/// Messages older than this (in days) are eligible to have their embedding
/// dropped, unless protected by the per-conversation keep-recent floor.
const DEFAULT_RETENTION_DAYS: i32 = 90;
/// Always retain embeddings for the most recent N messages of each
/// conversation, regardless of age, so active threads keep semantic recall.
const DEFAULT_KEEP_RECENT: i64 = 50;

/// Parse `EMBEDDING_RETENTION_DAYS`. Falls back to the default for missing,
/// unparseable, or non-positive values. Typed `i32` to match the
/// `make_interval(days => $1::int)` bind in `purge_stale_embeddings`.
fn parse_retention_days(raw: Option<String>) -> i32 {
    raw.and_then(|s| s.trim().parse::<i32>().ok())
        .filter(|&d| d >= 1)
        .unwrap_or(DEFAULT_RETENTION_DAYS)
}

/// Parse `EMBEDDING_RETENTION_KEEP_RECENT`. Falls back to the default for
/// missing, unparseable, or negative values. Zero is allowed and means
/// "no per-conversation floor".
fn parse_keep_recent(raw: Option<String>) -> i64 {
    raw.and_then(|s| s.trim().parse::<i64>().ok())
        .filter(|&n| n >= 0)
        .unwrap_or(DEFAULT_KEEP_RECENT)
}

/// Read embedding-retention configuration from the environment, returning
/// `(retention_days, keep_recent)`.
pub fn embedding_retention_config() -> (i32, i64) {
    (
        parse_retention_days(std::env::var("EMBEDDING_RETENTION_DAYS").ok()),
        parse_keep_recent(std::env::var("EMBEDDING_RETENTION_KEEP_RECENT").ok()),
    )
}

/// Null out embeddings on messages older than `days` that are NOT among the
/// most recent `keep_recent` messages of their conversation. Idempotent: the
/// `embedding IS NOT NULL` guard means already-cleared rows are never rewritten,
/// so re-running affects zero rows. Only the `embedding` column is touched —
/// `message_text` and all metadata are preserved. Returns the rows updated.
pub async fn purge_stale_embeddings(
    db: &sqlx::PgPool,
    days: i32,
    keep_recent: i64,
) -> Result<u64, sqlx::Error> {
    let result = sqlx::query(
        r#"
        UPDATE chat_messages SET embedding = NULL
        WHERE id IN (
            SELECT id FROM (
                SELECT id,
                       row_number() OVER (
                           PARTITION BY conversation_id ORDER BY created_at DESC
                       ) AS rn,
                       created_at
                FROM chat_messages
                WHERE embedding IS NOT NULL
            ) ranked
            WHERE ranked.rn > $2
              AND ranked.created_at < NOW() - make_interval(days => $1::int)
        )
        "#,
    )
    .bind(days)
    .bind(keep_recent)
    .execute(db)
    .await?;
    Ok(result.rows_affected())
}

#[derive(Deserialize)]
pub struct ChatRequest {
    pub message: String,
    pub budget_id: Option<Uuid>,
    pub conversation_id: Option<Uuid>,
    pub locale: Option<String>,
}

#[derive(Serialize)]
pub struct ChatResponse {
    pub response: String,
    pub action_taken: Option<String>,
    pub budget_id: Option<Uuid>,
    pub conversation_id: Uuid,
    /// A deletion the user must confirm in the UI before it actually happens.
    /// Deletions are never executed inside the chat request — the assistant only
    /// resolves the target here, and the frontend performs the delete via the
    /// REST endpoint after the user confirms in a custom modal.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub pending_deletion: Option<PendingDeletion>,
    /// Advisory signal (#157): when `Some(true)`, the frontend opens the existing
    /// insights dialog. Non-mutating — set by the OPEN_INSIGHTS chat action, which
    /// changes no data and is never logged as a "System Update".
    #[serde(skip_serializing_if = "Option::is_none")]
    pub open_insights: Option<bool>,
    /// Advisory signal (#241): when `Some(true)`, the frontend opens the
    /// dedicated budgets list page. Non-mutating — set by the OPEN_BUDGETS_LIST
    /// chat action.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub open_budgets_list: Option<bool>,
    /// Advisory signal (nels#301): when `Some(true)`, the frontend navigates to the
    /// dedicated categories page. Non-mutating — set ONLY by the LIST_CATEGORIES chat
    /// action (never by CATEGORY_BALANCE, which also populates `categories_table_html`
    /// but must answer inline in the chat transcript instead of navigating away).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub open_categories_list: Option<bool>,
    /// Escaped HTML table of the active budget's categories: name, type, limit,
    /// current-period spend, remaining, plus a totals row. Set by BOTH the
    /// LIST_CATEGORIES chat action (#176, the full list) and the CATEGORY_BALANCE
    /// chat action (nels#282, a single row). The frontend renders it two ways
    /// depending on which action set it (see `open_categories_list` above):
    /// LIST_CATEGORIES's table is discarded here and re-fetched fresh by the
    /// dedicated Categories page (`CategoriesView.svelte`), while
    /// CATEGORY_BALANCE's table is attached to the chat message itself and
    /// rendered inline in the transcript (nels#301). Only ever holds
    /// backend-built table markup, never model free-text.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub categories_table_html: Option<String>,
    /// The Stripe Financial Connections session client_secret (#303), set ONLY
    /// by the LINK_BANK_ACCOUNT chat action. The frontend uses it to drive
    /// Stripe.js's `collectFinancialConnectionsAccounts` modal — there is no
    /// hosted-redirect URL for Financial Connections like there is for
    /// Checkout, so this is the one chat-response field that carries a secret
    /// value through to the client (it is single-use and expires quickly on
    /// Stripe's side, same trust model as a Checkout Session URL).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub financial_connections_client_secret: Option<String>,
    /// The GoCardless consent redirect URL (#320), set ONLY by LINK_BANK_ACCOUNT
    /// when it resolves to a GoCardless country. Unlike Stripe's client_secret
    /// (which drives a client-side SDK modal), GoCardless's flow is a full-page
    /// redirect — the frontend navigates the browser to this URL directly.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub bank_link_redirect_url: Option<String>,
    /// The Belvo widget access token (#322), set ONLY by LINK_BANK_ACCOUNT
    /// when it resolves to Mexico/Brazil. Belvo's flow is a client-side
    /// embeddable widget (unlike GoCardless's redirect and Stripe's own
    /// hosted modal) — the frontend uses this token to initialize
    /// `cdn.belvo.io`'s widget script inline in the chat surface.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub belvo_widget_access_token: Option<String>,
    /// The `belvo_link_sessions` row id the widget token above was minted
    /// for (#322) — the frontend sends this back, alongside the Belvo
    /// `link_id` the widget's success callback returns, to
    /// `POST /budgets/:id/belvo/complete`.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub belvo_link_session_id: Option<Uuid>,
    /// The Plaid Link token (nels#321), set ONLY by LINK_BANK_ACCOUNT when it
    /// resolves to Canada/Plaid. The frontend opens the Plaid Link modal with
    /// this token, mirroring how financial_connections_client_secret drives
    /// Stripe.js's modal — Plaid Link is a client-side modal too, not a
    /// redirect, so it does NOT reuse bank_link_redirect_url.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub plaid_link_token: Option<String>,
    /// The plaid_link_sessions row id returned alongside plaid_link_token
    /// (anti-replay — see plaid.rs::create_link_token, and Belvo's own
    /// belvo_link_session_id above for the identical precedent) — the
    /// frontend must round-trip this back to POST .../plaid/complete
    /// alongside the public_token Plaid Link's onSuccess callback supplies.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub plaid_link_session_id: Option<Uuid>,
    /// A category choice the user must resolve before an un-categorized
    /// transaction is logged (#376). Set by ADD_TRANSACTION when the assistant
    /// would otherwise invent a brand-new category: instead of logging, it
    /// offers the user's existing expense categories as chips. The transaction
    /// is created only once the frontend calls POST /transactions/finalize.
    /// Mirrors `pending_deletion`'s propose-then-confirm round-trip.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub pending_category_choice: Option<PendingCategoryChoice>,
    /// Advisory signal (#376): when `Some(true)`, the frontend navigates to the
    /// dedicated transactions page. Non-mutating — set by an UNSCOPED
    /// LIST_TRANSACTIONS chat action (mirrors `open_categories_list`).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub open_transactions_list: Option<bool>,
    /// Advisory signal (nels#469): when `Some(true)`, the frontend navigates to
    /// the dedicated retirement planner route. Non-mutating — set ONLY by the
    /// RETIREMENT_PROJECTION chat action, and only when the projection actually
    /// computed (a refused turn stays in chat with its message, like
    /// `open_categories_list`).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub open_retirement: Option<bool>,
    /// The structured retirement projection (nels#467), set ONLY by the
    /// RETIREMENT_PROJECTION chat action.
    ///
    /// The card in `response` is already rendered for today's chat surface;
    /// this is the same projection as DATA, so #469 can draw the real dial,
    /// band and stacked bar without re-running the engine or re-deriving a
    /// single figure from the card's text. Non-mutating — a projection reads
    /// the profile and computes; it writes nothing and is never logged as a
    /// "System Update".
    #[serde(skip_serializing_if = "Option::is_none")]
    pub retirement_projection: Option<crate::retirement_projection::Projection>,
}

/// A category choice offered when the assistant would auto-create a brand-new
/// category for an un-categorized transaction (#376). The transaction is NOT
/// logged when this is returned; the frontend resolves it via finalize.
#[derive(Serialize)]
pub struct PendingCategoryChoice {
    pub budget_id: Uuid,
    pub amount: f64,
    pub description: String,
    /// The name the assistant proposed for a new category (the "Create new …"
    /// chip label and the `new_category_name` finalize value).
    pub proposed_new_name: String,
    /// Existing expense (non-mirror) categories, most-recently-used first,
    /// capped at 6.
    pub candidates: Vec<CategoryChoiceOption>,
}

/// One selectable existing category in a `PendingCategoryChoice` (#376).
#[derive(Serialize)]
pub struct CategoryChoiceOption {
    pub id: Uuid,
    pub name: String,
}

/// The core #376 decision, factored out so it is unit-testable without a DB.
/// Offer a category choice (instead of logging) only when: there is NO exact
/// (case-insensitive) match for the proposed name, the user did NOT explicitly
/// name the category (so we'd be inventing one), AND there is at least one
/// existing candidate to offer. Otherwise the ADD path logs as before (matched,
/// explicitly-named-new, or nothing-to-choose-from → silent auto-create).
fn should_offer_category_choice(
    has_exact_match: bool,
    explicit_category: bool,
    candidate_count: usize,
) -> bool {
    !has_exact_match && !explicit_category && candidate_count > 0
}

/// A deletion proposed by the assistant, awaiting explicit user confirmation.
#[derive(Serialize)]
pub struct PendingDeletion {
    pub kind: String, // "category" | "budget" | "transaction"
    pub id: Uuid,
    pub name: String,
    /// The budget the category/transaction belongs to (needed for the REST
    /// delete URL). `None` for budget deletions.
    pub budget_id: Option<Uuid>,
}

#[derive(Serialize)]
pub struct ChatHistoryItem {
    pub id: Uuid,
    pub sender: String,
    pub message_text: String,
    pub created_at: DateTime<Utc>,
}

