    // #257: rule 1 (ADD_TRANSACTION) must flag a dictation-mangled, ambiguous
    // amount and route to action NONE instead of logging it. Pure string
    // assertions over the prompt constant — no DB, no network, no live LLM
    // (there is no Gemini test harness in this repo); this is a content/
    // regression guard on the prompt text itself, not a behavioral test of
    // what Gemini actually does with it.
    #[test]
    fn add_transaction_rule_flags_ambiguous_dictated_amounts() {
        assert!(
            ADD_TRANSACTION_RULE.contains("AMBIGUOUS AMOUNTS"),
            "rule 1 must define an AMBIGUOUS AMOUNTS check"
        );
        assert!(
            ADD_TRANSACTION_RULE.contains("oh'/'o' (meaning zero)"),
            "rule 1 must call out the spoken oh/o -> zero dictation failure mode"
        );
        assert!(
            ADD_TRANSACTION_RULE.contains("set 'action' to 'NONE' instead"),
            "rule 1 must route ambiguous amounts to action NONE instead of ADD_TRANSACTION"
        );
    }

    // #257 AC 2 ("Confirming the amount then logs the correct value"): a bare
    // "yes" to a two-candidate clarifying question is ambiguous about WHICH
    // amount it confirms unless the rule requires a single primary
    // interpretation and defines how a plain affirmative resolves to it.
    #[test]
    fn add_transaction_rule_resolves_plain_confirmation_to_primary_amount() {
        assert!(
            ADD_TRANSACTION_RULE.contains("SINGLE most-likely interpretation"),
            "rule 1 must require stating one primary interpretation, not two equally-weighted options"
        );
        assert!(
            ADD_TRANSACTION_RULE.contains("plain affirmative"),
            "rule 1 must define how a bare 'yes' resolves to the primary amount"
        );
    }

    // #257 AC 3 ("Unambiguous amounts still log in one turn with no extra
    // prompt"): the happy path must remain explicitly stated, not just
    // implied by the absence of the ambiguity clause.
    #[test]
    fn add_transaction_rule_keeps_unambiguous_amounts_logging_directly() {
        assert!(
            ADD_TRANSACTION_RULE
                .contains("NOT ambiguous — log it directly with no extra confirmation step"),
            "rule 1 must explicitly state that a clearly-stated amount still logs directly"
        );
        assert!(
            ADD_TRANSACTION_RULE.contains("192 dollars and 4 cents"),
            "rule 1 must give an explicit unambiguous-amount example (a spoken cents figure)"
        );
    }

    // #257: rule 21 (EDIT_TRANSACTION) must apply the same ambiguity check to
    // a corrected amount, cross-referencing rule 1 rather than re-deriving
    // the heuristic (avoids prompt bloat / drift between two descriptions of
    // the same rule).
    #[test]
    fn edit_transaction_rule_flags_ambiguous_amounts_and_cross_references_rule_1() {
        assert!(
            EDIT_TRANSACTION_RULE.contains("AMBIGUOUS AMOUNTS"),
            "rule 21 must reference the AMBIGUOUS AMOUNTS check"
        );
        assert!(
            EDIT_TRANSACTION_RULE.contains("rule 1"),
            "rule 21 must cross-reference rule 1's heuristic rather than repeat it"
        );
        assert!(
            EDIT_TRANSACTION_RULE.contains("set 'action' to 'NONE'"),
            "rule 21 must route an ambiguous corrected amount to action NONE instead of EDIT_TRANSACTION"
        );
        assert!(
            EDIT_TRANSACTION_RULE.contains("apply the edit via 'action': 'EDIT_TRANSACTION'"),
            "rule 21 must explicitly instruct applying the edit (not just acknowledging) once the amount is confirmed on the user's next turn"
        );
    }

    // #302 AC ("An ambiguous/garbled amount (voice dictation) gets the same
    // confirm-before-acting flow as ADD_TRANSACTION/EDIT_TRANSACTION"): rule 20d
    // must reference the SAME ambiguity check as rule 1, mirroring
    // edit_transaction_rule_flags_ambiguous_amounts_and_cross_references_rule_1
    // above rather than repeating rule 1's heuristic inline.
    #[test]
    fn category_affordability_rule_flags_ambiguous_amounts_and_cross_references_rule_1() {
        assert!(
            CATEGORY_AFFORDABILITY_RULE.contains("AMBIGUOUS AMOUNTS"),
            "rule 20d must reference the AMBIGUOUS AMOUNTS check"
        );
        assert!(
            CATEGORY_AFFORDABILITY_RULE.contains("rule 1"),
            "rule 20d must cross-reference rule 1's heuristic rather than repeat it"
        );
        assert!(
            CATEGORY_AFFORDABILITY_RULE.contains("set 'action' to 'NONE'"),
            "rule 20d must route an ambiguous amount to action NONE instead of CATEGORY_AFFORDABILITY"
        );
        assert!(
            CATEGORY_AFFORDABILITY_RULE.contains("CATEGORY_AFFORDABILITY"),
            "rule 20d must actually name the CATEGORY_AFFORDABILITY action"
        );
        assert!(
            CATEGORY_AFFORDABILITY_RULE.contains("no dollar amount"),
            "rule 20d must instruct a clarifying 'how much?' question when no amount is given"
        );
    }

    // #364 (follow-up to #359): rule 20e must teach the model to READ the
    // auto-imported marker already present in the RECENT TRANSACTIONS context,
    // so it never claims it cannot tell which transactions were imported.
    // Prompt-content test, mirroring the neighbor rule tests above.
    #[test]
    fn recent_imported_marker_rule_teaches_reading_the_marker() {
        assert!(
            RECENT_IMPORTED_MARKER_RULE.contains("imported from"),
            "rule 20e must key off the literal 'imported from' marker text"
        );
        assert!(
            RECENT_IMPORTED_MARKER_RULE.contains("MANUALLY"),
            "rule 20e must explain unmarked lines were entered MANUALLY"
        );
        assert!(
            RECENT_IMPORTED_MARKER_RULE.contains("NEVER say you cannot tell"),
            "rule 20e must forbid claiming it cannot tell which transactions were imported"
        );
        assert!(
            RECENT_IMPORTED_MARKER_RULE
                .contains("name each imported transaction with its source account"),
            "rule 20e must instruct naming each imported transaction with its source account"
        );
        assert!(
            RECENT_IMPORTED_MARKER_RULE.contains("most recent"),
            "rule 20e must clarify RECENT TRANSACTIONS shows only the most recent rows, not full history"
        );
        assert!(
            RECENT_IMPORTED_MARKER_RULE.contains("SEARCH_TRANSACTIONS"),
            "rule 20e must offer SEARCH_TRANSACTIONS for completeness-oriented questions"
        );
        assert!(
            RECENT_IMPORTED_MARKER_RULE.contains("not the 🔗 icon"),
            "rule 20e must tell the model to detect imports by text, not the 🔗 glyph"
        );
        // Distinct zero-imports branch: when nothing in the window is marked, the
        // correct answer is a confident "none" — NOT the "cannot tell" hedge #364
        // fixes. Guard that branch explicitly so a prompt edit can't drop it.
        assert!(
            RECENT_IMPORTED_MARKER_RULE
                .contains("none of their recent transactions are auto-imported"),
            "rule 20e must tell the model to say 'none' (confidently) when no row carries the marker"
        );
        // Answer-routing half of the "answer directly" facet: the read is served
        // from existing context, so the rule must route to action NONE and answer
        // straight from the markers rather than triggering a DB action.
        assert!(
            RECENT_IMPORTED_MARKER_RULE.contains("set 'action' to 'NONE'"),
            "rule 20e must route imported-vs-manual questions to action NONE"
        );
        assert!(
            RECENT_IMPORTED_MARKER_RULE.contains("DIRECTLY"),
            "rule 20e must tell the model to answer DIRECTLY from the in-context markers"
        );
        // Renderer<->rule contract: the rule instructs the model to key off the
        // literal "imported from" token, and `imported_source_suffix` (#359) is
        // what actually emits that token into the RECENT TRANSACTIONS context.
        // Assert the emitter still produces the exact token the rule depends on,
        // so a future rename of the marker text can't silently de-couple the two
        // and reintroduce the #364 "I can't tell which were imported" failure.
        {
            use uuid::Uuid;
            let suffix =
                imported_source_suffix(Some(Uuid::new_v4()), Some("Chase Checking"), None, Some("1234"));
            assert!(
                suffix.contains("imported from"),
                "imported_source_suffix must still emit the 'imported from' token rule 20e keys off (renderer/rule drift guard)"
            );
        }
    }

    // UsageMetadata deserialization + the None->0 coercion used when recording
    // token usage. Pure unit test: no DB, no network.
    #[test]
    fn usage_metadata_deserializes_and_coerces_missing_to_zero() {
        // A response with NO usageMetadata field -> usage_metadata is None, and
        // the recorded token values coerce to 0.
        let json = r#"{"candidates":[{"content":{"parts":[{"text":"hi"}]}}]}"#;
        let resp: GeminiChatResponse = serde_json::from_str(json).expect("must parse");
        assert!(resp.usage_metadata.is_none(), "absent usageMetadata -> None");
        let usage = resp.usage_metadata.as_ref();
        assert_eq!(usage.and_then(|u| u.prompt_token_count).unwrap_or(0), 0);
        assert_eq!(usage.and_then(|u| u.candidates_token_count).unwrap_or(0), 0);
        assert_eq!(usage.and_then(|u| u.total_token_count).unwrap_or(0), 0);

        // Partial UsageMetadata: only totalTokenCount present. Missing fields
        // deserialize to None and coerce to 0; total parses to Some(42).
        let partial: UsageMetadata =
            serde_json::from_str(r#"{"totalTokenCount": 42}"#).expect("must parse");
        assert_eq!(partial.prompt_token_count, None);
        assert_eq!(partial.candidates_token_count, None);
        assert_eq!(partial.thoughts_token_count, None);
        assert_eq!(partial.total_token_count, Some(42));
        assert_eq!(partial.prompt_token_count.unwrap_or(0), 0);
        assert_eq!(partial.candidates_token_count.unwrap_or(0), 0);
        assert_eq!(partial.thoughts_token_count.unwrap_or(0), 0);

        // Full UsageMetadata: all camelCase fields parse via the rename,
        // including thoughtsTokenCount from Gemini 2.5 thinking models.
        let full: UsageMetadata = serde_json::from_str(
            r#"{"promptTokenCount":10,"candidatesTokenCount":20,"thoughtsTokenCount":5,"totalTokenCount":35}"#,
        )
        .expect("must parse");
        assert_eq!(full.prompt_token_count, Some(10));
        assert_eq!(full.candidates_token_count, Some(20));
        assert_eq!(full.thoughts_token_count, Some(5));
        assert_eq!(full.total_token_count, Some(35));
    }

    // vector_to_string formats a f32 slice as pgvector's bracketed, comma-
    // separated literal. Pure unit test (no DB), so it runs in the normal CI
    // pass unlike the #[ignore] DB tests.
    #[test]
    fn vector_to_string_formats_pgvector_literal() {
        // Empty slice -> just the brackets, no stray comma.
        assert_eq!(vector_to_string(&[]), "[]");
        // Single element -> no leading/trailing comma.
        assert_eq!(vector_to_string(&[1.0]), "[1]");
        // A few elements -> comma-separated inside the brackets.
        assert_eq!(vector_to_string(&[1.0, 2.0, 3.0]), "[1,2,3]");
    }

    #[test]
    fn ai_response_parses_rollover_flag() {
        let json = r#"{"thought":"t","action":"UPDATE_BUDGET","action_params":{"rollover":true},"response_text":"ok"}"#;
        let parsed: AiStructuredResponse = serde_json::from_str(json).expect("must parse");
        assert_eq!(parsed.action_params.unwrap().rollover, Some(true));
        let json_absent = r#"{"thought":"t","action":"NONE","action_params":{},"response_text":"ok"}"#;
        let parsed2: AiStructuredResponse = serde_json::from_str(json_absent).expect("must parse");
        assert_eq!(parsed2.action_params.unwrap().rollover, None);
    }

