        let json = r#"{"thought":"t","action":"CREATE_BUDGET","action_params":{"budget_name":"Kitchen Remodel","budget_type":"project"},"response_text":"ok"}"#;
        let parsed: AiStructuredResponse = serde_json::from_str(json).expect("must parse");
