    #[test]
    fn ai_response_parses_archive_budget_action() {
        let json = r#"{"thought":"t","action":"ARCHIVE_BUDGET","action_params":{"target_budget_name":"Kitchen Remodel"},"response_text":"ok"}"#;
        let parsed: AiStructuredResponse = serde_json::from_str(json).expect("must parse");
        assert_eq!(parsed.action, "ARCHIVE_BUDGET");
        assert_eq!(
            parsed.action_params.unwrap().target_budget_name,
            Some("Kitchen Remodel".to_string())
        );
    }

