    #[test]
    fn ai_response_parses_rollup_budget_action() {
        // ROLLUP_BUDGET carries both the parent (target_budget_name) and the child
        // (child_budget_name); both must round-trip (#52).
        let json = r#"{"thought":"t","action":"ROLLUP_BUDGET","action_params":{"target_budget_name":"Household","child_budget_name":"Groceries"},"response_text":"ok"}"#;
        let parsed: AiStructuredResponse = serde_json::from_str(json).expect("must parse");
        assert_eq!(parsed.action, "ROLLUP_BUDGET");
        let p = parsed.action_params.unwrap();
        assert_eq!(p.target_budget_name, Some("Household".to_string()));
        assert_eq!(p.child_budget_name, Some("Groceries".to_string()));
    }

