    #[test]
    fn offline_rollup_action_routes_unroll_before_rollup() {
        // "unroll" can contain "roll", so UNROLLUP must be matched before ROLLUP.
        assert_eq!(offline_rollup_action("please unroll this budget"), Some("UNROLLUP_BUDGET"));
        assert_eq!(offline_rollup_action("roll up groceries into household"), Some("ROLLUP_BUDGET"));
        assert_eq!(offline_rollup_action("combine budget kids into family"), Some("ROLLUP_BUDGET"));
        // Must NOT collide with per-budget rollover (#47), which says "roll over".
        assert_eq!(offline_rollup_action("roll over my unused budget"), None);
        assert_eq!(offline_rollup_action("show my spending"), None);
    }

    #[test]
    fn offline_amount_mode_routes_fixed_and_derived() {
        // #116: 'fixed' and 'derived' intents route to the right mode.
        assert_eq!(offline_amount_mode("set this budget to a fixed $2000"), Some("fixed"));
        assert_eq!(offline_amount_mode("make this a fixed budget"), Some("fixed"));
        assert_eq!(offline_amount_mode("derive this budget's amount from its categories"), Some("derived"));
        assert_eq!(offline_amount_mode("base this budget on its categories"), Some("derived"));
        assert_eq!(offline_amount_mode("derive its amount from the categories"), Some("derived"));
        // More verb-led 'fixed' phrasings route correctly.
        assert_eq!(offline_amount_mode("switch to a fixed amount"), Some("fixed"));
        assert_eq!(offline_amount_mode("make it a fixed budget"), Some("fixed"));
        // Must NOT collide with rollover ("roll over") or rollup ("roll up").
        assert_eq!(offline_amount_mode("roll over my unused budget"), None);
        assert_eq!(offline_amount_mode("roll up groceries into household"), None);
        assert_eq!(offline_amount_mode("show my spending"), None);
        // SAFETY (#116): plain informational sentences must NOT misroute into a
        // destructive UPDATE_BUDGET. These read like ordinary English, not an
        // intent to change amount_mode, so they must return None.
        assert_eq!(offline_amount_mode("i have a fixed budget"), None);
        assert_eq!(offline_amount_mode("show my fixed budget summary"), None);
        assert_eq!(offline_amount_mode("how much is coming from categories?"), None);
        assert_eq!(offline_amount_mode("spending from categories a and b"), None);
        // Passive "derived amount" / "from its categories" noun phrases are
        // informational, not an intent to switch mode — they must NOT route.
        assert_eq!(offline_amount_mode("what is the derived amount?"), None);
        assert_eq!(offline_amount_mode("use the derived amount instead"), None);
        assert_eq!(offline_amount_mode("how is spending tracked from its categories?"), None);
        // "to a fixed <noun>" in ordinary speech must NOT misroute; only the
        // "$"/"amount" qualified forms are an intent to set a fixed amount.
        assert_eq!(offline_amount_mode("compare my spending to a fixed benchmark"), None);
        assert_eq!(offline_amount_mode("i switched back to a fixed schedule"), None);
        assert_eq!(offline_amount_mode("set this budget to a fixed amount of $2000"), Some("fixed"));
    }

    #[test]
    fn offline_budget_strategy_routes_known_phrases() {
        assert_eq!(offline_budget_strategy("create a zero-based budget for vacation"), Some("zero_based"));
        assert_eq!(offline_budget_strategy("create a zero based budget"), Some("zero_based"));
        assert_eq!(offline_budget_strategy("make a limit budget for groceries"), Some("limit_spent_remaining"));
        assert_eq!(offline_budget_strategy("create a traditional budget"), Some("limit_spent_remaining"));
        assert_eq!(offline_budget_strategy("create a limit spent remaining budget"), Some("limit_spent_remaining"));

        // No explicit phrase -> None (must ask, never silently default)
        assert_eq!(offline_budget_strategy("create a budget called groceries"), None);
        assert_eq!(offline_budget_strategy("create a monthly budget of $500"), None);
        assert_eq!(offline_budget_strategy("show my budget summary"), None);
    }

    #[test]
    fn offline_archive_action_routes_unarchive_before_archive() {
        // "unarchive budget" contains the substring "archive budget"; the helper
        // must match UNARCHIVE first so an unarchive request never routes to
        // ARCHIVE. This pins the ordering invariant the offline router relies on.
        assert_eq!(
            offline_archive_action("please unarchive budget now"),
            Some("UNARCHIVE_BUDGET")
        );
        assert_eq!(
            offline_archive_action("please archive budget now"),
            Some("ARCHIVE_BUDGET")
        );
        assert_eq!(offline_archive_action("show my spending"), None);
    }

    #[test]
    fn offline_privacy_action_routes_delete_before_export() {
        // DELETE is checked before EXPORT and the multi-word phrases come first so
        // a generic word never shadows them. These cases pin that contract.
        assert_eq!(
            offline_privacy_action("please delete my account"),
            Some("DELETE_ACCOUNT")
        );
        assert_eq!(
            offline_privacy_action("i want to export my data"),
            Some("EXPORT_DATA")
        );
        assert_eq!(
            offline_privacy_action("download my data please"),
            Some("EXPORT_DATA")
        );
        // "delete my budget" must NOT be account deletion — proves the
        // account-delete match isn't over-greedy on the bare word "delete".
        assert_eq!(offline_privacy_action("delete my budget"), None);
        assert_eq!(offline_privacy_action("show my budgets"), None);
        // A message containing BOTH delete-account and export must resolve to
        // DELETE_ACCOUNT because delete is checked first.
        assert_eq!(
            offline_privacy_action("delete my account and export my data"),
            Some("DELETE_ACCOUNT")
        );
    }

    #[test]
    fn offline_retirement_action_routes_write_intents_only() {
        // nels#465. The offline matcher ROUTES to the write action; it never
        // populates action_params, so the arm always reprompts for the fields.
        assert_eq!(
            offline_retirement_action("set up my retirement profile"),
            Some("SET_RETIREMENT_PROFILE")
        );
        assert_eq!(
            offline_retirement_action("i want to retire at 62"),
            Some("SET_RETIREMENT_PROFILE")
        );
        assert_eq!(
            offline_retirement_action("save my retirement profile"),
            Some("SET_RETIREMENT_PROFILE")
        );
        // CRITICAL negative: this is a READ question. Routing it to a Pro-gated
        // WRITE action would answer a question with a paywall message.
        assert_eq!(offline_retirement_action("what is my retirement age"), None);
        assert_eq!(offline_retirement_action("what's my retirement profile"), None);
        assert_eq!(offline_retirement_action("when can i retire at my savings rate"), None);
        // Unrelated messages never trigger a Pro-gated write.
        assert_eq!(offline_retirement_action(""), None);
        assert_eq!(offline_retirement_action("delete my budget"), None);
        assert_eq!(offline_retirement_action("show my categories"), None);
        // "save for retirement" is a GOAL phrasing, not a profile write.
        assert_eq!(offline_retirement_action("i want to save for retirement"), None);

        // nels#466. Social Security wording is specific enough to claim on its
        // own; no other offline matcher wants it.
        assert_eq!(
            offline_retirement_action("set my social security benefit"),
            Some("SET_RETIREMENT_PROFILE")
        );
        assert_eq!(
            offline_retirement_action("my social security statement says 2400 a month"),
            Some("SET_RETIREMENT_PROFILE")
        );
        assert_eq!(
            offline_retirement_action("i plan to claim social security at 70"),
            Some("SET_RETIREMENT_PROFILE")
        );
        // Still a READ question, so still not a Pro-gated write. The
        // `is_question` guard has to survive the new keyword.
        assert_eq!(offline_retirement_action("how much social security will i get"), None);
        assert_eq!(offline_retirement_action("what is my social security benefit"), None);
    }

    #[test]
    fn offline_retirement_action_does_not_collide_with_sibling_matchers() {
        // Ordering discipline, mirroring
        // `offline_privacy_action_routes_delete_before_export`: the phrases this
        // matcher claims must not ALSO fire an earlier branch of the offline
        // if/else chain, or the retirement arm would be unreachable for them.
        for msg in [
            "set up my retirement profile",
            "i want to retire at 62",
            "save my retirement profile",
            // nels#466 phrasings, carried through the same discipline.
            "set my social security benefit",
            "log my social security benefit of 2400",
            "i plan to claim social security at 70",
        ] {
            // nels#466. The INLINE branches of the chain matter more than the
            // helpers here, because they are broader. `contains("log")` /
            // `contains("spent")` sits directly ABOVE the retirement arm and
            // would otherwise claim "log my social security benefit" and invent
            // a $15 "Utilities" transaction. The arm now carries an
            // `offline_retirement_action(..).is_none()` guard, and this asserts
            // the guard is what makes these messages reachable — not luck about
            // which words they happen to contain.
            if msg.contains("log") || msg.contains("spent") || msg.contains("add transaction") {
                assert!(
                    offline_retirement_action(msg).is_some(),
                    "{msg} overlaps the ADD_TRANSACTION branch, so the retirement matcher MUST claim it \
                     or the guard cannot rescue it"
                );
            }
            // The goal branch (`contains("goal") || contains("save for")`) also
            // runs earlier; the matcher's own "save for" exclusion is what keeps
            // these two apart, so assert the overlap does not exist.
            assert!(
                !(msg.contains("goal") || msg.contains("save for") || msg.contains("saving for")),
                "{msg} would be claimed by the earlier goal branch"
            );
            assert_eq!(offline_rename(msg), None, "{msg} must not read as a budget rename");
            assert_eq!(
                offline_budgets_list_action(msg),
                None,
                "{msg} must not open the budgets page"
            );
            assert_eq!(
                offline_categories_action(msg),
                None,
                "{msg} must not render the categories table"
            );
            assert_eq!(
                offline_privacy_action(msg),
                None,
                "{msg} must not read as an export/delete-account request"
            );
            assert_eq!(
                offline_linked_accounts_action(msg),
                None,
                "{msg} must not read as a bank-linking request"
            );
            // nels#467. The projection matcher is the newest sibling and the
            // one most able to steal from this matcher, since every phrase here
            // contains a retirement word. Exactly one owner per phrase.
            assert_eq!(
                offline_retirement_projection_action(msg),
                None,
                "{msg} is a profile WRITE and must not also route to the projection READ"
            );
        }
    }

    /// The projection matcher's own claims, and the four exclusions that keep
    /// it from stealing a phrase somebody else already owns (nels#467).
    #[test]
    fn offline_retirement_projection_action_is_narrow_by_design() {
        // Claims: an unambiguous retirement read.
        assert_eq!(
            offline_retirement_projection_action("show my retirement projection"),
            Some("RETIREMENT_PROJECTION")
        );
        assert_eq!(
            offline_retirement_projection_action("retire"),
            Some("RETIREMENT_PROJECTION")
        );
        assert_eq!(
            offline_retirement_projection_action("will my savings last in retirement"),
            Some("RETIREMENT_PROJECTION")
        );

        // Exclusion 1 — BUDGET forecast semantics keep the forecast arm. These
        // are the phrases whose reply used to be the fabricated "$100.00".
        assert_eq!(offline_retirement_projection_action("forecast next month"), None);
        assert_eq!(
            offline_retirement_projection_action("what will i have left over next month"),
            None
        );
        // Exclusion 2 — a BARE projection word is the budget arm's, not ours.
        assert_eq!(offline_retirement_projection_action("show me a projection"), None);
        assert_eq!(offline_retirement_projection_action("projection next month"), None);

        // Exclusion 3 — CREATE_GOAL's phrasing.
        assert_eq!(offline_retirement_projection_action("save for retirement"), None);
        assert_eq!(offline_retirement_projection_action("saving for retirement"), None);

        // Exclusion 4 — interrogatives, mirroring the write matcher's guard.
        assert_eq!(offline_retirement_projection_action("when can i retire"), None);
        assert_eq!(offline_retirement_projection_action("how much will i have to retire on"), None);

        // And the write matcher keeps every phrase it claims.
        for write in [
            "set up my retirement profile",
            "i want to retire at 62",
            "set my social security benefit",
            "change my retirement assumptions",
        ] {
            assert_eq!(
                offline_retirement_projection_action(write),
                None,
                "{write} belongs to SET_RETIREMENT_PROFILE"
            );
            assert!(
                offline_retirement_action(write).is_some(),
                "{write} must still be claimed by the write matcher"
            );
        }
    }

    /// The two retirement matchers must partition their phrases, not overlap.
    ///
    /// Asserted as a property over both directions rather than as a list of
    /// cases, because the failure this guards against is a future keyword added
    /// to one matcher that silently starts shadowing the other.
    #[test]
    fn the_two_retirement_matchers_never_claim_the_same_phrase() {
        for msg in [
            "set up my retirement profile",
            "i want to retire at 62",
            "change my retirement assumptions",
            "set my social security benefit",
            "show my retirement projection",
            "retire",
            "will my savings last in retirement",
            "what is my retirement age",
            "save for retirement",
            "forecast next month",
            "show me a projection",
        ] {
            let write = offline_retirement_action(msg).is_some();
            let read = offline_retirement_projection_action(msg).is_some();
            assert!(
                !(write && read),
                "{msg} is claimed by BOTH retirement matchers — one of them must refuse it"
            );
        }
    }

    #[test]
    fn set_retirement_profile_rule_forbids_editorializing_and_the_country_collision() {
        // #454 decision 3: chat is the cheapest place to emit financial advice by
        // accident, so rule 21d must forbid recommending outright. Pinned by
        // `.contains(...)` the same way `add_transaction_rule_*` pins rule 1.
        assert!(SET_RETIREMENT_PROFILE_RULE.starts_with("21d."));
        assert!(
            SET_RETIREMENT_PROFILE_RULE.contains("Do NOT editorialize"),
            "rule 21d must forbid editorializing on the saved result"
        );
        assert!(
            SET_RETIREMENT_PROFILE_RULE.contains("employer_match_formula"),
            "rule 21d must say the employer match formula is not chat-settable in v1"
        );
        // The nested `retirement_profile.country` vs the flat LINK_BANK_ACCOUNT
        // `country` collision must be called out explicitly, or the model fills
        // the wrong field and the user is re-asked for something they just said.
        assert!(
            SET_RETIREMENT_PROFILE_RULE.contains("top-level 'country'"),
            "rule 21d must disambiguate the nested country from the bank-linking one"
        );
        // Units, so the model never sends 0.06 for "6 percent".
        assert!(SET_RETIREMENT_PROFILE_RULE.contains("PERCENT"));
        assert!(SET_RETIREMENT_PROFILE_RULE.contains("FRACTION"));
    }

    /// nels#466. The prompt rule must forbid the model INVENTING a Social
    /// Security figure, which is the likeliest way this feature emits a number
    /// the user believes came from the government.
    ///
    /// #454 decision 1 is binding: Nels does not estimate Social Security
    /// benefits. Chat is where that leaks, because a model asked "roughly how
    /// much will I get?" will happily produce a plausible dollar amount from its
    /// weights and the arm would then SAVE it as a user-entered statement figure.
    #[test]
    fn set_retirement_profile_rule_forbids_inventing_a_social_security_figure() {
        assert!(
            SET_RETIREMENT_PROFILE_RULE.contains("MUST NOT estimate"),
            "rule 21d must forbid estimating a Social Security benefit"
        );
        assert!(
            SET_RETIREMENT_PROFILE_RULE.contains("ssa.gov/myaccount"),
            "rule 21d must point the user at their own statement instead"
        );
        assert!(
            SET_RETIREMENT_PROFILE_RULE.contains("do not offer a ballpark"),
            "rule 21d must close the ballpark loophole"
        );
        // The three settable field names, so a rename cannot silently orphan the
        // instructions the model is given.
        for field in ["ss_monthly_benefit", "ss_benefit_at_age", "ss_claiming_age"] {
            assert!(SET_RETIREMENT_PROFILE_RULE.contains(field), "rule 21d must name {field}");
        }
        // And it must NOT invite the model to set the derived provenance column.
        assert!(
            SET_RETIREMENT_PROFILE_RULE.contains("MONTHLY dollar figure"),
            "rule 21d must state the scale — an annual figure here triples the projection"
        );
    }

    /// Rule 21e's prohibitions, mirroring the 21d test above.
    ///
    /// The stakes are higher here than on 21d, which is why this is pinned
    /// rather than left to review: 21d governs figures the USER supplied, while
    /// 21e governs figures WE computed. "You're behind, consider contributing
    /// more" attached to a projection is regulated investment advice, and it is
    /// the single most natural thing for a model to say about this output.
    #[test]
    fn retirement_projection_rule_forbids_editorializing_and_names_the_action() {
        assert!(RETIREMENT_PROJECTION_RULE.starts_with("21e."));
        assert!(
            RETIREMENT_PROJECTION_RULE.contains("RETIREMENT_PROJECTION"),
            "the rule must name the action string it routes to, or the model cannot use it"
        );
        assert!(
            RETIREMENT_PROJECTION_RULE.contains("READ-ONLY"),
            "the rule must say the action writes nothing"
        );
        assert!(
            RETIREMENT_PROJECTION_RULE.contains("Do NOT editorialize"),
            "rule 21e must carry 21d's no-editorializing prohibition"
        );
        // The specific advice shapes a model reaches for when handed a
        // projection. Each is named so the prohibition cannot be read narrowly.
        for forbidden in ["on track", "contribute more", "401k vs IRA", "shortfall"] {
            assert!(
                RETIREMENT_PROJECTION_RULE.contains(forbidden),
                "rule 21e must explicitly forbid advice of the '{forbidden}' shape"
            );
        }
        assert!(
            RETIREMENT_PROJECTION_RULE.contains("MUST NOT produce any retirement figure"),
            "rule 21e must forbid the model inventing a figure of its own"
        );
        // It must route a "set up my profile" request elsewhere rather than
        // asking for details it has no parameters to carry.
        assert!(
            RETIREMENT_PROJECTION_RULE.contains("SET_RETIREMENT_PROFILE"),
            "rule 21e must hand profile setup back to 21d"
        );
    }

    /// The card is fixed backend text and must REPORT without ADVISING.
    ///
    /// Pure — no DB, no engine run — because it asserts on the markup builder
    /// with a hand-built `Projection`. The compliance property is a property of
    /// this function's output, so this is where it is enforceable.
    #[test]
    fn projection_card_reports_every_figure_and_advises_nothing() {
        use crate::retirement_projection::*;

        let p = Projection {
            deterministic_monthly_income: 5_500.0,
            percent_of_goal: Some(1.24),
            percentile_band: PercentileBand {
                p10: 4_000.0,
                p25: 4_800.0,
                p50: 5_500.0,
                p75: 6_200.0,
                p90: 7_000.0,
            },
            success_rate: 0.87,
            income_sources: IncomeSources {
                own_savings: 2_500.0,
                employer_contributions: 900.0,
                social_security: 2_100.0,
                other_assets: 0.0,
                gap: 0.0,
            },
            depletion_age: None,
            depletes: false,
            assumptions: sample_assumptions(),
        };

        let card = build_projection_card_html(&p);

        // Every headline figure reaches the user.
        assert!(card.contains("$5,500"), "the headline must appear: {card}");
        assert!(card.contains("124%"), "percent-of-goal must appear and may exceed 100: {card}");
        assert!(card.contains("$4,000") && card.contains("$7,000"), "the band must appear: {card}");
        assert!(card.contains("87%"), "the success rate must appear: {card}");
        assert!(card.contains("$2,100"), "the Social Security segment must appear: {card}");
        assert!(card.contains("not financial advice"), "the disclosure must appear: {card}");

        // And nothing advises. These are the phrases rule 21e forbids the model
        // from producing; the backend card must not produce them either.
        let lower = card.to_lowercase();
        for banned in [
            "on track", "behind", "ahead of", "you should", "consider ", "recommend",
            "healthy", "worrying", "aggressive", "conservative", "optimistic",
        ] {
            assert!(!lower.contains(banned), "the card must not editorialize with '{banned}': {card}");
        }
    }

    /// A surviving plan must SAY it survives. Reporting only the depleted case
    /// would leave a healthy projection looking like the check never ran.
    #[test]
    fn projection_card_states_longevity_in_both_directions() {
        use crate::retirement_projection::*;

        let base = Projection {
            deterministic_monthly_income: 3_000.0,
            percent_of_goal: Some(0.6),
            percentile_band: PercentileBand {
                p10: 2_000.0, p25: 2_500.0, p50: 3_000.0, p75: 3_500.0, p90: 4_000.0,
            },
            success_rate: 0.2,
            income_sources: IncomeSources {
                own_savings: 1_500.0,
                employer_contributions: 500.0,
                social_security: 1_000.0,
                other_assets: 0.0,
                gap: 2_000.0,
            },
            depletion_age: Some(81),
            depletes: true,
            assumptions: sample_assumptions(),
        };

        let depleting = build_projection_card_html(&base);
        assert!(depleting.contains("run out at age"), "{depleting}");
        assert!(depleting.contains("81"), "the depletion age must be stated: {depleting}");
        assert!(depleting.contains("$2,000"), "the shortfall segment must be stated: {depleting}");

        let surviving = build_projection_card_html(&Projection {
            depletion_age: None,
            depletes: false,
            ..base
        });
        assert!(surviving.contains("last to age"), "{surviving}");
        assert!(!surviving.contains("run out at age"), "{surviving}");
    }

    /// A zero target income must not render as "0% of your target" — that is a
    /// ratio nobody computed. The card names the reason instead.
    #[test]
    fn projection_card_declines_to_invent_a_percentage_without_a_target() {
        use crate::retirement_projection::*;

        let card = build_projection_card_html(&Projection {
            deterministic_monthly_income: 1_000.0,
            percent_of_goal: None,
            percentile_band: PercentileBand {
                p10: 1_000.0, p25: 1_000.0, p50: 1_000.0, p75: 1_000.0, p90: 1_000.0,
            },
            success_rate: 1.0,
            income_sources: IncomeSources {
                own_savings: 1_000.0,
                employer_contributions: 0.0,
                social_security: 0.0,
                other_assets: 0.0,
                gap: 0.0,
            },
            depletion_age: None,
            depletes: false,
            assumptions: sample_assumptions(),
        });

        assert!(card.contains("no target income set"), "{card}");
        // The precise failure mode: a cell whose entire content is "0%". A bare
        // `contains("0%")` would match the "100%" success rate on the row below
        // and fail a correct card.
        assert!(
            !card.contains("<td>0%</td>"),
            "a missing target must not render as zero percent: {card}"
        );
    }

