    #[test]
    fn new_category_limit_offer_mentions_category_amount_and_limit() {
        let s = super::format_new_category_limit_offer("Mortgage", 2932.92, Some("monthly"));
        assert!(s.contains("Mortgage"), "offer names the category: {s}");
        assert!(s.contains("$2932.92"), "offer states the amount: {s}");
        assert!(s.to_lowercase().contains("monthly limit"), "offer mentions monthly limit: {s}");
        let s2 = super::format_new_category_limit_offer("Misc", 10.0, None);
        assert!(s2.to_lowercase().contains("limit"), "generic offer still mentions limit: {s2}");
        assert!(s2.contains("Misc") && s2.contains("$10.00"), "generic offer names category+amount: {s2}");
        // The other period words map correctly (yearly aliases "annually").
        let q = super::format_new_category_limit_offer("Tax", 500.0, Some("quarterly"));
        assert!(q.to_lowercase().contains("quarterly limit"), "quarterly maps: {q}");
        let y = super::format_new_category_limit_offer("Tax", 500.0, Some("yearly"));
        assert!(y.to_lowercase().contains("yearly limit"), "yearly maps: {y}");
        let a = super::format_new_category_limit_offer("Tax", 500.0, Some("annually"));
        assert!(a.to_lowercase().contains("yearly limit"), "annually aliases yearly: {a}");
    }

