    // ---- Chat-mutation access control (issue #18) ----------------------------
    // SHARE_BUDGET (and the other whole-budget actions) must be owner-only,
    // mirroring the `perm != Permission::Owner` guards on the REST handlers.
    // A view/edit collaborator must NOT be able to drive a share via chat.

    // Test-only convenience: resolve an action's requirement and apply it in one
    // step, mirroring how `chat_endpoint` pairs the two helpers.
    fn action_authorized(action: &str, active_perm: &Permission) -> bool {
        is_chat_action_authorized(&required_perm_for_action(action), active_perm)
    }

    #[test]
    fn share_budget_requires_owner_permission() {
        // The HTTP share_budget handler rejects anyone who isn't Owner; the chat
        // path must agree, including on the level a collaborator might request.
        assert_eq!(
            required_perm_for_action("SHARE_BUDGET"),
            Some(Permission::Owner)
        );
    }

    #[test]
    fn non_owner_cannot_share_budget_via_chat() {
        // View AND Edit collaborators are both refused — sharing is owner-only.
        assert!(
            !action_authorized("SHARE_BUDGET", &Permission::View),
            "view collaborator must not be allowed to SHARE_BUDGET"
        );
        assert!(
            !action_authorized("SHARE_BUDGET", &Permission::Edit),
            "edit collaborator must not be allowed to SHARE_BUDGET"
        );
        assert!(
            !action_authorized("SHARE_BUDGET", &Permission::None),
            "no-access user must not be allowed to SHARE_BUDGET"
        );
    }

    #[test]
    fn owner_can_share_budget_via_chat() {
        assert!(
            action_authorized("SHARE_BUDGET", &Permission::Owner),
            "owner must be allowed to SHARE_BUDGET"
        );
    }

