    // End-to-end proof of the owner-only SHARE_BUDGET gate (issue #18) through the
    // real `chat_endpoint`, with the offline router (no GEMINI_API_KEY) routing a
    // "share ... <email>" message to action SHARE_BUDGET. A view AND an edit
    // collaborator must both be REFUSED (no budget_shares row inserted, refusal in
    // the response), while the owner can still share (regression). Mirrors the
    // `perm != Permission::Owner` guard on the HTTP `share_budget` handler.
    //
    // Runs only on demand against the local docker-compose Postgres:
    //   podman-compose up -d
    //   cd backend && cargo test -- --ignored
    #[tokio::test]
    #[ignore = "requires Postgres + pgvector; run via: cargo test -- --ignored"]
    async fn chat_share_budget_is_owner_only() {
        // #269: see GEMINI_ENV_LOCK's doc comment — every GEMINI_API_KEY-touching test must hold this.
        let _gemini_env = GEMINI_ENV_LOCK.lock().unwrap_or_else(|e| e.into_inner());
        // Force the offline router so routing is deterministic and no network
        // call is made. Restore the prior value on exit so we don't perturb any
        // other test that might read GEMINI_API_KEY in this process (env is
        // process-global; these DB tests run only under --ignored).
        struct EnvGuard(Option<String>);
        impl Drop for EnvGuard {
            fn drop(&mut self) {
                match &self.0 {
                    Some(v) => std::env::set_var("GEMINI_API_KEY", v),
                    None => std::env::remove_var("GEMINI_API_KEY"),
                }
            }
        }
        let _env_guard = EnvGuard(std::env::var("GEMINI_API_KEY").ok());
        std::env::remove_var("GEMINI_API_KEY");

        let url = std::env::var("DATABASE_URL").unwrap_or_else(|_| {
            "postgres://postgres:postgrespassword@localhost:6153/budget_rag".to_string()
        });
        let pool = sqlx::PgPool::connect(&url).await.expect("connect to test db");
        // chat_endpoint does not use the cipher; a fixed 32-byte key is fine here.
        let cipher = std::sync::Arc::new(
            crate::crypto::SecretCipher::new(&[7u8; 32]).expect("build test cipher"),
        );
        let state = AppState { db: pool.clone(), cipher, webauthn: std::sync::Arc::new(crate::passkeys::WebauthnRegistry::for_test()) };

        // Unique fixtures so the shared DB is never contaminated.
        let suffix = uuid::Uuid::new_v4();
        let owner_id = uuid::Uuid::new_v4();
        let viewer_id = uuid::Uuid::new_v4();
        let editor_id = uuid::Uuid::new_v4();
        let budget_id = uuid::Uuid::new_v4();
        let viewer_email = format!("viewer-{suffix}@example.test");
        let editor_email = format!("editor-{suffix}@example.test");
        // The third-party target a collaborator would try to (re-)share with.
        let target_email = format!("target-{suffix}@example.test");

        async fn seed_user(pool: &sqlx::PgPool, id: uuid::Uuid, email: &str) {
            sqlx::query("INSERT INTO users (id, email) VALUES ($1, $2)")
                .bind(id)
                .bind(email)
                .execute(pool)
                .await
                .expect("seed user");
        }
        seed_user(&pool, owner_id, &format!("owner-{suffix}@example.test")).await;
        seed_user(&pool, viewer_id, &viewer_email).await;
        seed_user(&pool, editor_id, &editor_email).await;

        // Owner's budget, set as the user's default so chat resolves it with no
        // explicit budget_id.
        sqlx::query(
            "INSERT INTO budgets (id, owner_id, name, time_frame, budget_limit, is_default) \
             VALUES ($1, $2, 'share-gate test', 'monthly', 1000.0, FALSE)",
        )
        .bind(budget_id)
        .bind(owner_id)
        .execute(&pool)
        .await
        .expect("seed budget");

        // Share the budget with a viewer and an editor (the collaborators under test).
        for (email, level) in [(&viewer_email, "view"), (&editor_email, "edit")] {
            sqlx::query(
                "INSERT INTO budget_shares (id, budget_id, shared_with_email, permission_level) \
                 VALUES ($1, $2, $3, $4)",
            )
            .bind(uuid::Uuid::new_v4())
            .bind(budget_id)
            .bind(email)
            .bind(level)
            .execute(&pool)
            .await
            .expect("seed share");
        }

        // Sanity: the collaborators have exactly the access we expect.
        assert_eq!(
            check_permission(&pool, viewer_id, budget_id).await.unwrap(),
            Permission::View
        );
        assert_eq!(
            check_permission(&pool, editor_id, budget_id).await.unwrap(),
            Permission::Edit
        );
        assert_eq!(
            check_permission(&pool, owner_id, budget_id).await.unwrap(),
            Permission::Owner
        );

        async fn target_share_count(
            pool: &sqlx::PgPool,
            budget_id: uuid::Uuid,
            target: &str,
        ) -> i64 {
            sqlx::query_scalar(
                "SELECT COUNT(*) FROM budget_shares WHERE budget_id = $1 AND shared_with_email = $2",
            )
            .bind(budget_id)
            .bind(target)
            .fetch_one(pool)
            .await
            .expect("count target shares")
        }

        let share_request = || ChatRequest {
            message: format!("Please share budget with {target_email}"),
            budget_id: Some(budget_id),
            conversation_id: None,
            locale: None,
        };

        // --- Non-owner VIEW collaborator: REFUSED ---
        let resp = chat_endpoint(
            State(state.clone()),
            Extension(viewer_id),
            Json(share_request()),
        )
        .await
        .expect("viewer chat call returns Ok (refusal is in-band, not an HTTP error)");
        assert!(
            resp.0.response.contains("Only the budget owner can do that."),
            "viewer must see the owner-only refusal, got: {}",
            resp.0.response
        );
        assert_eq!(
            target_share_count(&pool, budget_id, &target_email).await,
            0,
            "view collaborator must NOT insert a budget_shares row"
        );

        // --- Non-owner EDIT collaborator: REFUSED ---
        let resp = chat_endpoint(
            State(state.clone()),
            Extension(editor_id),
            Json(share_request()),
        )
        .await
        .expect("editor chat call returns Ok");
        assert!(
            resp.0.response.contains("Only the budget owner can do that."),
            "editor must see the owner-only refusal, got: {}",
            resp.0.response
        );
        assert_eq!(
            target_share_count(&pool, budget_id, &target_email).await,
            0,
            "edit collaborator must NOT insert a budget_shares row"
        );

        // --- Non-owner EDIT collaborator cannot ESCALATE an existing share ---
        // The share INSERT uses ON CONFLICT DO UPDATE, so the worst case is a
        // non-owner bumping an existing collaborator's level (view -> edit). The
        // gate must block the UPDATE branch too, not just fresh inserts.
        let target_share_id = uuid::Uuid::new_v4();
        sqlx::query(
            "INSERT INTO budget_shares (id, budget_id, shared_with_email, permission_level) \
             VALUES ($1, $2, $3, 'view')",
        )
        .bind(target_share_id)
        .bind(budget_id)
        .bind(&target_email)
        .execute(&pool)
        .await
        .expect("pre-seed target as view");

        let resp = chat_endpoint(
            State(state.clone()),
            Extension(editor_id),
            Json(ChatRequest {
                message: format!("Please share budget with {target_email} as an editor"),
                budget_id: Some(budget_id),
                conversation_id: None,
                locale: None,
            }),
        )
        .await
        .expect("editor escalation chat call returns Ok");
        assert!(
            resp.0.response.contains("Only the budget owner can do that."),
            "editor escalation must be refused, got: {}",
            resp.0.response
        );
        let level_after: String = sqlx::query_scalar(
            "SELECT permission_level FROM budget_shares WHERE id = $1",
        )
        .bind(target_share_id)
        .fetch_one(&pool)
        .await
        .expect("fetch target level after escalation attempt");
        assert_eq!(
            level_after, "view",
            "edit collaborator must NOT escalate an existing share via ON CONFLICT"
        );

        // Remove the escalation fixture so the owner-allowed count assertion below
        // measures only the owner's own insert.
        sqlx::query("DELETE FROM budget_shares WHERE id = $1")
            .bind(target_share_id)
            .execute(&pool)
            .await
            .expect("clear escalation fixture");

        // --- Owner: ALLOWED (regression) ---
        let resp = chat_endpoint(
            State(state.clone()),
            Extension(owner_id),
            Json(share_request()),
        )
        .await
        .expect("owner chat call returns Ok");
        assert!(
            !resp.0.response.contains("Only the budget owner can do that."),
            "owner must NOT be refused, got: {}",
            resp.0.response
        );
        assert_eq!(
            target_share_count(&pool, budget_id, &target_email).await,
            1,
            "owner share must insert exactly one budget_shares row"
        );

        // Cleanup: shares, budget, conversations/messages, then users.
        sqlx::query("DELETE FROM budget_shares WHERE budget_id = $1")
            .bind(budget_id).execute(&pool).await.expect("cleanup shares");
        sqlx::query("DELETE FROM audit_logs WHERE budget_id = $1")
            .bind(budget_id).execute(&pool).await.expect("cleanup audit");
        sqlx::query("DELETE FROM budgets WHERE id = $1")
            .bind(budget_id).execute(&pool).await.expect("cleanup budget");
        for id in [owner_id, viewer_id, editor_id] {
            sqlx::query("DELETE FROM users WHERE id = $1")
                .bind(id).execute(&pool).await.expect("cleanup user");
        }
    }

    // DB-integration coverage for #231: the chat context now includes budgets shared
    // with the caller, not just owned ones. Runs only on demand:
    //   podman-compose up -d
    //   cd backend && cargo test budgets_context -- --ignored
    #[tokio::test]
    #[ignore = "requires Postgres + pgvector; run via: cargo test -- --ignored"]
    async fn budgets_context_rows_shared_only_user_sees_no_active_tag() {
        let url = std::env::var("DATABASE_URL").unwrap_or_else(|_| {
            "postgres://postgres:postgrespassword@localhost:6153/budget_rag".to_string()
        });
        let pool = sqlx::PgPool::connect(&url).await.expect("connect to test db");

        let suffix = uuid::Uuid::new_v4();
        let owner_id = uuid::Uuid::new_v4();
        let viewer_id = uuid::Uuid::new_v4();
        let budget_id = uuid::Uuid::new_v4();
        let viewer_email = format!("viewer-{suffix}@example.test");

        sqlx::query("INSERT INTO users (id, email, name) VALUES ($1, $2, 'Alice')")
            .bind(owner_id)
            .bind(format!("owner-{suffix}@example.test"))
            .execute(&pool).await.expect("seed owner");
        sqlx::query("INSERT INTO users (id, email) VALUES ($1, $2)")
            .bind(viewer_id)
            .bind(&viewer_email)
            .execute(&pool).await.expect("seed viewer");
        sqlx::query(
            "INSERT INTO budgets (id, owner_id, name, time_frame, budget_limit, is_default) \
             VALUES ($1, $2, 'Groceries', 'monthly', 500.0, TRUE)",
        )
        .bind(budget_id).bind(owner_id)
        .execute(&pool).await.expect("seed budget");
        sqlx::query(
            "INSERT INTO budget_shares (id, budget_id, shared_with_email, permission_level) \
             VALUES ($1, $2, $3, 'view')",
        )
        .bind(uuid::Uuid::new_v4()).bind(budget_id).bind(&viewer_email)
        .execute(&pool).await.expect("seed share");

        let rows = fetch_budgets_context_rows(&pool, viewer_id, &viewer_email)
            .await
            .expect("fetch rows");
        // #391 finding 5: pass an UNRELATED id (not None) so the "(active)"
        // assertion below actually discriminates — with None, no row could ever
        // be marked regardless of the formatter's logic, making the assertion
        // vacuous.
        let ctx = format_budgets_context(&rows, Some(uuid::Uuid::new_v4()));

        assert_eq!(rows.len(), 1, "viewer owns nothing, sees only the shared budget");
        assert!(ctx.contains("Groceries (shared by Alice, view access)"), "got: {ctx}");
        assert!(!ctx.contains("(active)"), "shared-only viewer must see no (active) tag, got: {ctx}");

        sqlx::query("DELETE FROM users WHERE id = ANY($1)")
            .bind(&[owner_id, viewer_id][..])
            .execute(&pool).await.expect("cleanup");
    }

    #[tokio::test]
    #[ignore = "requires Postgres + pgvector; run via: cargo test -- --ignored"]
    async fn budgets_context_rows_owned_and_shared_separates_active_from_shared() {
        let url = std::env::var("DATABASE_URL").unwrap_or_else(|_| {
            "postgres://postgres:postgrespassword@localhost:6153/budget_rag".to_string()
        });
        let pool = sqlx::PgPool::connect(&url).await.expect("connect to test db");

        let suffix = uuid::Uuid::new_v4();
        let owner_id = uuid::Uuid::new_v4();
        let viewer_id = uuid::Uuid::new_v4();
        let shared_budget_id = uuid::Uuid::new_v4();
        let own_budget_id = uuid::Uuid::new_v4();
        let viewer_email = format!("viewer2-{suffix}@example.test");

        sqlx::query("INSERT INTO users (id, email, name) VALUES ($1, $2, 'Bob')")
            .bind(owner_id)
            .bind(format!("owner2-{suffix}@example.test"))
            .execute(&pool).await.expect("seed owner");
        sqlx::query("INSERT INTO users (id, email) VALUES ($1, $2)")
            .bind(viewer_id)
            .bind(&viewer_email)
            .execute(&pool).await.expect("seed viewer");

        // The OWNER's own budget, also the OWNER's own is_default = TRUE. This is the
        // key regression case: the viewer must NOT see this as their own "(active)".
        sqlx::query(
            "INSERT INTO budgets (id, owner_id, name, time_frame, budget_limit, is_default) \
             VALUES ($1, $2, 'Household', 'monthly', 1000.0, TRUE)",
        )
        .bind(shared_budget_id).bind(owner_id)
        .execute(&pool).await.expect("seed shared budget");
        sqlx::query(
            "INSERT INTO budget_shares (id, budget_id, shared_with_email, permission_level) \
             VALUES ($1, $2, $3, 'edit')",
        )
        .bind(uuid::Uuid::new_v4()).bind(shared_budget_id).bind(&viewer_email)
        .execute(&pool).await.expect("seed share");

        // The VIEWER's own budget, their own default.
        sqlx::query(
            "INSERT INTO budgets (id, owner_id, name, time_frame, budget_limit, is_default) \
             VALUES ($1, $2, 'My Budget', 'monthly', 200.0, TRUE)",
        )
        .bind(own_budget_id).bind(viewer_id)
        .execute(&pool).await.expect("seed own budget");

        let rows = fetch_budgets_context_rows(&pool, viewer_id, &viewer_email)
            .await
            .expect("fetch rows");
        let ctx = format_budgets_context(&rows, Some(own_budget_id));

        assert_eq!(rows.len(), 2);
        assert!(ctx.contains("My Budget (active)"), "own budget must show (active), got: {ctx}");
        assert!(ctx.contains("Household (shared by Bob, edit access)"), "got: {ctx}");
        assert!(
            !ctx.contains("Household (shared by Bob, edit access) (active)"),
            "shared row must never carry (active) even though its OWNER has is_default=TRUE, got: {ctx}"
        );

        sqlx::query("DELETE FROM users WHERE id = ANY($1)")
            .bind(&[owner_id, viewer_id][..])
            .execute(&pool).await.expect("cleanup");
    }

