        let owner_id = uuid::Uuid::new_v4();
        let sharee_id = uuid::Uuid::new_v4();
        let shared_budget_id = uuid::Uuid::new_v4();
        let own_budget_id = uuid::Uuid::new_v4();
        let sharee_email = format!("sharee-391a-{suffix}@example.test");

        sqlx::query("INSERT INTO users (id, email) VALUES ($1, $2)")
            .bind(owner_id)
            .bind(format!("owner-391a-{suffix}@example.test"))
            .execute(&pool).await.expect("seed owner");
        sqlx::query("INSERT INTO users (id, email) VALUES ($1, $2)")
            .bind(sharee_id)
            .bind(&sharee_email)
            .execute(&pool).await.expect("seed sharee");

        // The owner's budget, shared with the sharee at edit level.
        sqlx::query(
            "INSERT INTO budgets (id, owner_id, name, time_frame, budget_limit, is_default) \
             VALUES ($1, $2, 'Owner Shared', 'monthly', 100.0, FALSE)",
        )
        .bind(shared_budget_id).bind(owner_id)
        .execute(&pool).await.expect("seed shared budget");
        sqlx::query(
            "INSERT INTO budget_shares (id, budget_id, shared_with_email, permission_level) \
             VALUES ($1, $2, $3, 'edit')",
        )
        .bind(uuid::Uuid::new_v4()).bind(shared_budget_id).bind(&sharee_email)
        .execute(&pool).await.expect("seed share");

        // The sharee's own default budget — must lose to the active preference below.
        sqlx::query(
            "INSERT INTO budgets (id, owner_id, name, time_frame, budget_limit, is_default) \
             VALUES ($1, $2, 'Sharee Own', 'monthly', 50.0, TRUE)",
        )
        .bind(own_budget_id).bind(sharee_id)
        .execute(&pool).await.expect("seed own budget");

