    /// Builds a mock Gemini `generateContent` response body carrying the given
    /// structured action, for tests that need to drive an action the offline
    /// router cannot reach (e.g. SWITCH_BUDGET, which has no offline route).
    #[cfg(test)]
    fn gemini_action_response_body(action: &str, action_params: serde_json::Value, response_text: &str) -> serde_json::Value {
        let inner = serde_json::json!({
            "thought": "t",
            "action": action,
            "action_params": action_params,
            "response_text": response_text,
        })
        .to_string();
        serde_json::json!({
            "candidates": [
                { "content": { "parts": [ { "text": inner } ] } }
            ]
        })
    }

    // #391 FINDING 1 regression guard: SWITCH_BUDGET must write the caller's
    // per-viewer preference (users.active_budget_id, #255), not just the
    // owner-scoped is_default flag. Before the fix, a caller whose preference was
    // already set (e.g. via the list page's Switch button, or a PRIOR chat
    // switch) got a SWITCH_BUDGET that flipped is_default but left the stale
    // preference in place — resolve_active_budget_id (which consults the
    // preference FIRST) would then keep resolving to the OLD budget on every
    // subsequent turn while the chat reply claimed success.
    #[tokio::test]
    #[ignore = "requires Postgres + pgvector; run via: cargo test -- --ignored"]
    async fn chat_switch_budget_updates_active_budget_id_preference() {
        // #269: see GEMINI_ENV_LOCK's doc comment — every GEMINI_API_KEY-touching test must hold this.
        let _gemini_env = GEMINI_ENV_LOCK.lock().unwrap_or_else(|e| e.into_inner());
        struct EnvGuard(Option<String>);
        impl Drop for EnvGuard {
            fn drop(&mut self) {
                match &self.0 {
                    Some(v) => std::env::set_var("GEMINI_API_KEY", v),
                    None => std::env::remove_var("GEMINI_API_KEY"),
                }
            }
        }
        let _env_guard = EnvGuard(std::env::var("GEMINI_API_KEY").ok());
        std::env::set_var("GEMINI_API_KEY", "dummy-test-key");

        let server = wiremock::MockServer::start().await;
        std::env::set_var("GEMINI_API_BASE", server.uri());
        let _base_guard = GeminiApiBaseGuard;
        wiremock::Mock::given(wiremock::matchers::method("POST"))
            .respond_with(wiremock::ResponseTemplate::new(200).set_body_json(
                gemini_action_response_body(
                    "SWITCH_BUDGET",
                    serde_json::json!({ "target_budget_name": "Beta" }),
                    "Switched to Beta.",
                ),
            ))
            .mount(&server)
            .await;

        let url = std::env::var("DATABASE_URL").unwrap_or_else(|_| {
            "postgres://postgres:postgrespassword@localhost:6153/budget_rag".to_string()
        });
        let pool = sqlx::PgPool::connect(&url).await.expect("connect to test db");
        let cipher = std::sync::Arc::new(
            crate::crypto::SecretCipher::new(&[7u8; 32]).expect("build test cipher"),
        );
        let state = AppState { db: pool.clone(), cipher, webauthn: std::sync::Arc::new(crate::passkeys::WebauthnRegistry::for_test()) };

        let suffix = uuid::Uuid::new_v4();
        let user_id = uuid::Uuid::new_v4();
        let alpha_id = uuid::Uuid::new_v4();
        let beta_id = uuid::Uuid::new_v4();

        sqlx::query("INSERT INTO users (id, email) VALUES ($1, $2)")
            .bind(user_id)
            .bind(format!("switch-pref-{suffix}@example.test"))
            .execute(&pool).await.expect("seed user");
        sqlx::query(
            "INSERT INTO budgets (id, owner_id, name, time_frame, budget_limit, is_default) \
             VALUES ($1, $2, 'Alpha', 'monthly', 100.0, TRUE)",
        )
        .bind(alpha_id).bind(user_id)
        .execute(&pool).await.expect("seed alpha");
        sqlx::query(
            "INSERT INTO budgets (id, owner_id, name, time_frame, budget_limit, is_default) \
             VALUES ($1, $2, 'Beta', 'monthly', 200.0, FALSE)",
        )
        .bind(beta_id).bind(user_id)
        .execute(&pool).await.expect("seed beta");

        // Preference already set (mimics a user who previously used the list
        // page's Switch button, or an earlier chat switch).
        sqlx::query("UPDATE users SET active_budget_id = $1 WHERE id = $2")
            .bind(alpha_id).bind(user_id)
            .execute(&pool).await.expect("set initial preference");

        let resp = chat_endpoint(
            State(state.clone()),
            Extension(user_id),
            Json(ChatRequest {
                message: "switch to my Beta budget".to_string(),
                budget_id: Some(alpha_id),
                conversation_id: None,
                locale: None,
            }),
        )
        .await
        .expect("chat call succeeds");
        assert!(
            !resp.0.response.contains("⚠️"),
            "a successful switch must not carry a mutation_error warning, got: {}", resp.0.response
        );

        // The regression: on the VERY NEXT call, resolve_active_budget_id must
        // reflect the switch — not the stale preference.
        let resolved = resolve_active_budget_id(&pool, user_id, None)
            .await.expect("resolve");
        assert_eq!(resolved, Some(beta_id), "the preference must follow the chat SWITCH_BUDGET, not stay stuck on the old budget");

        let is_default_beta: bool = sqlx::query_scalar("SELECT is_default FROM budgets WHERE id = $1")
            .bind(beta_id).fetch_one(&pool).await.expect("fetch is_default");
        assert!(is_default_beta, "is_default must also flip, mirroring the pre-#391 behavior");

        sqlx::query("DELETE FROM users WHERE id = $1")
            .bind(user_id)
            .execute(&pool).await.expect("cleanup");
    }

    // #391 FINDING 2: SWITCH_BUDGET's target resolution was owner-only (`WHERE
    // owner_id = $1`), even though prompt rule 12 tells the model to match
    // target_budget_name against the FULL "USER'S BUDGETS" list, which has
    // included shared budgets since #231. A sharee saying "switch to the Family
    // Budget" produced a valid SWITCH_BUDGET action that matched nothing and
    // silently no-opped, while the model's response_text had already claimed
