    // #300: chat ROLLUP_BUDGET must refuse a parent/child pair whose budget_type
    // or budget_strategy differ (`validate_rollup_link`'s new checks) and must
    // NOT write an AI_ROLLUP_BUDGET audit_logs row for the rejected attempt.
    // Drives the extracted `chat_rollup_budget` helper directly.
    //
    // Runs only on demand against the local docker-compose Postgres:
    //   podman-compose up -d
    //   cd backend && cargo test -- --ignored
    #[tokio::test]
    #[ignore = "requires Postgres + pgvector; run via: cargo test -- --ignored"]
    async fn chat_rollup_budget_rejects_type_or_strategy_mismatch_without_audit_row() {
        let url = std::env::var("DATABASE_URL").unwrap_or_else(|_| {
            "postgres://postgres:postgrespassword@localhost:6153/budget_rag".to_string()
        });
        let pool = sqlx::PgPool::connect(&url).await.expect("connect to test db");
        let cipher = std::sync::Arc::new(
            crate::crypto::SecretCipher::new(&[7u8; 32]).expect("build test cipher"),
        );
        let state = AppState { db: pool.clone(), cipher, webauthn: std::sync::Arc::new(crate::passkeys::WebauthnRegistry::for_test()) };

        let suffix = uuid::Uuid::new_v4();
        let user_id = uuid::Uuid::new_v4();
        sqlx::query("INSERT INTO users (id, email) VALUES ($1, $2)")
            .bind(user_id)
            .bind(format!("chatrollup-{suffix}@example.test"))
            .execute(&pool)
            .await
            .expect("seed user");

        let parent_id = uuid::Uuid::new_v4();
        let parent_name = format!("chat-rollup-parent-{suffix}");
        sqlx::query(
            "INSERT INTO budgets (id, owner_id, name, time_frame, budget_type) \
             VALUES ($1, $2, $3, 'monthly', 'time_based')",
        )
        .bind(parent_id)
        .bind(user_id)
        .bind(&parent_name)
        .execute(&pool)
        .await
        .expect("seed parent budget");

        // Child differs from the parent on budget_type only (both default to the
        // same 'limit_spent_remaining' budget_strategy), so this exercises the
        // #300 type-mismatch branch of validate_rollup_link.
        let child_id = uuid::Uuid::new_v4();
        let child_name = format!("chat-rollup-child-{suffix}");
        sqlx::query(
            "INSERT INTO budgets (id, owner_id, name, time_frame, budget_type) \
             VALUES ($1, $2, $3, 'monthly', 'project')",
        )
        .bind(child_id)
        .bind(user_id)
        .bind(&child_name)
        .execute(&pool)
        .await
        .expect("seed child budget");

        let params = AiActionParams {
            target_budget_name: Some(parent_name),
            child_budget_name: Some(child_name),
            ..blank_action_params()
        };

        let (log, err) = chat_rollup_budget(&state, user_id, None, Some(&params)).await;

        assert!(log.is_none(), "a rejected rollup must produce no success log");
        let err = err.expect("mismatched type/strategy must be refused");
        assert!(
            err.contains("budget type") || err.contains("budgeting strategy"),
            "error should explain the type/strategy mismatch, got: {err}"
        );

        let audit_count: i64 = sqlx::query_scalar(
            "SELECT COUNT(*) FROM audit_logs WHERE budget_id = $1 AND action = 'AI_ROLLUP_BUDGET'",
        )
        .bind(parent_id)
        .fetch_one(&pool)
        .await
        .expect("count audit rows");
        assert_eq!(audit_count, 0, "no audit row for a rejected rollup attempt");

        // The link was NOT made either.
        let still_standalone: Option<uuid::Uuid> =
            sqlx::query_scalar("SELECT rollup_parent_id FROM budgets WHERE id = $1")
                .bind(child_id).fetch_one(&pool).await.expect("child row");
        assert_eq!(still_standalone, None, "child remains standalone after a rejected rollup");

        // Cleanup.
        sqlx::query("DELETE FROM audit_logs WHERE budget_id IN ($1, $2)")
            .bind(parent_id).bind(child_id).execute(&pool).await.ok();
        sqlx::query("DELETE FROM categories WHERE budget_id IN ($1, $2)")
            .bind(parent_id).bind(child_id).execute(&pool).await.ok();
        sqlx::query("DELETE FROM budgets WHERE id IN ($1, $2)")
            .bind(parent_id).bind(child_id).execute(&pool).await.ok();
        sqlx::query("DELETE FROM users WHERE id = $1")
            .bind(user_id).execute(&pool).await.ok();
    }

    // Happy path: a valid share with a real budget and a non-self target must
    // succeed (success log, no error) and persist exactly one budget_shares row;
    // re-sharing the same email with a higher level must UPSERT (ON CONFLICT DO
    // UPDATE) rather than insert a duplicate (#83). Drives the extracted
    // `chat_share_budget` helper directly.
    //
    // Runs only on demand against the local docker-compose Postgres:
    //   podman-compose up -d
    //   cd backend && cargo test -- --ignored
    #[tokio::test]
    #[ignore = "requires Postgres + pgvector; run via: cargo test -- --ignored"]
    async fn chat_share_success_inserts_row_and_upserts_on_relink() {
        let url = std::env::var("DATABASE_URL").unwrap_or_else(|_| {
            "postgres://postgres:postgrespassword@localhost:6153/budget_rag".to_string()
        });
        let pool = sqlx::PgPool::connect(&url).await.expect("connect to test db");
        let cipher = std::sync::Arc::new(
            crate::crypto::SecretCipher::new(&[7u8; 32]).expect("build test cipher"),
        );
        let state = AppState { db: pool.clone(), cipher, webauthn: std::sync::Arc::new(crate::passkeys::WebauthnRegistry::for_test()) };

        let suffix = uuid::Uuid::new_v4();
        let user_id = uuid::Uuid::new_v4();
        let budget_id = uuid::Uuid::new_v4();
        let user_email = format!("shareowner-{suffix}@example.test");
        let target_email = format!("collaborator-{suffix}@example.test");

        sqlx::query("INSERT INTO users (id, email) VALUES ($1, $2)")
            .bind(user_id)
            .bind(&user_email)
            .execute(&pool)
            .await
            .expect("seed user");
        sqlx::query(
            "INSERT INTO budgets (id, owner_id, name, time_frame, budget_limit, is_default) \
             VALUES ($1, $2, 'share success test', 'monthly', 1000.0, FALSE)",
        )
        .bind(budget_id)
        .bind(user_id)
        .execute(&pool)
        .await
        .expect("seed budget");

        let params = |level: &str| AiActionParams {
            budget_name: None,
            budget_limit: None,
            time_frame: None,
            description: None,
            category_name: None,
            category_type: None,
            category_limit: None,
            amount: None,
            email: Some(target_email.clone()),
            permission_level: Some(level.to_string()),
            goal_name: None,
            goal_type: None,
            target_amount: None,
            target_date: None,
            linked_category: None,
            note: None,
            reminder_message: None,
            cadence: None,
            name: None,
            target_budget_name: None,
            rollover: None,
            budget_type: None,
            category_rollover: None,
            is_fund: None,
            auto_renew: None,
            amount_mode: None,
            budget_strategy: None,
            child_budget_name: None,
            new_budget_name: None,
            new_category_name: None,
            issue_title: None,
            issue_body: None,
            transaction_match: None,
            new_description: None,
            excluded: None,
            ignore_match: None,
            categories: None,
            account_match: None,
            country: None,
            explicit_category: None,
            institution_query: None,
            currency: None,
            retirement_profile: None,
        };

        // First share as 'view' -> succeeds, inserts one row.
        let view_params = params("view");
        let (log, err) =
            chat_share_budget(&state, user_id, &user_email, Some(budget_id), Some(&view_params)).await;
        assert!(err.is_none(), "valid share must not error: {err:?}");
        assert!(log.is_some(), "valid share must produce a success log");

        // Re-share the SAME email as 'edit' -> UPSERTs (ON CONFLICT DO UPDATE),
        // still exactly one row, now at the higher level.
        let edit_params = params("edit");
        let (log2, err2) =
            chat_share_budget(&state, user_id, &user_email, Some(budget_id), Some(&edit_params)).await;
        assert!(err2.is_none(), "re-share must not error: {err2:?}");
        assert!(log2.is_some(), "re-share must produce a success log");

        let (count, level): (i64, String) = sqlx::query_as(
            "SELECT COUNT(*)::bigint, MAX(permission_level) \
             FROM budget_shares WHERE budget_id = $1 AND shared_with_email = $2",
        )
        .bind(budget_id)
        .bind(&target_email)
        .fetch_one(&pool)
        .await
        .expect("count + level of shares");
        assert_eq!(count, 1, "re-share must UPSERT, not duplicate the row");
        assert_eq!(level, "edit", "re-share must update the permission level");

        // Cleanup: shares, budget, then user.
        sqlx::query("DELETE FROM budget_shares WHERE budget_id = $1")
            .bind(budget_id).execute(&pool).await.expect("cleanup shares");
        sqlx::query("DELETE FROM budgets WHERE id = $1")
            .bind(budget_id).execute(&pool).await.expect("cleanup budget");
        sqlx::query("DELETE FROM users WHERE id = $1")
            .bind(user_id).execute(&pool).await.expect("cleanup user");
    }

    // End-to-end proof that a chat-driven budget rename (#89) actually persists,
    // through the real `chat_endpoint` with the offline router (no GEMINI_API_KEY)
    // mapping "rename budget to <name>" to UPDATE_BUDGET with `new_budget_name`.
    // This is the gap the feature shipped without: the UPDATE_BUDGET arm previously
    // had no `name` branch, so renames were silently dropped. Also proves the
    // no-blank guard: a bare "rename budget" (no new name) must NOT clear the name.
    //
    // Runs only on demand against the local docker-compose Postgres:
    //   podman-compose up -d
    //   cd backend && cargo test -- --ignored
    #[tokio::test]
    #[ignore = "requires Postgres + pgvector; run via: cargo test -- --ignored"]
    async fn chat_rename_budget_updates_active_budget_name() {
        // #269: see GEMINI_ENV_LOCK's doc comment — every GEMINI_API_KEY-touching test must hold this.
        let _gemini_env = GEMINI_ENV_LOCK.lock().unwrap_or_else(|e| e.into_inner());
        struct EnvGuard(Option<String>);
        impl Drop for EnvGuard {
            fn drop(&mut self) {
                match &self.0 {
                    Some(v) => std::env::set_var("GEMINI_API_KEY", v),
                    None => std::env::remove_var("GEMINI_API_KEY"),
                }
            }
        }
        let _env_guard = EnvGuard(std::env::var("GEMINI_API_KEY").ok());
        std::env::remove_var("GEMINI_API_KEY");

        let url = std::env::var("DATABASE_URL").unwrap_or_else(|_| {
            "postgres://postgres:postgrespassword@localhost:6153/budget_rag".to_string()
        });
        let pool = sqlx::PgPool::connect(&url).await.expect("connect to test db");
        let cipher = std::sync::Arc::new(
            crate::crypto::SecretCipher::new(&[7u8; 32]).expect("build test cipher"),
        );
        let state = AppState { db: pool.clone(), cipher, webauthn: std::sync::Arc::new(crate::passkeys::WebauthnRegistry::for_test()) };

        let suffix = uuid::Uuid::new_v4();
        let owner_id = uuid::Uuid::new_v4();
        let budget_id = uuid::Uuid::new_v4();

        sqlx::query("INSERT INTO users (id, email) VALUES ($1, $2)")
            .bind(owner_id)
            .bind(format!("owner-{suffix}@example.test"))
            .execute(&pool)
            .await
            .expect("seed user");
        sqlx::query(
            "INSERT INTO budgets (id, owner_id, name, time_frame, budget_limit, is_default) \
             VALUES ($1, $2, 'Old Name', 'monthly', 1000.0, TRUE)",
        )
        .bind(budget_id)
        .bind(owner_id)
        .execute(&pool)
        .await
        .expect("seed budget");

        async fn budget_name(pool: &sqlx::PgPool, id: uuid::Uuid) -> String {
            sqlx::query_scalar("SELECT name FROM budgets WHERE id = $1")
                .bind(id)
                .fetch_one(pool)
                .await
                .expect("fetch budget name")
        }

        // --- Rename applies and persists ---
        let resp = chat_endpoint(
            State(state.clone()),
            Extension(owner_id),
            Json(ChatRequest {
                message: "rename budget to Summer Trip".to_string(),
                budget_id: Some(budget_id),
                conversation_id: None,
                locale: None,
            }),
        )
        .await
        .expect("rename chat call returns Ok");
        assert_eq!(
            budget_name(&pool, budget_id).await,
            "Summer Trip",
            "the active budget's name must be updated in the DB"
        );
        assert_eq!(
            resp.0.action_taken.as_deref(),
            Some("renamed budget to 'Summer Trip'"),
            "the response must report the rename mutation, got: {:?}",
            resp.0.action_taken
        );

        // --- No-blank guard: a bare "rename budget" (no new name) is a no-op ---
        let resp = chat_endpoint(
            State(state.clone()),
            Extension(owner_id),
            Json(ChatRequest {
                message: "rename budget".to_string(),
                budget_id: Some(budget_id),
                conversation_id: None,
                locale: None,
            }),
        )
        .await
        .expect("bare rename chat call returns Ok");
        assert_eq!(
            budget_name(&pool, budget_id).await,
            "Summer Trip",
            "a rename with no new name must NOT blank the existing name"
        );
        assert!(
            resp.0.action_taken.is_none(),
            "a bare rename performs no mutation, got: {:?}",
            resp.0.action_taken
        );

        // Cleanup.
        sqlx::query("DELETE FROM audit_logs WHERE budget_id = $1")
            .bind(budget_id).execute(&pool).await.expect("cleanup audit");
        sqlx::query("DELETE FROM chat_messages WHERE user_id = $1")
            .bind(owner_id).execute(&pool).await.expect("cleanup messages");
        sqlx::query("DELETE FROM conversations WHERE user_id = $1")
            .bind(owner_id).execute(&pool).await.expect("cleanup conversations");
        sqlx::query("DELETE FROM budgets WHERE id = $1")
            .bind(budget_id).execute(&pool).await.expect("cleanup budget");
        sqlx::query("DELETE FROM users WHERE id = $1")
            .bind(owner_id).execute(&pool).await.expect("cleanup user");
    }

    // Locks in the code-review fix for #303's offline UNLINK_BANK_ACCOUNT gap: the
    // offline router previously routed "disconnect my chase account" to
    // UNLINK_BANK_ACCOUNT but never populated `account_match`, so it ALWAYS fell
    // into the generic "Which account would you like to disconnect?" clarifying
    // question — even though the user clearly named a bank — because the mutation
    // arm only attempts its (plain substring) match when `account_match` is
    // `Some`. This runs through the real `chat_endpoint` (no GEMINI_API_KEY) to
    // prove `account_match` is now threaded through end to end:
    //   - a locator that matches no linked account still names the ACTUAL locator
    //     text in its error (proving `account_match` carried the real message,
    //     not `None` — the old bug always asked the generic clarifying question
    //     regardless of message content)
    //   - a locator that DOES match (because the fixture's institution_name is
    //     deliberately long enough to literally contain the raw message — see the
    //     matcher's `haystack.contains(needle)` direction in the UNLINK_BANK_ACCOUNT
    //     arm above) actually disconnects the account via Stripe and flips its DB
    //     status, proving the plumbing works end to end, not just that a string
    //     landed in the struct.
    //
    // Runs only on demand against the local docker-compose Postgres:
    //   podman-compose up -d
    //   cd backend && cargo test -- --ignored
    #[tokio::test]
    #[ignore = "requires Postgres + pgvector; run via: cargo test -- --ignored"]
    #[serial_test::serial]
    async fn chat_offline_unlink_bank_account_populates_account_match() {
        // #269: see GEMINI_ENV_LOCK's doc comment — every GEMINI_API_KEY-touching test must hold this.
        let _gemini_env = GEMINI_ENV_LOCK.lock().unwrap_or_else(|e| e.into_inner());
        struct EnvGuard(Option<String>);
        impl Drop for EnvGuard {
            fn drop(&mut self) {
                match &self.0 {
                    Some(v) => std::env::set_var("GEMINI_API_KEY", v),
                    None => std::env::remove_var("GEMINI_API_KEY"),
                }
            }
        }
        let _env_guard = EnvGuard(std::env::var("GEMINI_API_KEY").ok());
        std::env::remove_var("GEMINI_API_KEY");

        let url = std::env::var("DATABASE_URL").unwrap_or_else(|_| {
            "postgres://postgres:postgrespassword@localhost:6153/budget_rag".to_string()
        });
        let pool = sqlx::PgPool::connect(&url).await.expect("connect to test db");
        let cipher = std::sync::Arc::new(
            crate::crypto::SecretCipher::new(&[7u8; 32]).expect("build test cipher"),
        );
        let state = AppState { db: pool.clone(), cipher, webauthn: std::sync::Arc::new(crate::passkeys::WebauthnRegistry::for_test()) };

        let suffix = uuid::Uuid::new_v4();
        let owner_id = uuid::Uuid::new_v4();
        let budget_id = uuid::Uuid::new_v4();
        let no_match_account_id = uuid::Uuid::new_v4();
        let matching_account_id = uuid::Uuid::new_v4();

        sqlx::query("INSERT INTO users (id, email) VALUES ($1, $2)")
            .bind(owner_id)
            .bind(format!("unlink-offline-{suffix}@example.test"))
            .execute(&pool)
            .await
            .expect("seed user");
        sqlx::query(
            "INSERT INTO budgets (id, owner_id, name, time_frame, budget_limit, is_default) \
             VALUES ($1, $2, 'Unlink Offline Test', 'monthly', 1000.0, TRUE)",
        )
        .bind(budget_id)
        .bind(owner_id)
        .execute(&pool)
        .await
        .expect("seed budget");

        // --- Case 1: no linked account's name is a substring match for the raw
        // message -> the code must still reach the matching logic (proving
        // account_match carried the real text) and report a "couldn't find"
        // error naming the actual locator, NOT the old generic clarifying
        // question (which fired regardless of message content).
        sqlx::query(
            "INSERT INTO linked_accounts (id, budget_id, user_id, provider, provider_account_id, provider_ref, institution_name, display_name, status) \
             VALUES ($1, $2, $3, 'stripe', $4, 'cus_test_unlink', 'Wells Fargo', 'Wells Fargo Checking', 'active')",
        )
        .bind(no_match_account_id)
        .bind(budget_id)
        .bind(owner_id)
        .bind(format!("fca_no_match_{suffix}"))
        .execute(&pool)
        .await
        .expect("seed non-matching linked account");

        let resp = chat_endpoint(
            State(state.clone()),
            Extension(owner_id),
            Json(ChatRequest {
                message: "disconnect my chase account".to_string(),
                budget_id: Some(budget_id),
                conversation_id: None,
                locale: None,
            }),
        )
        .await
        .expect("unlink chat call returns Ok");
        assert!(
            !resp.0.response.contains("Which account would you like to disconnect?"),
            "account_match must be populated from the message, not left None, got: {}",
            resp.0.response
        );
        assert!(
            resp.0.response.contains("disconnect my chase account"),
            "the 'couldn't find' error must echo the actual locator text (proving \
             account_match carried the real message), got: {}",
            resp.0.response
        );

        // --- Case 2: a fixture whose institution_name literally contains the raw
        // message text (a deliberately contrived fixture, chosen to satisfy the
        // matcher's `account_name.contains(locator)` direction — see comment
        // above) resolves to exactly one account and actually disconnects it.
        let server = wiremock::MockServer::start().await;
        std::env::set_var("STRIPE_API_BASE", server.uri());
        std::env::set_var("STRIPE_SECRET_KEY", "sk_test_x");
        wiremock::Mock::given(wiremock::matchers::method("POST"))
            .and(wiremock::matchers::path(format!(
                "/v1/financial_connections/accounts/fca_match_{suffix}/disconnect"
            )))
            .respond_with(wiremock::ResponseTemplate::new(200).set_body_json(serde_json::json!({
                "id": format!("fca_match_{suffix}"), "status": "disconnected"
            })))
            .expect(1)
            .mount(&server)
            .await;

        sqlx::query(
            "INSERT INTO linked_accounts (id, budget_id, user_id, provider, provider_account_id, provider_ref, institution_name, display_name, status) \
             VALUES ($1, $2, $3, 'stripe', $4, 'cus_test_unlink', 'Test Bank (unlink my checking account)', 'Test Checking', 'active')",
        )
        .bind(matching_account_id)
        .bind(budget_id)
        .bind(owner_id)
        .bind(format!("fca_match_{suffix}"))
        .execute(&pool)
        .await
        .expect("seed matching linked account");

        let resp2 = chat_endpoint(
            State(state.clone()),
            Extension(owner_id),
            Json(ChatRequest {
                message: "unlink my checking account".to_string(),
                budget_id: Some(budget_id),
                conversation_id: None,
                locale: None,
            }),
        )
        .await
        .expect("unlink chat call returns Ok");
        assert!(
            resp2.0.action_taken.as_deref().unwrap_or("").contains("Disconnected"),
            "a genuine single-account match must actually disconnect it, got action_taken: {:?}, response: {}",
            resp2.0.action_taken, resp2.0.response
        );

        let status: String = sqlx::query_scalar("SELECT status FROM linked_accounts WHERE id = $1")
            .bind(matching_account_id)
            .fetch_one(&pool)
            .await
            .expect("fetch status");
        assert_eq!(status, "disconnected", "the matched account's status must flip in the DB");
        // wiremock verifies .expect(1) on drop — confirms Stripe's disconnect endpoint was actually called.

        std::env::remove_var("STRIPE_API_BASE");
        std::env::remove_var("STRIPE_SECRET_KEY");

        // Cleanup.
        sqlx::query("DELETE FROM linked_accounts WHERE budget_id = $1")
            .bind(budget_id).execute(&pool).await.expect("cleanup linked accounts");
        sqlx::query("DELETE FROM audit_logs WHERE budget_id = $1")
            .bind(budget_id).execute(&pool).await.expect("cleanup audit");
        sqlx::query("DELETE FROM chat_messages WHERE user_id = $1")
            .bind(owner_id).execute(&pool).await.expect("cleanup messages");
        sqlx::query("DELETE FROM conversations WHERE user_id = $1")
            .bind(owner_id).execute(&pool).await.expect("cleanup conversations");
        sqlx::query("DELETE FROM budgets WHERE id = $1")
            .bind(budget_id).execute(&pool).await.expect("cleanup budget");
        sqlx::query("DELETE FROM users WHERE id = $1")
            .bind(owner_id).execute(&pool).await.expect("cleanup user");
    }

    // End-to-end proof that chat-driven amount-mode changes (#116) persist through
    // the real `chat_endpoint` with the offline router (no GEMINI_API_KEY):
    //   - "set this budget to a fixed $2000" -> amount_mode='fixed', budget_limit=2000
    //   - "derive this budget's amount from its categories" -> amount_mode='derived'
    //   - an invalid mode is rejected and leaves the row unchanged
    //   - CREATE_BUDGET with amount_mode='fixed' persists the mode
    //
    // Runs only on demand against the local docker-compose Postgres:
    //   podman-compose up -d
    //   cd backend && cargo test -- --ignored
    #[tokio::test]
    #[ignore = "requires Postgres + pgvector; run via: cargo test -- --ignored"]
    async fn chat_amount_mode_updates_active_budget() {
        // #269: see GEMINI_ENV_LOCK's doc comment — every GEMINI_API_KEY-touching test must hold this.
        let _gemini_env = GEMINI_ENV_LOCK.lock().unwrap_or_else(|e| e.into_inner());
        struct EnvGuard(Option<String>);
        impl Drop for EnvGuard {
            fn drop(&mut self) {
                match &self.0 {
                    Some(v) => std::env::set_var("GEMINI_API_KEY", v),
                    None => std::env::remove_var("GEMINI_API_KEY"),
                }
            }
        }
        let _env_guard = EnvGuard(std::env::var("GEMINI_API_KEY").ok());
        std::env::remove_var("GEMINI_API_KEY");

        let url = std::env::var("DATABASE_URL").unwrap_or_else(|_| {
            "postgres://postgres:postgrespassword@localhost:6153/budget_rag".to_string()
        });
        let pool = sqlx::PgPool::connect(&url).await.expect("connect to test db");
        let cipher = std::sync::Arc::new(
            crate::crypto::SecretCipher::new(&[7u8; 32]).expect("build test cipher"),
        );
        let state = AppState { db: pool.clone(), cipher, webauthn: std::sync::Arc::new(crate::passkeys::WebauthnRegistry::for_test()) };

        let suffix = uuid::Uuid::new_v4();
        let owner_id = uuid::Uuid::new_v4();
        let budget_id = uuid::Uuid::new_v4();

        sqlx::query("INSERT INTO users (id, email) VALUES ($1, $2)")
            .bind(owner_id)
            .bind(format!("owner-{suffix}@example.test"))
            .execute(&pool)
            .await
            .expect("seed user");
        sqlx::query(
            "INSERT INTO budgets (id, owner_id, name, time_frame, budget_limit, is_default, amount_mode) \
             VALUES ($1, $2, 'Mode Budget', 'monthly', 0.0, TRUE, 'derived')",
        )
        .bind(budget_id)
        .bind(owner_id)
        .execute(&pool)
        .await
        .expect("seed budget");

        async fn mode_and_limit(pool: &sqlx::PgPool, id: uuid::Uuid) -> (String, Option<f64>) {
            let row = sqlx::query("SELECT amount_mode, budget_limit FROM budgets WHERE id = $1")
                .bind(id)
                .fetch_one(pool)
                .await
                .expect("fetch budget");
            (row.get("amount_mode"), row.get("budget_limit"))
        }

        // --- Fixed + amount in one message persists BOTH ---
        let resp = chat_endpoint(
            State(state.clone()),
            Extension(owner_id),
            Json(ChatRequest {
                message: "set this budget to a fixed $2000".to_string(),
                budget_id: Some(budget_id),
                conversation_id: None,
                locale: None,
            }),
        )
        .await
        .expect("fixed chat call returns Ok");
        let (mode, limit) = mode_and_limit(&pool, budget_id).await;
        assert_eq!(mode, "fixed", "amount_mode must be persisted as fixed");
        assert_eq!(limit, Some(2000.0), "the fixed amount must be persisted as budget_limit");
        assert!(
            resp.0.action_taken.is_some(),
            "the response must report a mutation, got: {:?}",
            resp.0.action_taken
        );

        // --- Back to derived ---
        chat_endpoint(
            State(state.clone()),
            Extension(owner_id),
            Json(ChatRequest {
                message: "derive this budget's amount from its categories".to_string(),
                budget_id: Some(budget_id),
                conversation_id: None,
                locale: None,
            }),
        )
        .await
        .expect("derived chat call returns Ok");
        let (mode, limit) = mode_and_limit(&pool, budget_id).await;
        assert_eq!(mode, "derived", "amount_mode must be persisted as derived");
        // Switching back to derived is lossless: the stored budget_limit is retained
        // (just ignored while derived) so a later switch back to fixed re-uses it.
        assert_eq!(
            limit,
            Some(2000.0),
            "fixed->derived must retain budget_limit, not clear it"
        );

        // --- An invalid mode is rejected by the dispatch guard, leaving the row unchanged ---
        // The offline router only ever emits valid modes, so we can't drive an invalid
        // value through `chat_endpoint`. Instead we invoke the SAME function the
        // UPDATE_BUDGET dispatch arm calls (apply_amount_mode_update), passing an
        // invalid mode "FIXED". This exercises the real guard end-to-end against the
        // live DB: the call must return Err (a mutation/validation error surfaced) AND
        // the budget row's amount_mode must be UNCHANGED (still 'derived' from above).
        // If the `validate_amount_mode` guard in apply_amount_mode_update is removed,
        // the UPDATE would run and flip the row to 'FIXED', failing the assertions below.
        let bad = apply_amount_mode_update(&pool, budget_id, owner_id, "FIXED", None).await;
        // Assert on the APPLICATION guard's specific message, not just any Err: the
        // DB also has a CHECK constraint on amount_mode, so a generic Err would still
        // be produced even if the validate_amount_mode guard were removed (the UPDATE
        // would just fail at the DB layer). Pinning the guard's exact wording
        // ("...: amount_mode must be...") makes this test FAIL if the guard is removed,
        // because the fallback DB-error path returns a different, generic message.
        let err = bad.expect_err("an invalid amount_mode must surface a validation error");
        assert!(
            err.contains("amount_mode must be"),
            "the invalid mode must be rejected by the application guard (not just the DB), got: {:?}",
            err
        );
        let (mode, _limit) = mode_and_limit(&pool, budget_id).await;
        assert_eq!(mode, "derived", "an invalid mode must not change the stored value");

        // --- Switching to fixed with NO stored/supplied amount nudges for one ---
        // Clear the retained limit so the no-amount branch is reached, then drive the
        // valid-mode success path of apply_amount_mode_update directly and assert the
        // nudge fragment is appended (and the mode still flips to fixed).
        sqlx::query("UPDATE budgets SET budget_limit = 0.0 WHERE id = $1")
            .bind(budget_id).execute(&pool).await.expect("reset limit");
        let nudge = apply_amount_mode_update(&pool, budget_id, owner_id, "fixed", None)
            .await
            .expect("valid fixed switch returns Ok");
        assert!(
            nudge.contains("set a fixed amount"),
            "switching to fixed with no amount must nudge for one, got: {:?}",
            nudge
        );
        let (mode, _limit) = mode_and_limit(&pool, budget_id).await;
        assert_eq!(mode, "fixed", "the no-amount fixed switch still flips the mode");

        // (The chat CREATE_BUDGET arm's amount_mode persistence is covered by the
        // REST `create_budget` integration test in budget.rs, which exercises the
        // identical INSERT shape; the offline router cannot carry amount_mode on a
        // create so it can't be driven end-to-end through `chat_endpoint` here.)

        // Cleanup.
        sqlx::query("DELETE FROM audit_logs WHERE budget_id = $1")
            .bind(budget_id).execute(&pool).await.expect("cleanup audit");
        sqlx::query("DELETE FROM chat_messages WHERE user_id = $1")
            .bind(owner_id).execute(&pool).await.expect("cleanup messages");
        sqlx::query("DELETE FROM conversations WHERE user_id = $1")
            .bind(owner_id).execute(&pool).await.expect("cleanup conversations");
        sqlx::query("DELETE FROM budgets WHERE owner_id = $1")
            .bind(owner_id).execute(&pool).await.expect("cleanup budgets");
        sqlx::query("DELETE FROM users WHERE id = $1")
            .bind(owner_id).execute(&pool).await.expect("cleanup user");
    }

    // Proof (#300) that the UPDATE_BUDGET dispatch arm can change an EXISTING
    // budget's budget_strategy. Unlike CREATE_BUDGET's ask-first clarification
    // guard, an UPDATE_BUDGET request always carries an explicit value — there's
    // no offline-router phrase that routes chat text to an UPDATE_BUDGET
    // budget_strategy change, so (mirroring the invalid-mode guard test above,
    // which drives `apply_amount_mode_update` directly for the same reason) this
    // drives `apply_budget_strategy_update` directly: the exact function the
    // UPDATE_BUDGET dispatch arm delegates to.
    //
    // Runs only on demand against the local docker-compose Postgres:
    //   podman-compose up -d
    //   cd backend && cargo test -- --ignored
    #[tokio::test]
    #[ignore = "requires Postgres + pgvector; run via: cargo test -- --ignored"]
    async fn chat_update_budget_changes_budget_strategy() {
        let url = std::env::var("DATABASE_URL").unwrap_or_else(|_| {
            "postgres://postgres:postgrespassword@localhost:6153/budget_rag".to_string()
        });
        let pool = sqlx::PgPool::connect(&url).await.expect("connect to test db");

        let suffix = uuid::Uuid::new_v4();
        let owner_id = uuid::Uuid::new_v4();
        let budget_id = uuid::Uuid::new_v4();

        sqlx::query("INSERT INTO users (id, email) VALUES ($1, $2)")
            .bind(owner_id)
            .bind(format!("owner-{suffix}@example.test"))
            .execute(&pool)
            .await
            .expect("seed user");
        sqlx::query(
            "INSERT INTO budgets (id, owner_id, name, time_frame, budget_limit, is_default, budget_strategy) \
             VALUES ($1, $2, 'Strategy Budget', 'monthly', 0.0, TRUE, 'limit_spent_remaining')",
        )
        .bind(budget_id)
        .bind(owner_id)
        .execute(&pool)
        .await
        .expect("seed budget");

        async fn strategy_of(pool: &sqlx::PgPool, id: uuid::Uuid) -> String {
            sqlx::query_scalar("SELECT budget_strategy FROM budgets WHERE id = $1")
                .bind(id)
                .fetch_one(pool)
                .await
                .expect("fetch budget_strategy")
        }

        // --- A valid strategy change is persisted and audited ---
        let msg = apply_budget_strategy_update(&pool, budget_id, owner_id, "zero_based")
            .await
            .expect("valid strategy change returns Ok");
        assert!(
            msg.contains("zero_based"),
            "the mutation-log fragment should mention the new strategy, got: {:?}",
            msg
        );
        assert_eq!(
            strategy_of(&pool, budget_id).await,
            "zero_based",
            "budget_strategy must be updated to zero_based"
        );
        let audit_count: i64 = sqlx::query_scalar(
            "SELECT COUNT(*) FROM audit_logs WHERE budget_id = $1 AND action = 'AI_UPDATE_BUDGET'",
        )
        .bind(budget_id)
        .fetch_one(&pool)
        .await
        .expect("count audit rows");
        assert_eq!(audit_count, 1, "a successful strategy change must write an AI_UPDATE_BUDGET audit row");

        // --- An invalid strategy is rejected by the guard, leaving the row unchanged ---
        let bad = apply_budget_strategy_update(&pool, budget_id, owner_id, "fifty_thirty_twenty").await;
        let err = bad.expect_err("an invalid budget_strategy must surface a validation error");
        assert!(
            err.contains("budget_strategy must be"),
            "the invalid strategy must be rejected by the application guard (not just the DB), got: {:?}",
            err
        );
        assert_eq!(
            strategy_of(&pool, budget_id).await,
            "zero_based",
            "an invalid strategy must not change the stored value"
        );

        // Cleanup.
        sqlx::query("DELETE FROM audit_logs WHERE budget_id = $1")
            .bind(budget_id).execute(&pool).await.expect("cleanup audit");
        sqlx::query("DELETE FROM budgets WHERE owner_id = $1")
            .bind(owner_id).execute(&pool).await.expect("cleanup budgets");
        sqlx::query("DELETE FROM users WHERE id = $1")
            .bind(owner_id).execute(&pool).await.expect("cleanup user");
    }

    // #317: apply_budget_strategy_update rejects an ACTUAL strategy change on a budget that is a
    // rollup CHILD or PARENT, leaving the row and audit log untouched — mirrors the REST
    // update_budget guard for the one axis chat can change on an existing budget.
    #[tokio::test]
    #[ignore = "requires Postgres + pgvector; run via: cargo test -- --ignored"]
    async fn chat_update_budget_rejects_strategy_change_on_rollup_participant() {
        let url = std::env::var("DATABASE_URL").unwrap_or_else(|_| {
            "postgres://postgres:postgrespassword@localhost:6153/budget_rag".to_string()
        });
        let pool = sqlx::PgPool::connect(&url).await.expect("connect to test db");

        let suffix = uuid::Uuid::new_v4();
        let owner_id = uuid::Uuid::new_v4();
        let parent_id = uuid::Uuid::new_v4();
        let child_id = uuid::Uuid::new_v4();

        sqlx::query("INSERT INTO users (id, email) VALUES ($1, $2)")
            .bind(owner_id)
            .bind(format!("owner-{suffix}@example.test"))
            .execute(&pool)
            .await
            .expect("seed user");
        sqlx::query(
            "INSERT INTO budgets (id, owner_id, name, time_frame, budget_limit, is_default, budget_strategy) \
             VALUES ($1, $2, 'Parent', 'monthly', 0.0, TRUE, 'limit_spent_remaining')",
        )
        .bind(parent_id)
        .bind(owner_id)
        .execute(&pool)
        .await
        .expect("seed parent");
        sqlx::query(
            "INSERT INTO budgets (id, owner_id, name, time_frame, budget_limit, is_default, budget_strategy, rollup_parent_id) \
             VALUES ($1, $2, 'Child', 'monthly', 0.0, FALSE, 'limit_spent_remaining', $3)",
        )
        .bind(child_id)
        .bind(owner_id)
        .bind(parent_id)
        .execute(&pool)
        .await
        .expect("seed child linked to parent");

        async fn strategy_of(pool: &sqlx::PgPool, id: uuid::Uuid) -> String {
            sqlx::query_scalar("SELECT budget_strategy FROM budgets WHERE id = $1")
                .bind(id)
                .fetch_one(pool)
                .await
                .expect("fetch budget_strategy")
        }

        // --- CHILD: an actual change is rejected, row unchanged, no audit row written ---
        let err = apply_budget_strategy_update(&pool, child_id, owner_id, "zero_based")
            .await
            .expect_err("changing strategy on a rollup child must be rejected");
        assert!(err.contains("rollup"), "error should mention the rollup relationship, got: {:?}", err);
        assert_eq!(strategy_of(&pool, child_id).await, "limit_spent_remaining");
        let child_audit_count: i64 = sqlx::query_scalar(
            "SELECT COUNT(*) FROM audit_logs WHERE budget_id = $1 AND action = 'AI_UPDATE_BUDGET'",
        )
        .bind(child_id)
        .fetch_one(&pool)
        .await
        .expect("count child audit rows");
        assert_eq!(child_audit_count, 0, "a rejected change must not write an audit row");

        // --- PARENT: same rejection ---
        let err = apply_budget_strategy_update(&pool, parent_id, owner_id, "zero_based")
            .await
            .expect_err("changing strategy on a rollup parent must be rejected");
        assert!(err.contains("rollup"));
        assert_eq!(strategy_of(&pool, parent_id).await, "limit_spent_remaining");

        // --- Resubmitting the SAME value on the child is a no-op success ---
        let msg = apply_budget_strategy_update(&pool, child_id, owner_id, "limit_spent_remaining")
            .await
            .expect("resubmitting the unchanged strategy must succeed");
        assert!(msg.contains("limit_spent_remaining"));

        // Cleanup.
        sqlx::query("DELETE FROM audit_logs WHERE budget_id = ANY($1)")
            .bind(&[parent_id, child_id][..])
            .execute(&pool)
            .await
            .expect("cleanup audit");
        sqlx::query("DELETE FROM budgets WHERE owner_id = $1")
            .bind(owner_id)
            .execute(&pool)
            .await
            .expect("cleanup budgets");
        sqlx::query("DELETE FROM users WHERE id = $1")
            .bind(owner_id)
            .execute(&pool)
            .await
            .expect("cleanup user");
    }

    // End-to-end proof (#300) that a chat-driven CREATE_BUDGET with no strategy
    // phrase asks a clarifying question and creates NOTHING, through the real
    // `chat_endpoint` with the offline router (no GEMINI_API_KEY). The offline
    // gate requires the literal substring "create budget" (not "create a
    // budget") — see `msg_lower.contains("create budget")` in the offline
    // router — so "create budget Vacation" is the matching phrasing.
    //
    // Runs only on demand against the local docker-compose Postgres:
    //   podman-compose up -d
    //   cd backend && cargo test -- --ignored
    #[tokio::test]
    #[ignore = "requires Postgres + pgvector; run via: cargo test -- --ignored"]
    async fn chat_create_budget_offline_without_strategy_phrase_asks_and_creates_nothing() {
        // #269: see GEMINI_ENV_LOCK's doc comment — every GEMINI_API_KEY-touching test must hold this.
        let _gemini_env = GEMINI_ENV_LOCK.lock().unwrap_or_else(|e| e.into_inner());
        struct EnvGuard(Option<String>);
        impl Drop for EnvGuard {
            fn drop(&mut self) {
                match &self.0 {
                    Some(v) => std::env::set_var("GEMINI_API_KEY", v),
                    None => std::env::remove_var("GEMINI_API_KEY"),
                }
            }
        }
        let _env_guard = EnvGuard(std::env::var("GEMINI_API_KEY").ok());
        std::env::remove_var("GEMINI_API_KEY");

        let url = std::env::var("DATABASE_URL").unwrap_or_else(|_| {
            "postgres://postgres:postgrespassword@localhost:6153/budget_rag".to_string()
        });
        let pool = sqlx::PgPool::connect(&url).await.expect("connect to test db");
        let cipher = std::sync::Arc::new(
            crate::crypto::SecretCipher::new(&[7u8; 32]).expect("build test cipher"),
        );
        let state = AppState { db: pool.clone(), cipher, webauthn: std::sync::Arc::new(crate::passkeys::WebauthnRegistry::for_test()) };

        let suffix = uuid::Uuid::new_v4();
        let owner_id = uuid::Uuid::new_v4();

        sqlx::query("INSERT INTO users (id, email) VALUES ($1, $2)")
            .bind(owner_id)
            .bind(format!("owner-{suffix}@example.test"))
            .execute(&pool)
            .await
            .expect("seed user");

        let resp = chat_endpoint(
            State(state.clone()),
            Extension(owner_id),
            Json(ChatRequest {
                message: "create budget Vacation".to_string(),
                budget_id: None,
                conversation_id: None,
                locale: None,
            }),
        )
        .await
        .expect("create-budget chat call returns Ok");

        assert!(
            resp.0.response.to_lowercase().contains("strategy"),
            "must ask which strategy before creating, got: {}",
            resp.0.response
        );
        assert!(
            resp.0.response.to_lowercase().contains("zero"),
            "must present the zero-based option, got: {}",
            resp.0.response
        );
        assert!(
            resp.0.response.to_lowercase().contains("limit"),
            "must present the limit/spent/remaining option, got: {}",
            resp.0.response
        );
        assert!(
            resp.0.action_taken.is_none(),
            "a clarifying question performs no mutation, got: {:?}",
            resp.0.action_taken
        );

        let count: i64 = sqlx::query_scalar("SELECT COUNT(*) FROM budgets WHERE owner_id = $1")
            .bind(owner_id)
            .fetch_one(&pool)
            .await
            .expect("count budgets");
        assert_eq!(count, 0, "no budget must be created without a strategy");

        // Cleanup.
        sqlx::query("DELETE FROM chat_messages WHERE user_id = $1")
            .bind(owner_id).execute(&pool).await.expect("cleanup messages");
        sqlx::query("DELETE FROM conversations WHERE user_id = $1")
            .bind(owner_id).execute(&pool).await.expect("cleanup conversations");
        sqlx::query("DELETE FROM users WHERE id = $1")
            .bind(owner_id).execute(&pool).await.expect("cleanup user");
    }

    // End-to-end proof (#300) that a chat-driven CREATE_BUDGET that DOES include
    // a strategy phrase in the same message creates the budget with that
    // strategy, through the real `chat_endpoint` with the offline router (no
    // GEMINI_API_KEY). The message contains BOTH "create budget" (the offline
    // CREATE_BUDGET gate) and "zero based budget" (`offline_budget_strategy`'s
    // match phrase) as substrings.
    //
    // Runs only on demand against the local docker-compose Postgres:
    //   podman-compose up -d
