    // ADD_TRANSACTION that auto-creates a BRAND-NEW category must (a) still log
    // the transaction, (b) leave the new category UNCAPPED (limit NULL) until the
    // user accepts, and (c) surface the limit offer in the reply (#123). Runs on
    // the offline router: "log $42 spent on something" -> ADD_TRANSACTION, amount
    // 42.0, category "Utilities" (the else branch), which does not pre-exist here.
    #[tokio::test]
    #[ignore = "requires Postgres + pgvector; run via: cargo test -- --ignored"]
    async fn chat_add_transaction_new_category_offers_limit() {
        // #269: see GEMINI_ENV_LOCK's doc comment — every GEMINI_API_KEY-touching test must hold this.
        let _gemini_env = GEMINI_ENV_LOCK.lock().unwrap_or_else(|e| e.into_inner());
        struct EnvGuard(Option<String>);
        impl Drop for EnvGuard {
            fn drop(&mut self) {
                match &self.0 {
                    Some(v) => std::env::set_var("GEMINI_API_KEY", v),
                    None => std::env::remove_var("GEMINI_API_KEY"),
                }
            }
        }
        let _env_guard = EnvGuard(std::env::var("GEMINI_API_KEY").ok());
        std::env::remove_var("GEMINI_API_KEY");

        let url = std::env::var("DATABASE_URL").unwrap_or_else(|_| {
            "postgres://postgres:postgrespassword@localhost:6153/budget_rag".to_string()
        });
        let pool = sqlx::PgPool::connect(&url).await.expect("connect to test db");
        let cipher = std::sync::Arc::new(
            crate::crypto::SecretCipher::new(&[7u8; 32]).expect("build test cipher"),
        );
        let state = AppState { db: pool.clone(), cipher, webauthn: std::sync::Arc::new(crate::passkeys::WebauthnRegistry::for_test()) };

        let suffix = uuid::Uuid::new_v4();
        let owner_id = uuid::Uuid::new_v4();
        let budget_id = uuid::Uuid::new_v4();

        sqlx::query("INSERT INTO users (id, email) VALUES ($1, $2)")
            .bind(owner_id)
            .bind(format!("owner-{suffix}@example.test"))
            .execute(&pool)
            .await
            .expect("seed user");
        sqlx::query(
            "INSERT INTO budgets (id, owner_id, name, time_frame, budget_limit, is_default) \
             VALUES ($1, $2, 'My Budget', 'monthly', 1000.0, TRUE)",
        )
        .bind(budget_id)
        .bind(owner_id)
        .execute(&pool)
        .await
        .expect("seed budget");

        let resp = chat_endpoint(
            State(state.clone()),
            Extension(owner_id),
            Json(ChatRequest {
                message: "log $42 spent on something".to_string(),
                budget_id: Some(budget_id),
                conversation_id: None,
                locale: None,
            }),
        )
        .await
        .expect("add transaction chat call returns Ok");

        // The new "Utilities" category exists but is UNCAPPED until accepted.
        // Use fetch_optional so a missing row (e.g. the offline router picked a
        // different name) fails with a clear message instead of a confusing panic.
        let climit: Option<f64> = sqlx::query_scalar::<_, Option<f64>>(
            "SELECT category_limit FROM categories WHERE budget_id = $1 AND name = 'Utilities'",
        )
        .bind(budget_id)
        .fetch_optional(&pool)
        .await
        .expect("query new category row")
        .expect("auto-created 'Utilities' category must exist");
        assert_eq!(climit, None, "auto-created category stays uncapped until the user accepts");

        // The transaction was logged regardless of the offer. fetch_optional so a
        // missing row fails as a clear assertion rather than a panic.
        let amt: Option<f64> = sqlx::query_scalar(
            "SELECT amount FROM transactions WHERE budget_id = $1",
        )
        .bind(budget_id)
        .fetch_optional(&pool)
        .await
        .expect("query transaction");
        assert_eq!(amt, Some(42.0), "the transaction must always be logged");

        // The reply offers to set the limit.
        assert!(
            resp.0.response.contains("Utilities"),
            "offer names the new category, got: {}",
            resp.0.response
        );
        assert!(
            resp.0.response.to_lowercase().contains("limit"),
            "offer mentions a limit, got: {}",
            resp.0.response
        );

        // Cleanup.
        sqlx::query("DELETE FROM transactions WHERE budget_id = $1")
            .bind(budget_id).execute(&pool).await.expect("cleanup transactions");
        sqlx::query("DELETE FROM audit_logs WHERE budget_id = $1")
            .bind(budget_id).execute(&pool).await.expect("cleanup audit");
        sqlx::query("DELETE FROM chat_messages WHERE user_id = $1")
            .bind(owner_id).execute(&pool).await.expect("cleanup messages");
        sqlx::query("DELETE FROM conversations WHERE user_id = $1")
            .bind(owner_id).execute(&pool).await.expect("cleanup conversations");
        sqlx::query("DELETE FROM categories WHERE budget_id = $1")
            .bind(budget_id).execute(&pool).await.expect("cleanup categories");
        sqlx::query("DELETE FROM budgets WHERE id = $1")
            .bind(budget_id).execute(&pool).await.expect("cleanup budget");
        sqlx::query("DELETE FROM users WHERE id = $1")
            .bind(owner_id).execute(&pool).await.expect("cleanup user");
    }

