    // --- #376: ADD_TRANSACTION pending category choice ---

    // The core decision, exhaustively (no DB needed).
    #[test]
    fn should_offer_choice_only_when_inventing_with_candidates() {
        use super::should_offer_category_choice;
        // no match, inferred, candidates present -> ASK
        assert!(should_offer_category_choice(false, false, 2));
        // exact match -> never ask (log under the match)
        assert!(!should_offer_category_choice(true, false, 2));
        // user explicitly named the category -> honor it, create+log, don't ask
        assert!(!should_offer_category_choice(false, true, 2));
        // nothing to choose from (empty budget) -> silent auto-create, don't ask
        assert!(!should_offer_category_choice(false, false, 0));
        // explicit AND match -> never ask
        assert!(!should_offer_category_choice(true, true, 5));
    }


    // Shared offline-router harness for the #376 ADD tests: removes GEMINI_API_KEY
    // (so "log $42 spent on something" routes offline to ADD_TRANSACTION with
    // category "Utilities"), seeds a default budget, runs the chat call, and
    // returns (pool, owner_id, budget_id, response). Caller seeds any categories
    // BEFORE calling via the `pre_seed` closure.
    #[tokio::test]
    #[ignore = "requires Postgres + pgvector; run via: cargo test -- --ignored"]
    async fn add_transaction_no_match_with_categories_returns_choice() {
        let _gemini_env = GEMINI_ENV_LOCK.lock().unwrap_or_else(|e| e.into_inner());
        struct EnvGuard(Option<String>);
        impl Drop for EnvGuard {
            fn drop(&mut self) {
                match &self.0 {
                    Some(v) => std::env::set_var("GEMINI_API_KEY", v),
                    None => std::env::remove_var("GEMINI_API_KEY"),
                }
            }
        }
        let _env_guard = EnvGuard(std::env::var("GEMINI_API_KEY").ok());
        std::env::remove_var("GEMINI_API_KEY");

        let url = std::env::var("DATABASE_URL").unwrap_or_else(|_| {
            "postgres://postgres:postgrespassword@localhost:6153/budget_rag".to_string()
        });
        let pool = sqlx::PgPool::connect(&url).await.expect("connect to test db");
        let cipher = std::sync::Arc::new(
            crate::crypto::SecretCipher::new(&[7u8; 32]).expect("build test cipher"),
        );
        let state = AppState { db: pool.clone(), cipher, webauthn: std::sync::Arc::new(crate::passkeys::WebauthnRegistry::for_test()) };
        let suffix = uuid::Uuid::new_v4();
        let owner_id = uuid::Uuid::new_v4();
        let budget_id = uuid::Uuid::new_v4();
        sqlx::query("INSERT INTO users (id, email) VALUES ($1, $2)")
            .bind(owner_id).bind(format!("owner-{suffix}@example.test"))
            .execute(&pool).await.expect("seed user");
        sqlx::query(
            "INSERT INTO budgets (id, owner_id, name, time_frame, budget_limit, is_default) \
             VALUES ($1, $2, 'My Budget', 'monthly', 1000.0, TRUE)",
        )
        .bind(budget_id).bind(owner_id).execute(&pool).await.expect("seed budget");
        // An existing expense category the model did NOT name -> a candidate.
        sqlx::query("INSERT INTO categories (id, budget_id, name, category_type) VALUES ($1, $2, 'Rob', 'expense')")
            .bind(uuid::Uuid::new_v4()).bind(budget_id).execute(&pool).await.expect("seed Rob");
        // An income category and a mirror (#52, linked_budget_id set) must NOT be
        // offered as spend targets.
        sqlx::query("INSERT INTO categories (id, budget_id, name, category_type) VALUES ($1, $2, 'Salary', 'income')")
            .bind(uuid::Uuid::new_v4()).bind(budget_id).execute(&pool).await.expect("seed Salary");
        let other_budget = uuid::Uuid::new_v4();
        sqlx::query(
            "INSERT INTO budgets (id, owner_id, name, time_frame, budget_limit) \
             VALUES ($1, $2, 'Source', 'monthly', 100.0)",
        )
        .bind(other_budget).bind(owner_id).execute(&pool).await.expect("seed source budget");
        sqlx::query(
            "INSERT INTO categories (id, budget_id, name, category_type, linked_budget_id) \
             VALUES ($1, $2, 'Mirror', 'expense', $3)",
        )
        .bind(uuid::Uuid::new_v4()).bind(budget_id).bind(other_budget).execute(&pool).await.expect("seed mirror");

        let resp = chat_endpoint(
            State(state.clone()),
            Extension(owner_id),
            Json(ChatRequest {
                message: "log $42 spent on something".to_string(),
                budget_id: Some(budget_id),
                conversation_id: None,
                locale: None,
            }),
        )
        .await
        .expect("chat call Ok");

        let choice = resp.0.pending_category_choice.as_ref().expect("a choice is offered");
        assert_eq!(choice.proposed_new_name, "Utilities");
        let names: Vec<&str> = choice.candidates.iter().map(|c| c.name.as_str()).collect();
        assert!(names.contains(&"Rob"), "existing expense category offered");
        assert!(!names.contains(&"Salary"), "income categories are not offered as spend targets");
        assert!(!names.contains(&"Mirror"), "mirror (#52) categories are not offered");
        assert!(resp.0.action_taken.is_none(), "nothing was logged");

        // No transaction and no 'Utilities' category were created.
        let tx_count: i64 = sqlx::query_scalar("SELECT COUNT(*) FROM transactions WHERE budget_id = $1")
            .bind(budget_id).fetch_one(&pool).await.expect("count tx");
        assert_eq!(tx_count, 0, "the transaction is NOT logged while a choice is pending");
        let util: i64 = sqlx::query_scalar(
            "SELECT COUNT(*) FROM categories WHERE budget_id = $1 AND name = 'Utilities'",
        )
        .bind(budget_id).fetch_one(&pool).await.expect("count util");
        assert_eq!(util, 0, "no brand-new category is created while asking");

        sqlx::query("DELETE FROM transactions WHERE budget_id = $1").bind(budget_id).execute(&pool).await.ok();
        sqlx::query("DELETE FROM audit_logs WHERE budget_id = $1").bind(budget_id).execute(&pool).await.ok();
        sqlx::query("DELETE FROM chat_messages WHERE user_id = $1").bind(owner_id).execute(&pool).await.ok();
        sqlx::query("DELETE FROM conversations WHERE user_id = $1").bind(owner_id).execute(&pool).await.ok();
        sqlx::query("DELETE FROM categories WHERE budget_id = $1").bind(budget_id).execute(&pool).await.ok();
        sqlx::query("DELETE FROM budgets WHERE id = $1").bind(budget_id).execute(&pool).await.ok();
        sqlx::query("DELETE FROM budgets WHERE id = $1").bind(other_budget).execute(&pool).await.ok();
        sqlx::query("DELETE FROM users WHERE id = $1").bind(owner_id).execute(&pool).await.ok();
    }

