    // add no coverage.
    #[tokio::test]
    #[ignore = "requires Postgres + pgvector; run via: cargo test -- --ignored"]
    async fn chat_rename_category_edge_cases() {
        // #269: see GEMINI_ENV_LOCK's doc comment — every GEMINI_API_KEY-touching test must hold this.
        let _gemini_env = GEMINI_ENV_LOCK.lock().unwrap_or_else(|e| e.into_inner());
        struct EnvGuard(Option<String>);
        impl Drop for EnvGuard {
            fn drop(&mut self) {
                match &self.0 {
                    Some(v) => std::env::set_var("GEMINI_API_KEY", v),
                    None => std::env::remove_var("GEMINI_API_KEY"),
                }
            }
        }
        let _env_guard = EnvGuard(std::env::var("GEMINI_API_KEY").ok());
        std::env::remove_var("GEMINI_API_KEY");

        let url = std::env::var("DATABASE_URL").unwrap_or_else(|_| {
            "postgres://postgres:postgrespassword@localhost:6153/budget_rag".to_string()
        });
        let pool = sqlx::PgPool::connect(&url).await.expect("connect to test db");
        let cipher = std::sync::Arc::new(
            crate::crypto::SecretCipher::new(&[7u8; 32]).expect("build test cipher"),
        );
        let state = AppState { db: pool.clone(), cipher, webauthn: std::sync::Arc::new(crate::passkeys::WebauthnRegistry::for_test()) };

        async fn rename_call(
            state: &AppState,
            owner_id: uuid::Uuid,
            budget_id: uuid::Uuid,
            msg: &str,
        ) -> ChatResponse {
            chat_endpoint(
                State(state.clone()),
                Extension(owner_id),
                Json(ChatRequest {
                    message: msg.to_string(),
                    budget_id: Some(budget_id),
                    conversation_id: None,
                    locale: None,
                }),
            )
            .await
            .expect("rename chat call returns Ok")
            .0
        }

        // ----- (a) conflict: rename Food -> Bills when Bills already exists -----
        let suffix = uuid::Uuid::new_v4();
        let owner_id = uuid::Uuid::new_v4();
        let budget_id = uuid::Uuid::new_v4();
        let food_id = uuid::Uuid::new_v4();
        let bills_id = uuid::Uuid::new_v4();
        sqlx::query("INSERT INTO users (id, email) VALUES ($1, $2)")
            .bind(owner_id)
            .bind(format!("owner-{suffix}@example.test"))
            .execute(&pool).await.expect("seed user");
        sqlx::query(
            "INSERT INTO budgets (id, owner_id, name, time_frame, budget_limit, is_default) \
             VALUES ($1, $2, 'My Budget', 'monthly', 1000.0, TRUE)",
        )
        .bind(budget_id).bind(owner_id).execute(&pool).await.expect("seed budget");
        sqlx::query("INSERT INTO categories (id, budget_id, name, category_type) VALUES ($1, $2, 'Food', 'expense')")
            .bind(food_id).bind(budget_id).execute(&pool).await.expect("seed Food");
        sqlx::query("INSERT INTO categories (id, budget_id, name, category_type) VALUES ($1, $2, 'Bills', 'expense')")
            .bind(bills_id).bind(budget_id).execute(&pool).await.expect("seed Bills");

        let resp = rename_call(&state, owner_id, budget_id, "rename the Food category to Bills").await;
        assert!(
            resp.action_taken.is_none(),
            "a conflicting rename must not report a mutation, got: {:?}",
            resp.action_taken
        );
        assert!(
            resp.response.contains("already exists"),
            "conflict must surface an 'already exists' message, got: {}",
            resp.response
        );
        let food_name: String =
            sqlx::query_scalar("SELECT name FROM categories WHERE id = $1")
                .bind(food_id).fetch_one(&pool).await.expect("fetch Food");
        assert_eq!(food_name, "Food", "the source category must be unchanged on conflict");

        // ----- (b) unknown source category -----
        let resp = rename_call(&state, owner_id, budget_id, "rename the Nonexistent category to Whatever").await;
        assert!(
            resp.action_taken.is_none(),
            "renaming an unknown category must not report a mutation, got: {:?}",
            resp.action_taken
        );
        assert!(
            resp.response.contains("couldn't find"),
            "unknown source must surface a not-found message, got: {}",
            resp.response
        );

        // ----- (c) closed (project) budget rejects the rename -----
        let closed_budget_id = uuid::Uuid::new_v4();
        let closed_cat_id = uuid::Uuid::new_v4();
        sqlx::query(
            "INSERT INTO budgets (id, owner_id, name, time_frame, budget_limit, is_default, budget_type, closed_at) \
             VALUES ($1, $2, 'Closed Project', 'monthly', 1000.0, FALSE, 'project', now())",
        )
        .bind(closed_budget_id).bind(owner_id).execute(&pool).await.expect("seed closed budget");
        sqlx::query("INSERT INTO categories (id, budget_id, name, category_type) VALUES ($1, $2, 'Wood', 'expense')")
            .bind(closed_cat_id).bind(closed_budget_id).execute(&pool).await.expect("seed closed cat");

        let resp = rename_call(&state, owner_id, closed_budget_id, "rename the Wood category to Lumber").await;
        assert!(
            resp.action_taken.is_none(),
            "a rename on a closed budget must not report a mutation, got: {:?}",
            resp.action_taken
        );
        assert!(
            resp.response.contains("can't change this budget"),
            "a closed-budget rename must surface the rejection wording, got: {}",
            resp.response
        );
        let closed_name: String =
            sqlx::query_scalar("SELECT name FROM categories WHERE id = $1")
                .bind(closed_cat_id).fetch_one(&pool).await.expect("fetch closed cat");
        assert_eq!(closed_name, "Wood", "the category on a closed budget must be unchanged");

        // Cleanup.
        for bid in [budget_id, closed_budget_id] {
            sqlx::query("DELETE FROM audit_logs WHERE budget_id = $1")
                .bind(bid).execute(&pool).await.expect("cleanup audit");
            sqlx::query("DELETE FROM categories WHERE budget_id = $1")
                .bind(bid).execute(&pool).await.expect("cleanup categories");
        }
        sqlx::query("DELETE FROM chat_messages WHERE user_id = $1")
            .bind(owner_id).execute(&pool).await.expect("cleanup messages");
        sqlx::query("DELETE FROM conversations WHERE user_id = $1")
            .bind(owner_id).execute(&pool).await.expect("cleanup conversations");
        for bid in [budget_id, closed_budget_id] {
            sqlx::query("DELETE FROM budgets WHERE id = $1")
                .bind(bid).execute(&pool).await.expect("cleanup budget");
        }
        sqlx::query("DELETE FROM users WHERE id = $1")
            .bind(owner_id).execute(&pool).await.expect("cleanup user");
    }

    // --- Conversation deletion (#53) ---

    /// Deleting a conversation must remove the conversation row AND every chat
    /// message tied to it — including each message's embedding (which lives in
    /// the `chat_messages.embedding` column, so it goes when the row cascades).
    /// No orphaned message/embedding rows may remain, and a SECOND conversation
    /// belonging to the same user must be left fully intact. This exercises the
    /// exact owner-scoped SQL that `delete_conversation` runs.
    ///
    /// Runs only on demand against the local docker-compose Postgres:
    ///   podman-compose up -d
    ///   cd backend && cargo test -- --ignored
    #[tokio::test]
    #[ignore = "requires Postgres + pgvector; run via: cargo test -- --ignored"]
    async fn delete_conversation_removes_messages_and_embeddings() {
        let url = std::env::var("DATABASE_URL").unwrap_or_else(|_| {
            "postgres://postgres:postgrespassword@localhost:6153/budget_rag".to_string()
        });
        let pool = sqlx::PgPool::connect(&url).await.expect("connect to test db");

        let user_id = uuid::Uuid::new_v4();
        let target_convo = uuid::Uuid::new_v4(); // to be deleted
        let survivor_convo = uuid::Uuid::new_v4(); // must remain

        sqlx::query("INSERT INTO users (id, email) VALUES ($1, $2)")
            .bind(user_id)
            .bind(format!("del-conv-{user_id}@example.test"))
            .execute(&pool)
            .await
            .expect("seed user");
        for c in [target_convo, survivor_convo] {
            sqlx::query("INSERT INTO conversations (id, user_id, title) VALUES ($1, $2, 'c')")
                .bind(c)
                .bind(user_id)
                .execute(&pool)
                .await
                .expect("seed conversation");
        }

        // Seed the target with one embedded and one non-embedded message (so the
        // cascade is exercised for both kinds), and the survivor with one embedded
        // message. A 768-dim zero vector satisfies the vector(768) column.
        async fn seed_msg(
            pool: &sqlx::PgPool,
            convo: uuid::Uuid,
            user: uuid::Uuid,
            text: &str,
            embedded: bool,
        ) {
            let emb = if embedded {
                "array_fill(0::real, ARRAY[768])::vector"
            } else {
                "NULL"
            };
            let sql = format!(
                "INSERT INTO chat_messages
                    (id, user_id, budget_id, conversation_id, sender, message_text, embedding)
                 VALUES (gen_random_uuid(), $1, NULL, $2, 'user', $3, {emb})"
            );
            sqlx::query(&sql)
                .bind(user)
                .bind(convo)
                .bind(text)
                .execute(pool)
                .await
                .expect("seed message");
        }
        seed_msg(&pool, target_convo, user_id, "target-embedded", true).await;
        seed_msg(&pool, target_convo, user_id, "target-plain", false).await;
        seed_msg(&pool, survivor_convo, user_id, "survivor-embedded", true).await;

        async fn count(pool: &sqlx::PgPool, sql: &str, id: uuid::Uuid) -> i64 {
            sqlx::query_scalar::<_, i64>(sql)
                .bind(id)
                .fetch_one(pool)
                .await
                .expect("count")
        }

        // Sanity: target seeded with 2 messages, 1 embedded.
        assert_eq!(
            count(&pool, "SELECT COUNT(*) FROM chat_messages WHERE conversation_id = $1", target_convo).await,
            2,
            "target seeded with 2 messages"
        );
        assert_eq!(
            count(&pool, "SELECT COUNT(*) FROM chat_messages WHERE conversation_id = $1 AND embedding IS NOT NULL", target_convo).await,
            1,
            "target seeded with 1 embedding"
        );

        // Run the exact owner-scoped DELETE the handler runs.
        let result = sqlx::query("DELETE FROM conversations WHERE id = $1 AND user_id = $2")
            .bind(target_convo)
            .bind(user_id)
            .execute(&pool)
            .await
            .expect("delete conversation");
        assert_eq!(result.rows_affected(), 1, "exactly the target conversation deleted");

        // Completeness: conversation row gone; ALL its messages gone (so every
        // embedding for those messages is gone too); zero orphans.
        assert_eq!(
            count(&pool, "SELECT COUNT(*) FROM conversations WHERE id = $1", target_convo).await,
            0,
            "target conversation row removed"
        );
        assert_eq!(
            count(&pool, "SELECT COUNT(*) FROM chat_messages WHERE conversation_id = $1", target_convo).await,
            0,
            "no orphaned messages for the deleted conversation"
        );
        assert_eq!(
            count(&pool, "SELECT COUNT(*) FROM chat_messages WHERE conversation_id = $1 AND embedding IS NOT NULL", target_convo).await,
            0,
            "no orphaned embeddings for the deleted conversation"
        );

        // The survivor conversation and its embedded message are untouched.
        assert_eq!(
            count(&pool, "SELECT COUNT(*) FROM conversations WHERE id = $1", survivor_convo).await,
            1,
            "survivor conversation intact"
        );
        assert_eq!(
            count(&pool, "SELECT COUNT(*) FROM chat_messages WHERE conversation_id = $1 AND embedding IS NOT NULL", survivor_convo).await,
            1,
            "survivor message + embedding intact"
        );

        // Cleanup: deleting the user cascades to the survivor conversation + messages.
        sqlx::query("DELETE FROM users WHERE id = $1")
            .bind(user_id)
            .execute(&pool)
            .await
            .expect("cleanup");
    }

    /// A user must only be able to delete their OWN conversations. The handler
    /// scopes the DELETE by `user_id`; a non-owner's attempt must affect 0 rows
    /// (the handler maps that to 404) and leave the victim's data fully intact,
    /// while the real owner's delete succeeds.
    ///
    /// Runs only on demand against the local docker-compose Postgres:
    ///   podman-compose up -d
    ///   cd backend && cargo test -- --ignored
    #[tokio::test]
    #[ignore = "requires Postgres + pgvector; run via: cargo test -- --ignored"]
    async fn delete_conversation_is_owner_scoped() {
        let url = std::env::var("DATABASE_URL").unwrap_or_else(|_| {
            "postgres://postgres:postgrespassword@localhost:6153/budget_rag".to_string()
        });
        let pool = sqlx::PgPool::connect(&url).await.expect("connect to test db");

        let owner_id = uuid::Uuid::new_v4(); // owns the conversation
        let attacker_id = uuid::Uuid::new_v4(); // must NOT be able to delete it
        let convo_id = uuid::Uuid::new_v4();

        for (id, tag) in [(owner_id, "owner"), (attacker_id, "attacker")] {
            sqlx::query("INSERT INTO users (id, email) VALUES ($1, $2)")
                .bind(id)
                .bind(format!("{tag}-{id}@example.test"))
                .execute(&pool)
                .await
                .expect("seed user");
        }
        sqlx::query("INSERT INTO conversations (id, user_id, title) VALUES ($1, $2, 'private')")
            .bind(convo_id)
            .bind(owner_id)
            .execute(&pool)
            .await
            .expect("seed conversation");
        sqlx::query(
            "INSERT INTO chat_messages (id, user_id, budget_id, conversation_id, sender, message_text)
             VALUES (gen_random_uuid(), $1, NULL, $2, 'user', 'secret message')",
        )
        .bind(owner_id)
        .bind(convo_id)
        .execute(&pool)
        .await
        .expect("seed message");

        async fn count(pool: &sqlx::PgPool, sql: &str, id: uuid::Uuid) -> i64 {
            sqlx::query_scalar::<_, i64>(sql)
                .bind(id)
                .fetch_one(pool)
                .await
                .expect("count")
        }

        // Attacker attempts the owner-scoped DELETE with THEIR user_id → no match.
        let attack = sqlx::query("DELETE FROM conversations WHERE id = $1 AND user_id = $2")
            .bind(convo_id)
            .bind(attacker_id)
            .execute(&pool)
            .await
            .expect("attacker delete query");
        assert_eq!(
            attack.rows_affected(),
            0,
            "cross-user delete must affect 0 rows (handler returns 404)"
        );

        // The victim's conversation + message are still present.
        assert_eq!(
            count(&pool, "SELECT COUNT(*) FROM conversations WHERE id = $1", convo_id).await,
            1,
            "conversation survives a cross-user delete attempt"
        );
        assert_eq!(
            count(&pool, "SELECT COUNT(*) FROM chat_messages WHERE conversation_id = $1", convo_id).await,
            1,
            "message survives a cross-user delete attempt"
        );

        // The real owner can delete it.
        let owner_delete = sqlx::query("DELETE FROM conversations WHERE id = $1 AND user_id = $2")
            .bind(convo_id)
            .bind(owner_id)
            .execute(&pool)
            .await
            .expect("owner delete query");
        assert_eq!(owner_delete.rows_affected(), 1, "owner can delete their own conversation");
        assert_eq!(
            count(&pool, "SELECT COUNT(*) FROM chat_messages WHERE conversation_id = $1", convo_id).await,
            0,
            "owner delete cascades the message"
        );

        // Cleanup.
        for id in [owner_id, attacker_id] {
            sqlx::query("DELETE FROM users WHERE id = $1")
                .bind(id)
                .execute(&pool)
                .await
                .expect("cleanup user");
        }
    }

    // record_llm_usage persists exactly one row carrying the supplied token
    // counts for a real user (issue #140, AC #2).
    #[tokio::test]
    #[ignore = "requires Postgres + pgvector; run via: cargo test -- --ignored"]
    async fn record_llm_usage_persists_one_row() {
        let url = std::env::var("DATABASE_URL").unwrap_or_else(|_| {
            "postgres://postgres:postgrespassword@localhost:6153/budget_rag".to_string()
        });
        let pool = sqlx::PgPool::connect(&url).await.expect("connect to test db");

        let user_id = uuid::Uuid::new_v4();
        sqlx::query("INSERT INTO users (id, email) VALUES ($1, $2)")
            .bind(user_id)
            .bind(format!("llm-usage-{user_id}@example.test"))
            .execute(&pool)
            .await
            .expect("seed user");

        record_llm_usage(&pool, user_id, "gemini-2.5-flash", "chat", 10, 20, 5, 35).await;

        let (count, model, call_type, input_t, output_t, thinking_t, total_t): (i64, String, String, i32, i32, i32, i32) =
            sqlx::query_as(
                "SELECT COUNT(*), MAX(model), MAX(call_type), MAX(input_tokens), MAX(output_tokens), MAX(thinking_tokens), MAX(total_tokens) \
                 FROM llm_usage WHERE user_id = $1",
            )
            .bind(user_id)
            .fetch_one(&pool)
            .await
            .expect("query llm_usage");

        assert_eq!(count, 1, "exactly one llm_usage row recorded");
        assert_eq!(model, "gemini-2.5-flash");
        assert_eq!(call_type, "chat");
        assert_eq!(input_t, 10);
        assert_eq!(output_t, 20);
        assert_eq!(thinking_t, 5);
        assert_eq!(total_t, 35);

        // Cleanup (FK ON DELETE CASCADE would also clear llm_usage, but be explicit).
        sqlx::query("DELETE FROM llm_usage WHERE user_id = $1")
            .bind(user_id)
            .execute(&pool)
            .await
            .expect("cleanup llm_usage");
        sqlx::query("DELETE FROM users WHERE id = $1")
            .bind(user_id)
            .execute(&pool)
            .await
            .expect("cleanup user");
    }

    // AC #6 fail-safe: a usage-write failure (here an FK violation from a
    // non-existent user_id) must be swallowed — record_llm_usage returns ()
    // without panicking and inserts no row.
    #[tokio::test]
    #[ignore = "requires Postgres + pgvector; run via: cargo test -- --ignored"]
    async fn record_llm_usage_swallows_write_failure() {
        let url = std::env::var("DATABASE_URL").unwrap_or_else(|_| {
            "postgres://postgres:postgrespassword@localhost:6153/budget_rag".to_string()
        });
        let pool = sqlx::PgPool::connect(&url).await.expect("connect to test db");

        // No such user — the FK to users(id) must fail, and the helper must
        // swallow that error rather than panic or propagate.
        let bogus_user_id = uuid::Uuid::new_v4();
        record_llm_usage(&pool, bogus_user_id, "m", "chat", 1, 1, 1, 1).await;

        let count: i64 =
            sqlx::query_scalar("SELECT COUNT(*) FROM llm_usage WHERE user_id = $1")
                .bind(bogus_user_id)
                .fetch_one(&pool)
                .await
                .expect("query llm_usage");
        assert_eq!(count, 0, "FK violation must leave no llm_usage row");
    }

    // ===== Multi-category chat creation (#166) =====
    //
    // These drive the extracted `chat_create_categories` helper directly against a
