    // Union de-dup: a model that fills BOTH the singular channel ("Food") AND the
    // `categories` array with the SAME name in a different case ("food") must NOT
    // double-create. Singular wins (it is pushed first), so exactly one row named
    // "Food" exists and its limit comes from the singular entry (#166).
    #[tokio::test]
    #[ignore = "requires Postgres + pgvector; run via: cargo test -- --ignored"]
    async fn chat_create_categories_union_dedup_singular_wins() {
        let url = std::env::var("DATABASE_URL").unwrap_or_else(|_| {
            "postgres://postgres:postgrespassword@localhost:6153/budget_rag".to_string()
        });
        let pool = sqlx::PgPool::connect(&url).await.expect("connect to test db");
        let cipher = std::sync::Arc::new(
            crate::crypto::SecretCipher::new(&[7u8; 32]).expect("build test cipher"),
        );
        let state = AppState { db: pool.clone(), cipher, webauthn: std::sync::Arc::new(crate::passkeys::WebauthnRegistry::for_test()) };

        let suffix = uuid::Uuid::new_v4();
        let owner_id = uuid::Uuid::new_v4();
        let budget_id = uuid::Uuid::new_v4();

        sqlx::query("INSERT INTO users (id, email) VALUES ($1, $2)")
            .bind(owner_id)
            .bind(format!("dedupcat-{suffix}@example.test"))
            .execute(&pool)
            .await
            .expect("seed user");
        sqlx::query(
            "INSERT INTO budgets (id, owner_id, name, time_frame, budget_limit, is_default) \
             VALUES ($1, $2, 'Dedup Cat', 'monthly', 10000.0, TRUE)",
        )
        .bind(budget_id)
        .bind(owner_id)
        .execute(&pool)
        .await
        .expect("seed budget");

        let params = super::AiActionParams {
            budget_name: None,
            budget_limit: None,
            time_frame: None,
            description: None,
            category_name: Some("Food".to_string()),
            category_type: Some("expense".to_string()),
            category_limit: Some(50.0),
            amount: None,
            email: None,
            permission_level: None,
            goal_name: None,
            goal_type: None,
            target_amount: None,
            target_date: None,
            linked_category: None,
            note: None,
            reminder_message: None,
            cadence: None,
            name: None,
            target_budget_name: None,
            rollover: None,
            budget_type: None,
            category_rollover: None,
            is_fund: None,
            auto_renew: None,
            amount_mode: None,
            budget_strategy: None,
            child_budget_name: None,
            new_budget_name: None,
            new_category_name: None,
            issue_title: None,
            issue_body: None,
            transaction_match: None,
            new_description: None,
            excluded: None,
            ignore_match: None,
            // Same name, different case, different limit — must be de-duped away.
            categories: Some(vec![super::AiCategorySpec {
                category_name: "food".to_string(),
                category_type: None,
                category_limit: Some(99.0),
                is_fund: None,
            }]),
            account_match: None,
            country: None,
            explicit_category: None,
            institution_query: None,
            currency: None,
            retirement_profile: None,
        };

        let (log, err) =
            super::chat_create_categories(&state, owner_id, Some(budget_id), Some(&params)).await;

        assert!(err.is_none(), "dedup create must not error: {:?}", err);
        assert!(log.is_some(), "dedup create must produce a success log");

        let count: i64 = sqlx::query_scalar(
            "SELECT COUNT(*) FROM categories WHERE budget_id = $1 AND lower(name) = 'food'",
        )
        .bind(budget_id)
        .fetch_one(&pool)
        .await
        .expect("count food categories");
        assert_eq!(count, 1, "the singular + array 'food' entries must de-dup to one row");

        // Singular precedence: the row carries the singular's name AND limit (50),
        // not the array entry's 99.
        let (name, limit): (String, Option<f64>) = sqlx::query_as(
            "SELECT name, category_limit FROM categories WHERE budget_id = $1 AND lower(name) = 'food'",
        )
        .bind(budget_id)
        .fetch_one(&pool)
        .await
        .expect("fetch the single food row");
        assert_eq!(name, "Food", "singular casing must win");
        assert_eq!(limit, Some(50.0), "singular limit must win (proves singular precedence)");

        // Cleanup.
        sqlx::query("DELETE FROM audit_logs WHERE budget_id = $1")
            .bind(budget_id).execute(&pool).await.expect("cleanup audit");
        sqlx::query("DELETE FROM categories WHERE budget_id = $1")
            .bind(budget_id).execute(&pool).await.expect("cleanup categories");
        sqlx::query("DELETE FROM budgets WHERE id = $1")
            .bind(budget_id).execute(&pool).await.expect("cleanup budget");
        sqlx::query("DELETE FROM users WHERE id = $1")
            .bind(owner_id).execute(&pool).await.expect("cleanup user");
    }

