    // Partial failure: one valid spec and one whose name exceeds the
    // categories.name VARCHAR(100) NOT NULL constraint. The valid one is created;
    // the over-length one fails its upsert and is skipped. The created category
    // goes to mutation_log (✅) and the failed one to mutation_error (⚠️) — they
    // are split across the two channels so the failure is never hidden under the
    // success marker (#166).
    #[tokio::test]
    #[ignore = "requires Postgres + pgvector; run via: cargo test -- --ignored"]
    async fn chat_create_categories_partial_failure() {
        let url = std::env::var("DATABASE_URL").unwrap_or_else(|_| {
            "postgres://postgres:postgrespassword@localhost:6153/budget_rag".to_string()
        });
        let pool = sqlx::PgPool::connect(&url).await.expect("connect to test db");
        let cipher = std::sync::Arc::new(
            crate::crypto::SecretCipher::new(&[7u8; 32]).expect("build test cipher"),
        );
        let state = AppState { db: pool.clone(), cipher, webauthn: std::sync::Arc::new(crate::passkeys::WebauthnRegistry::for_test()) };

        let suffix = uuid::Uuid::new_v4();
        let owner_id = uuid::Uuid::new_v4();
        let budget_id = uuid::Uuid::new_v4();

        sqlx::query("INSERT INTO users (id, email) VALUES ($1, $2)")
            .bind(owner_id)
            .bind(format!("partialcat-{suffix}@example.test"))
            .execute(&pool)
            .await
            .expect("seed user");
        sqlx::query(
            "INSERT INTO budgets (id, owner_id, name, time_frame, budget_limit, is_default) \
             VALUES ($1, $2, 'Partial Cat', 'monthly', 10000.0, TRUE)",
        )
        .bind(budget_id)
        .bind(owner_id)
        .execute(&pool)
        .await
        .expect("seed budget");

        // 150 chars > VARCHAR(100) -> the upsert for this spec must fail.
        let too_long = "x".repeat(150);

        let params = super::AiActionParams {
            budget_name: None,
            budget_limit: None,
            time_frame: None,
            description: None,
            category_name: None,
            category_type: None,
            category_limit: None,
            amount: None,
            email: None,
            permission_level: None,
            goal_name: None,
            goal_type: None,
            target_amount: None,
            target_date: None,
            linked_category: None,
            note: None,
            reminder_message: None,
            cadence: None,
            name: None,
            target_budget_name: None,
            rollover: None,
            budget_type: None,
            category_rollover: None,
            is_fund: None,
            auto_renew: None,
            amount_mode: None,
            budget_strategy: None,
            child_budget_name: None,
            new_budget_name: None,
            new_category_name: None,
            issue_title: None,
            issue_body: None,
            transaction_match: None,
            new_description: None,
            excluded: None,
            ignore_match: None,
            categories: Some(vec![
                super::AiCategorySpec {
                    category_name: "validcat".to_string(),
                    category_type: Some("expense".to_string()),
                    category_limit: Some(100.0),
                    is_fund: None,
                },
                super::AiCategorySpec {
                    category_name: too_long.clone(),
                    category_type: Some("expense".to_string()),
                    category_limit: Some(200.0),
                    is_fund: None,
                },
            ]),
            account_match: None,
            country: None,
            explicit_category: None,
            institution_query: None,
            currency: None,
            retirement_profile: None,
        };

        let (log, err) =
            super::chat_create_categories(&state, owner_id, Some(budget_id), Some(&params)).await;

        // A partial failure now sets BOTH channels: the created one in the success
        // log (✅) and the failed one in the error (⚠️) — the failure is no longer
        // folded into the success log's "; failed:" suffix.
        let log = log.expect("a partial success must produce a success log");
        let err = err.expect("a partial failure must surface a warning, not be hidden");
        assert!(log.contains("validcat"), "success log must name the created category, got: {log}");
        assert!(!log.contains("failed"), "success log must NOT carry the failed category, got: {log}");
        assert!(
            err.contains("couldn't create the categor"),
            "error must flag the failed category, got: {err}"
        );

        // The valid category exists; the over-length one does not.
        let valid_count: i64 = sqlx::query_scalar(
            "SELECT COUNT(*) FROM categories WHERE budget_id = $1 AND name = 'validcat'",
        )
        .bind(budget_id)
        .fetch_one(&pool)
        .await
        .expect("count valid category");
        assert_eq!(valid_count, 1, "the valid category must be created");

        let bad_count: i64 = sqlx::query_scalar(
            "SELECT COUNT(*) FROM categories WHERE budget_id = $1 AND name = $2",
        )
        .bind(budget_id)
        .bind(&too_long)
        .fetch_one(&pool)
        .await
        .expect("count over-length category");
        assert_eq!(bad_count, 0, "the over-length category must NOT be created");

        // Cleanup.
        sqlx::query("DELETE FROM audit_logs WHERE budget_id = $1")
            .bind(budget_id).execute(&pool).await.expect("cleanup audit");
        sqlx::query("DELETE FROM categories WHERE budget_id = $1")
            .bind(budget_id).execute(&pool).await.expect("cleanup categories");
        sqlx::query("DELETE FROM budgets WHERE id = $1")
            .bind(budget_id).execute(&pool).await.expect("cleanup budget");
        sqlx::query("DELETE FROM users WHERE id = $1")
            .bind(owner_id).execute(&pool).await.expect("cleanup user");
    }

    // Three specs in one call exercise: N > 2, per-entry category_type retention,
