    // CREATE_CATEGORY's upsert is keyed on `ON CONFLICT (budget_id, name)`, and
    // mirror categories (#52) live in the SAME `categories` table under the SAME
    // `UNIQUE (budget_id, name)` constraint. If a requested `category_name`
    // collides with an EXISTING mirror's name, the upsert resolves onto the
    // mirror row and returns the MIRROR's id — this must NOT get fund-enabled
    // (a mirror's "amount" mirrors a linked source budget, not a per-period
    // allocation; fund semantics make no sense on it, matching
    // chat_set_category_fund's rejection of a named mirror target). Seeding
    // follows chat_set_category_fund_rejects_linked_mirror_category's pattern:
    // a parent budget holding the mirror + the source budget it rolls up.
    #[tokio::test]
    #[ignore = "requires Postgres + pgvector; run via: cargo test -- --ignored"]
    async fn chat_create_categories_name_collision_does_not_fund_enable_mirror() {
        let url = std::env::var("DATABASE_URL").unwrap_or_else(|_| {
            "postgres://postgres:postgrespassword@localhost:6153/budget_rag".to_string()
        });
        let pool = sqlx::PgPool::connect(&url).await.expect("connect to test db");
        let user_id = Uuid::new_v4();
        sqlx::query("INSERT INTO users (id, email) VALUES ($1, $2)")
            .bind(user_id)
            .bind(format!("fund-collide-{user_id}@example.test"))
            .execute(&pool)
            .await
            .expect("seed user");

        // Parent budget (holds the mirror category) + a source budget it rolls up.
        let parent_id = Uuid::new_v4();
        sqlx::query(
            "INSERT INTO budgets (id, owner_id, name, time_frame, budget_type) \
             VALUES ($1, $2, 'Fund Collide Parent', 'monthly', 'time_based')",
        )
        .bind(parent_id)
        .bind(user_id)
        .execute(&pool)
        .await
        .expect("seed parent budget");
        let source_id = Uuid::new_v4();
        sqlx::query(
            "INSERT INTO budgets (id, owner_id, name, time_frame, budget_type) \
             VALUES ($1, $2, 'Fund Collide Source', 'monthly', 'time_based')",
        )
        .bind(source_id)
        .bind(user_id)
        .execute(&pool)
        .await
        .expect("seed source budget");

        // Seed the mirror category directly via SQL: category_type = 'expense',
        // category_limit NULL, linked_budget_id pointing at the source.
        let mirror_id = Uuid::new_v4();
        sqlx::query(
            "INSERT INTO categories (id, budget_id, name, category_type, category_limit, linked_budget_id) \
             VALUES ($1, $2, 'Source (rolled up)', 'expense', NULL, $3)",
        )
        .bind(mirror_id)
        .bind(parent_id)
        .bind(source_id)
        .execute(&pool)
        .await
        .expect("seed mirror category");

        let state = AppState {
            db: pool.clone(),
            cipher: std::sync::Arc::new(crate::crypto::SecretCipher::new(&[7u8; 32]).unwrap()), webauthn: std::sync::Arc::new(crate::passkeys::WebauthnRegistry::for_test()),
        };

        // CREATE_CATEGORY with a name that EXACTLY collides with the mirror's
        // existing name, requesting is_fund: true.
        let params = AiActionParams {
            category_name: Some("Source (rolled up)".to_string()),
            category_type: Some("expense".to_string()),
            is_fund: Some(true),
            ..Default::default()
        };

        let (_log, err) =
            super::chat_create_categories(&state, user_id, Some(parent_id), Some(&params)).await;
        // The upsert itself is allowed to proceed/no-op as it does today — only
        // the fund-enable step must be skipped, not the whole request.
        assert!(err.is_none(), "the category upsert must still succeed on a name collision: {:?}", err);

        let row = sqlx::query("SELECT is_fund, linked_budget_id FROM categories WHERE id = $1")
            .bind(mirror_id)
            .fetch_one(&pool)
            .await
            .expect("fetch mirror category");
        assert!(
            row.get::<Option<Uuid>, _>("linked_budget_id").is_some(),
            "sanity: the row the upsert touched is still the mirror"
        );
        assert!(
            !row.get::<bool, _>("is_fund"),
            "a name-collision CREATE_CATEGORY must not fund-enable the mirror it collided into"
        );

        sqlx::query("DELETE FROM categories WHERE budget_id IN ($1, $2)")
            .bind(parent_id)
            .bind(source_id)
            .execute(&pool)
            .await
            .ok();
        sqlx::query("DELETE FROM budgets WHERE id IN ($1, $2)")
            .bind(parent_id)
            .bind(source_id)
            .execute(&pool)
            .await
            .ok();
        sqlx::query("DELETE FROM users WHERE id = $1").bind(user_id).execute(&pool).await.ok();
    }

