    // Re-enabling a fund category after it was disabled must RESUME from the
    // preserved balance, not zero it out again — the whole point of
    // `chat_set_category_fund_disable_preserves_balance` above is that the
    // balance survives while off; this test proves the OTHER half of the
    // non-destructive-toggle contract (AGENTS.md §12 / `Category.fund_balance`
    // doc comment): a subsequent re-enable resumes from that preserved balance
    // instead of resetting it to 0 (#228).
    #[tokio::test]
    #[ignore = "requires Postgres + pgvector; run via: cargo test -- --ignored"]
    async fn chat_set_category_fund_reenable_after_disable_preserves_balance() {
        let url = std::env::var("DATABASE_URL").unwrap_or_else(|_| {
            "postgres://postgres:postgrespassword@localhost:6153/budget_rag".to_string()
        });
        let pool = sqlx::PgPool::connect(&url).await.expect("connect to test db");
        let user_id = Uuid::new_v4();
        sqlx::query("INSERT INTO users (id, email) VALUES ($1, $2)")
            .bind(user_id)
            .bind(format!("fund-reenable-{user_id}@example.test"))
            .execute(&pool)
            .await
            .expect("seed user");
        let budget_id = Uuid::new_v4();
        sqlx::query(
            "INSERT INTO budgets (id, owner_id, name, time_frame, budget_type) \
             VALUES ($1, $2, 'Fund Reenable Test', 'monthly', 'time_based')",
        )
        .bind(budget_id)
        .bind(user_id)
        .execute(&pool)
        .await
        .expect("seed budget");
        let cat_id = Uuid::new_v4();
        sqlx::query(
            "INSERT INTO categories (id, budget_id, name, category_type, category_limit) \
             VALUES ($1, $2, 'Groceries', 'expense', 100.0)",
        )
        .bind(cat_id)
        .bind(budget_id)
        .execute(&pool)
        .await
        .expect("seed category");

        let state = AppState {
            db: pool.clone(),
            cipher: std::sync::Arc::new(crate::crypto::SecretCipher::new(&[7u8; 32]).unwrap()), webauthn: std::sync::Arc::new(crate::passkeys::WebauthnRegistry::for_test()),
        };

        // 1. Enable the fund: fresh enable resets balance to 0 (fine — this is
        // the correct, already-tested behavior for a category that was NEVER a
        // fund before).
        let enable_params = AiActionParams {
            category_name: Some("Groceries".to_string()),
            is_fund: Some(true),
            ..Default::default()
        };
        let (_log, err) =
            super::chat_set_category_fund(&state, user_id, Some(budget_id), Some(&enable_params)).await;
        assert!(err.is_none(), "expected no error enabling: {:?}", err);

        // 2. Simulate a real accrued balance from a completed period (as the
        // background job would produce) via direct SQL.
        sqlx::query("UPDATE categories SET fund_balance = 42.0 WHERE id = $1")
            .bind(cat_id)
            .execute(&pool)
            .await
            .expect("bump fund_balance");

        // 3. Disable the fund: balance must be preserved (already covered by
        // chat_set_category_fund_disable_preserves_balance, re-asserted here as
        // this test's own setup for step 4).
        let disable_params = AiActionParams {
            category_name: Some("Groceries".to_string()),
            is_fund: Some(false),
            ..Default::default()
        };
        let (_log, err) =
            super::chat_set_category_fund(&state, user_id, Some(budget_id), Some(&disable_params)).await;
        assert!(err.is_none(), "expected no error disabling: {:?}", err);

        let row = sqlx::query("SELECT is_fund, fund_balance FROM categories WHERE id = $1")
            .bind(cat_id)
            .fetch_one(&pool)
            .await
            .expect("fetch category after disable");
        assert!(!row.get::<bool, _>("is_fund"));
        assert_eq!(row.get::<f64, _>("fund_balance"), 42.0, "balance preserved while disabled");

        let marker_before_reenable: Option<DateTime<Utc>> =
            sqlx::query_scalar("SELECT fund_advanced_through FROM categories WHERE id = $1")
                .bind(cat_id)
                .fetch_one(&pool)
                .await
                .expect("fetch marker before re-enable");

        // 4. Re-enable the fund: THIS is the bug this test pins down. Against
        // the buggy `enable_category_fund` (unconditional `fund_balance = 0`),
        // this assertion fails because the balance gets wiped back to 0. The
        // fix distinguishes "never was a fund" (fund_advanced_through IS NULL)
        // from "was a fund, now re-enabling" (fund_advanced_through IS NOT
        // NULL) and only zeroes the balance in the former case.
        let (_log, err) =
            super::chat_set_category_fund(&state, user_id, Some(budget_id), Some(&enable_params)).await;
        assert!(err.is_none(), "expected no error re-enabling: {:?}", err);

        let row = sqlx::query(
            "SELECT is_fund, fund_balance, fund_advanced_through FROM categories WHERE id = $1",
        )
        .bind(cat_id)
        .fetch_one(&pool)
        .await
        .expect("fetch category after re-enable");
        assert!(row.get::<bool, _>("is_fund"));
        assert_eq!(
            row.get::<f64, _>("fund_balance"),
            42.0,
            "re-enable must RESUME from the preserved balance, not reset it to 0"
        );
        let marker_after_reenable: Option<DateTime<Utc>> = row.get("fund_advanced_through");
        assert!(marker_after_reenable.is_some());
        assert!(
            marker_after_reenable >= marker_before_reenable,
            "fund_advanced_through must be reset to the CURRENT period start on re-enable \
             (periods elapsed while disabled don't count)"
        );

        sqlx::query("DELETE FROM audit_logs WHERE budget_id = $1").bind(budget_id).execute(&pool).await.ok();
        sqlx::query("DELETE FROM categories WHERE budget_id = $1").bind(budget_id).execute(&pool).await.ok();
        sqlx::query("DELETE FROM budgets WHERE id = $1").bind(budget_id).execute(&pool).await.ok();
        sqlx::query("DELETE FROM users WHERE id = $1").bind(user_id).execute(&pool).await.ok();
    }

    // A linked/mirror category (#52) is system-managed — its "amount" mirrors a
    // source budget's total rather than representing a per-period allocation —
    // so SET_CATEGORY_FUND must reject naming one explicitly, the same way
    // `update_category` (budget.rs) rejects editing one (#228).
    #[tokio::test]
    #[ignore = "requires Postgres + pgvector; run via: cargo test -- --ignored"]
    async fn chat_set_category_fund_rejects_linked_mirror_category() {
        let url = std::env::var("DATABASE_URL").unwrap_or_else(|_| {
            "postgres://postgres:postgrespassword@localhost:6153/budget_rag".to_string()
        });
        let pool = sqlx::PgPool::connect(&url).await.expect("connect to test db");
        let user_id = Uuid::new_v4();
        sqlx::query("INSERT INTO users (id, email) VALUES ($1, $2)")
            .bind(user_id)
            .bind(format!("fund-mirror-{user_id}@example.test"))
            .execute(&pool)
            .await
            .expect("seed user");

        // Parent budget (holds the mirror category) + a source budget it rolls up.
        let parent_id = Uuid::new_v4();
        sqlx::query(
            "INSERT INTO budgets (id, owner_id, name, time_frame, budget_type) \
             VALUES ($1, $2, 'Fund Mirror Parent', 'monthly', 'time_based')",
        )
        .bind(parent_id)
        .bind(user_id)
        .execute(&pool)
        .await
        .expect("seed parent budget");
        let source_id = Uuid::new_v4();
        sqlx::query(
            "INSERT INTO budgets (id, owner_id, name, time_frame, budget_type) \
             VALUES ($1, $2, 'Fund Mirror Source', 'monthly', 'time_based')",
        )
        .bind(source_id)
        .bind(user_id)
        .execute(&pool)
        .await
        .expect("seed source budget");

        // Seed the mirror category directly via SQL, matching the pattern
        // existing rollup tests use (see budget.rs's mirror_category_includes_
        // source_total_in_parent): category_type = 'expense', category_limit
        // NULL, linked_budget_id pointing at the source.
        let mirror_id = Uuid::new_v4();
        sqlx::query(
            "INSERT INTO categories (id, budget_id, name, category_type, category_limit, linked_budget_id) \
             VALUES ($1, $2, 'Source (rolled up)', 'expense', NULL, $3)",
        )
        .bind(mirror_id)
        .bind(parent_id)
        .bind(source_id)
        .execute(&pool)
        .await
        .expect("seed mirror category");

        let state = AppState {
            db: pool.clone(),
            cipher: std::sync::Arc::new(crate::crypto::SecretCipher::new(&[7u8; 32]).unwrap()), webauthn: std::sync::Arc::new(crate::passkeys::WebauthnRegistry::for_test()),
        };
        let params = AiActionParams {
            category_name: Some("Source (rolled up)".to_string()),
            is_fund: Some(true),
            ..Default::default()
        };

        let (log, err) =
            super::chat_set_category_fund(&state, user_id, Some(parent_id), Some(&params)).await;
        assert!(log.is_none());
        assert!(err.is_some(), "expected a clear error rejecting a linked/mirror target");
        assert!(
            err.unwrap().contains("linked rollup category"),
            "error should explain the target is a linked rollup category"
        );

        let row = sqlx::query("SELECT is_fund FROM categories WHERE id = $1")
            .bind(mirror_id)
            .fetch_one(&pool)
            .await
            .expect("fetch mirror category");
        assert!(!row.get::<bool, _>("is_fund"), "rejected mutation must not have applied");

        sqlx::query("DELETE FROM categories WHERE budget_id IN ($1, $2)")
            .bind(parent_id)
            .bind(source_id)
            .execute(&pool)
            .await
            .ok();
        sqlx::query("DELETE FROM budgets WHERE id IN ($1, $2)")
            .bind(parent_id)
            .bind(source_id)
            .execute(&pool)
            .await
            .ok();
        sqlx::query("DELETE FROM users WHERE id = $1").bind(user_id).execute(&pool).await.ok();
    }

    // A category that already exists is UPDATED in place via ON CONFLICT DO UPDATE:
    // its limit changes, no duplicate row appears, and rollover_enabled is left
    // untouched (the upsert deliberately updates ONLY category_limit) (#166).
