    /// A non-US profile gets NO Social Security sentence in chat at all.
    ///
    /// `social_security_view` returns `None` outside the supported region, and
    /// the log is built from it — so a French user cannot be handed a US SSA
    /// full retirement age. Without this, the non-US path would be disclosed by
    /// `RETIREMENT_NON_US_NOTE` in one sentence and contradicted by a US statute
    /// readout in the next.
    #[tokio::test]
    #[ignore = "requires Postgres + pgvector; run via: cargo test -- --ignored"]
    async fn chat_log_omits_the_social_security_sentence_for_a_non_us_profile() {
        let url = std::env::var("DATABASE_URL").unwrap_or_else(|_| {
            "postgres://postgres:postgrespassword@localhost:6153/budget_rag".to_string()
        });
        let pool = sqlx::PgPool::connect(&url).await.expect("connect to test db");
        let cipher = std::sync::Arc::new(
            crate::crypto::SecretCipher::new(&[7u8; 32]).expect("build test cipher"),
        );
        let state = AppState { db: pool.clone(), cipher, webauthn: std::sync::Arc::new(crate::passkeys::WebauthnRegistry::for_test()) };

        let user_id = uuid::Uuid::new_v4();
        sqlx::query("INSERT INTO users (id, email) VALUES ($1, $2)")
            .bind(user_id)
            .bind(format!("chat-ss-fr-{user_id}@example.test"))
            .execute(&pool)
            .await
            .expect("seed user");
        seed_pro_subscriber(&pool, user_id).await;

        let params = AiActionParams {
            retirement_profile: Some(crate::retirement::RetirementProfileInput {
                country: Some("FR".to_string()),
                birth_date: Some(chrono::NaiveDate::from_ymd_opt(1960, 6, 15).unwrap()),
                current_gross_income: Some(120_000.0),
                // EXPLICIT, and it has to be. `chat_set_retirement_profile`
                // calls `upsert_profile` with `Utc::now()`, so a fixture that
                // relies on the default target retirement age of 65 rots the
                // moment this birth cohort passes 65 — which it already has.
                target_retirement_age: Some(72),
                ss_monthly_benefit: Some(2_400.0),
                ss_benefit_at_age: Some(crate::retirement::SsAnchor::Age(67)),
                ss_claiming_age: Some(crate::retirement::SsAnchor::Age(70)),
                ..Default::default()
            }),
            ..blank_action_params()
        };

        let (log, err, _) = chat_set_retirement_profile(&state, user_id, Some(&params)).await;
        assert_eq!(err, None, "a non-US profile still SAVES");
        let log = log.expect("success log");
        assert!(
            !log.contains("full retirement age"),
            "a non-US user must not be handed a US SSA full retirement age: {log}"
        );
        assert!(!log.contains("Social Security:"), "{log}");
        assert!(log.contains(RETIREMENT_NON_US_NOTE), "the non-US limit is still disclosed: {log}");
    }

    /// The ADD_TRANSACTION guard, driven through the REAL offline if/else chain.
    ///
    /// `contains("log") || contains("spent")` sits directly ABOVE the retirement
    /// arm, so "log my social security benefit" was claimed there and fabricated
    /// a $15 "Utilities" transaction the user never made. The unit tests assert
    /// the guard's PRECONDITION — that `offline_retirement_action` claims the
    /// phrase — but deleting the guard itself left every one of them green,
    /// because none of them executes the chain. This one does.
    #[tokio::test]
    #[ignore = "requires Postgres + pgvector; run via: cargo test -- --ignored"]
    async fn chat_endpoint_does_not_log_a_transaction_for_a_social_security_message() {
        // #269: see GEMINI_ENV_LOCK's doc comment.
        let _gemini_env = GEMINI_ENV_LOCK.lock().unwrap_or_else(|e| e.into_inner());
        struct EnvGuard(Option<String>);
        impl Drop for EnvGuard {
            fn drop(&mut self) {
                match &self.0 {
                    Some(v) => std::env::set_var("GEMINI_API_KEY", v),
                    None => std::env::remove_var("GEMINI_API_KEY"),
                }
            }
        }
        let _env_guard = EnvGuard(std::env::var("GEMINI_API_KEY").ok());
        std::env::remove_var("GEMINI_API_KEY");

        let url = std::env::var("DATABASE_URL").unwrap_or_else(|_| {
            "postgres://postgres:postgrespassword@localhost:6153/budget_rag".to_string()
        });
        let pool = sqlx::PgPool::connect(&url).await.expect("connect to test db");
        let cipher = std::sync::Arc::new(
            crate::crypto::SecretCipher::new(&[7u8; 32]).expect("build test cipher"),
        );
        let state = AppState { db: pool.clone(), cipher, webauthn: std::sync::Arc::new(crate::passkeys::WebauthnRegistry::for_test()) };

        let user_id = uuid::Uuid::new_v4();
        sqlx::query("INSERT INTO users (id, email) VALUES ($1, $2)")
            .bind(user_id)
            .bind(format!("chat-ss-guard-{user_id}@example.test"))
            .execute(&pool)
            .await
            .expect("seed user");
        seed_pro_subscriber(&pool, user_id).await;

        let before: i64 = sqlx::query_scalar("SELECT count(*) FROM transactions")
            .fetch_one(&pool)
            .await
            .expect("count transactions");

        let resp = chat_endpoint(
            State(state.clone()),
            Extension(user_id),
            Json(ChatRequest {
                message: "log my social security benefit of 2400".to_string(),
                budget_id: None,
                conversation_id: None,
                locale: None,
            }),
        )
        .await
        .expect("chat call returns Ok");

        let body = resp.0.response;
        assert!(
            !body.contains("Logging transaction"),
            "a Social Security message must NOT be claimed by the ADD_TRANSACTION arm: {body}"
        );
        assert!(
            !body.contains("Utilities"),
            "and must certainly not invent a Utilities expense: {body}"
        );
        let after: i64 = sqlx::query_scalar("SELECT count(*) FROM transactions")
            .fetch_one(&pool)
            .await
            .expect("count transactions");
        assert_eq!(before, after, "no transaction row may be written");
    }

    #[tokio::test]
    #[ignore = "requires Postgres + pgvector; run via: cargo test -- --ignored"]
    async fn chat_endpoint_routes_set_retirement_profile_and_asks_once_without_a_warning() {
        // #269: see GEMINI_ENV_LOCK's doc comment — every GEMINI_API_KEY-touching test must hold this.
        let _gemini_env = GEMINI_ENV_LOCK.lock().unwrap_or_else(|e| e.into_inner());
        struct EnvGuard(Option<String>);
        impl Drop for EnvGuard {
            fn drop(&mut self) {
                match &self.0 {
                    Some(v) => std::env::set_var("GEMINI_API_KEY", v),
                    None => std::env::remove_var("GEMINI_API_KEY"),
                }
            }
        }
        let _env_guard = EnvGuard(std::env::var("GEMINI_API_KEY").ok());
        std::env::remove_var("GEMINI_API_KEY");

        let url = std::env::var("DATABASE_URL").unwrap_or_else(|_| {
            "postgres://postgres:postgrespassword@localhost:6153/budget_rag".to_string()
        });
        let pool = sqlx::PgPool::connect(&url).await.expect("connect to test db");
        let cipher = std::sync::Arc::new(
            crate::crypto::SecretCipher::new(&[7u8; 32]).expect("build test cipher"),
        );
        let state = AppState { db: pool.clone(), cipher, webauthn: std::sync::Arc::new(crate::passkeys::WebauthnRegistry::for_test()) };

        let user_id = uuid::Uuid::new_v4();
        sqlx::query("INSERT INTO users (id, email) VALUES ($1, $2)")
            .bind(user_id)
            .bind(format!("chat-ret-e2e-{user_id}@example.test"))
            .execute(&pool)
            .await
            .expect("seed user");
        seed_pro_subscriber(&pool, user_id).await;

        // `offline_retirement_action`'s matching phrasing. The offline router
        // routes the action but supplies NO params, which is exactly the
        // clarifying case.
        let resp = chat_endpoint(
            State(state.clone()),
            Extension(user_id),
            Json(ChatRequest {
                message: "set up my retirement profile".to_string(),
                budget_id: None,
                conversation_id: None,
                locale: None,
            }),
        )
        .await
        .expect("retirement chat call returns Ok");

        let body = resp.0.response;
        assert!(
            body.contains("annual gross income"),
            "the arm ran and asked for the create fields: {body}"
        );
        // #300's precedent: a question is not a failure, so no warning marker.
        assert!(
            !body.contains("⚠️"),
            "nothing was attempted and nothing failed, so no warning may appear: {body}"
        );
        // Asked ONCE. The arm's clarification overrode the offline router's own
        // "tell me your country, date of birth and annual gross income" line
        // rather than being appended below it.
        assert_eq!(
            body.matches("annual gross income").count(),
            1,
            "the user must not be asked the same thing twice in one reply: {body}"
        );
        assert!(
            !body.contains("Mock AI Offline Mode"),
            "the override replaced the router's canned text entirely: {body}"
        );
        // A clarifying question writes nothing.
        let rows: i64 = sqlx::query_scalar("SELECT COUNT(*) FROM retirement_profiles WHERE user_id = $1")
            .bind(user_id)
            .fetch_one(&pool)
            .await
            .expect("count profiles");
        assert_eq!(rows, 0);

        sqlx::query("DELETE FROM chat_messages WHERE user_id = $1")
            .bind(user_id).execute(&pool).await.expect("cleanup messages");
        sqlx::query("DELETE FROM conversations WHERE user_id = $1")
            .bind(user_id).execute(&pool).await.expect("cleanup conversations");
        sqlx::query("DELETE FROM users WHERE id = $1")
            .bind(user_id).execute(&pool).await.expect("cleanup user");
    }

    /// A non-US profile SAVES, and the reply says the projection will not appear.
    ///
    /// REST carries `supported: false` on the response, but this release ships
    /// no frontend at all, so without this sentence nothing anywhere discloses
    /// the US-only limit. The user would get a confirmation listing every field
    /// they gave and then watch the feature never materialise.
    ///
    /// The note is a statement of fact about product behaviour, not advice, so
    /// it does not cross #454 decision 3 — and the no-editorializing assertions
    /// are re-run here to keep it that way.
    #[tokio::test]
