    // ---- #195: transactions updated_at + embedding ----

    // Proves the migration's effects: updated_at defaults to created_at on insert
    // (trigger is BEFORE UPDATE only), advances past created_at on a user-visible
    // UPDATE, and the embedding vector(768) column accepts a 768-dim vector. Also
    // proves the trigger's WHEN clause: an embedding-only write does NOT advance
    // updated_at. Self-sufficient: runs migrate!() and re-applies the corrected
    // trigger DDL so it holds even on a previously-migrated DB.
    #[tokio::test]
    #[ignore = "requires Postgres + pgvector; run via: cargo test -- --ignored"]
    async fn transactions_updated_at_trigger_and_embedding_column() {
        let url = std::env::var("DATABASE_URL").unwrap_or_else(|_| {
            "postgres://postgres:postgrespassword@localhost:6153/budget_rag".to_string()
        });
        let pool = sqlx::PgPool::connect(&url).await.expect("connect to test db");
        // New DB tests must be self-sufficient: ensure our migration is applied.
        sqlx::migrate!("./migrations").run(&pool).await.expect("apply migrations");

        // The trigger's WHEN clause may post-date a prior application of this
        // migration on the test DB. sqlx tracks applied versions by filename and
        // will not re-run an edited migration, so apply the corrected trigger DDL
        // explicitly here. This makes the test self-sufficient regardless of the
        // DB's prior migration state.
        sqlx::query("DROP TRIGGER IF EXISTS trg_transactions_updated_at ON transactions")
            .execute(&pool)
            .await
            .expect("drop stale updated_at trigger");
        sqlx::query(
            "CREATE TRIGGER trg_transactions_updated_at \
               BEFORE UPDATE ON transactions FOR EACH ROW \
               WHEN (OLD.description IS DISTINCT FROM NEW.description \
                  OR OLD.amount IS DISTINCT FROM NEW.amount \
                  OR OLD.transaction_date IS DISTINCT FROM NEW.transaction_date \
                  OR OLD.category_id IS DISTINCT FROM NEW.category_id) \
               EXECUTE FUNCTION set_updated_at()",
        )
        .execute(&pool)
        .await
        .expect("apply corrected updated_at trigger");

        let owner_id = uuid::Uuid::new_v4();
        let budget_id = uuid::Uuid::new_v4();
        let tx_id = uuid::Uuid::new_v4();

        sqlx::query("INSERT INTO users (id, email) VALUES ($1, $2)")
            .bind(owner_id)
            .bind(format!("tx-updated-{owner_id}@example.test"))
            .execute(&pool)
            .await
            .expect("seed user");
        sqlx::query(
            "INSERT INTO budgets (id, owner_id, name, time_frame, budget_limit, is_default) \
             VALUES ($1, $2, 'updated-at test', 'monthly', 1000.0, FALSE)",
        )
        .bind(budget_id)
        .bind(owner_id)
        .execute(&pool)
        .await
        .expect("seed budget");

        sqlx::query(
            "INSERT INTO transactions (id, budget_id, category_id, amount, transaction_date, description) \
             VALUES ($1, $2, NULL, $3, NOW(), $4)",
        )
        .bind(tx_id)
        .bind(budget_id)
        .bind(10.0_f64)
        .bind("initial")
        .execute(&pool)
        .await
        .expect("seed transaction");

        // At insert the trigger has not fired (BEFORE UPDATE only), so both
        // timestamps share the transaction-start NOW().
        let equal_at_insert: bool = sqlx::query_scalar(
            "SELECT updated_at = created_at FROM transactions WHERE id = $1",
        )
        .bind(tx_id)
        .fetch_one(&pool)
        .await
        .expect("read timestamps");
        assert!(equal_at_insert, "updated_at should equal created_at at insert");

        // An UPDATE in a later transaction advances updated_at past created_at.
        sqlx::query("UPDATE transactions SET description = $2 WHERE id = $1")
            .bind(tx_id)
            .bind("changed")
            .execute(&pool)
            .await
            .expect("update transaction");
        let advanced: bool = sqlx::query_scalar(
            "SELECT updated_at > created_at FROM transactions WHERE id = $1",
        )
        .bind(tx_id)
        .fetch_one(&pool)
        .await
        .expect("read timestamps after update");
        assert!(advanced, "updated_at should advance past created_at after UPDATE");

        // A user-visible UPDATE to a non-description column (amount) also bumps
        // updated_at: the WHEN clause covers amount via IS DISTINCT FROM.
        let updated_before_amount: chrono::DateTime<chrono::Utc> = sqlx::query_scalar(
            "SELECT updated_at FROM transactions WHERE id = $1",
        )
        .bind(tx_id)
        .fetch_one(&pool)
        .await
        .expect("read updated_at before amount update");
        sqlx::query("UPDATE transactions SET amount = $2 WHERE id = $1")
            .bind(tx_id)
            .bind(20.0_f64)
            .execute(&pool)
            .await
            .expect("update amount");
        let updated_after_amount: chrono::DateTime<chrono::Utc> = sqlx::query_scalar(
            "SELECT updated_at FROM transactions WHERE id = $1",
        )
        .bind(tx_id)
        .fetch_one(&pool)
        .await
        .expect("read updated_at after amount update");
        assert!(
            updated_after_amount > updated_before_amount,
            "updated_at should advance after an amount UPDATE"
        );

        // A no-op UPDATE that sets a column to its SAME value must NOT bump
        // updated_at: the WHEN clause uses IS DISTINCT FROM, so an unchanged value
        // does not fire the trigger.
        sqlx::query("UPDATE transactions SET amount = $2 WHERE id = $1")
            .bind(tx_id)
            .bind(20.0_f64)
            .execute(&pool)
            .await
            .expect("no-op update amount to same value");
        let updated_after_noop: chrono::DateTime<chrono::Utc> = sqlx::query_scalar(
            "SELECT updated_at FROM transactions WHERE id = $1",
        )
        .bind(tx_id)
        .fetch_one(&pool)
        .await
        .expect("read updated_at after no-op update");
        assert_eq!(
            updated_after_amount, updated_after_noop,
            "a no-op UPDATE (same value) must NOT advance updated_at"
        );

        // Snapshot updated_at after the user-visible UPDATE so we can prove an
        // embedding-only write leaves it untouched.
        let updated_before_embedding: chrono::DateTime<chrono::Utc> = sqlx::query_scalar(
            "SELECT updated_at FROM transactions WHERE id = $1",
        )
        .bind(tx_id)
        .fetch_one(&pool)
        .await
        .expect("read updated_at before embedding write");

        // The embedding vector(768) column accepts a 768-dim vector via $1::vector.
        // An embedding-only write touches no user-visible column, so the trigger's
        // WHEN clause must keep it from firing: updated_at must NOT advance.
        let vec_str = vector_to_string(&vec![0.0_f32; 768]);
        sqlx::query("UPDATE transactions SET embedding = $1::vector WHERE id = $2")
            .bind(&vec_str)
            .bind(tx_id)
            .execute(&pool)
            .await
            .expect("set embedding on transaction");
        let has_embedding: bool = sqlx::query_scalar(
            "SELECT embedding IS NOT NULL FROM transactions WHERE id = $1",
        )
        .bind(tx_id)
        .fetch_one(&pool)
        .await
        .expect("read embedding state");
        assert!(has_embedding, "embedding column should hold the 768-dim vector");

        let updated_after_embedding: chrono::DateTime<chrono::Utc> = sqlx::query_scalar(
            "SELECT updated_at FROM transactions WHERE id = $1",
        )
        .bind(tx_id)
        .fetch_one(&pool)
        .await
        .expect("read updated_at after embedding write");
        assert_eq!(
            updated_before_embedding, updated_after_embedding,
            "embedding-only UPDATE must NOT advance updated_at"
        );

        sqlx::query("DELETE FROM users WHERE id = $1")
            .bind(owner_id)
            .execute(&pool)
            .await
            .expect("cleanup");
    }

    // SEARCH_TRANSACTIONS query (#195): with embeddings seeded directly via SQL,
    // the production search const returns matches ordered by cosine distance and
    // scoped to the budget (a same-vector row in another budget is excluded).
    #[tokio::test]
    #[ignore = "requires Postgres + pgvector; run via: cargo test -- --ignored"]
    async fn transactions_semantic_search_orders_by_distance_and_scopes_to_budget() {
        let url = std::env::var("DATABASE_URL").unwrap_or_else(|_| {
            "postgres://postgres:postgrespassword@localhost:6153/budget_rag".to_string()
        });
        let pool = sqlx::PgPool::connect(&url).await.expect("connect to test db");
        sqlx::migrate!("./migrations").run(&pool).await.expect("apply migrations");

        let owner_id = uuid::Uuid::new_v4();
        let budget_id = uuid::Uuid::new_v4();
        let other_budget_id = uuid::Uuid::new_v4();

        // A 768-dim unit-ish vector with `value` at `idx`, else 0.
        fn axis_vec(idx: usize, value: f32) -> Vec<f32> {
            let mut v = vec![0.0_f32; 768];
            v[idx] = value;
            v
        }

        sqlx::query("INSERT INTO users (id, email) VALUES ($1, $2)")
            .bind(owner_id)
            .bind(format!("tx-search-{owner_id}@example.test"))
            .execute(&pool)
            .await
            .expect("seed user");
        for (bid, name) in [(budget_id, "search test"), (other_budget_id, "other budget")] {
            sqlx::query(
                "INSERT INTO budgets (id, owner_id, name, time_frame, budget_limit, is_default) \
                 VALUES ($1, $2, $3, 'monthly', 1000.0, FALSE)",
            )
            .bind(bid)
            .bind(owner_id)
            .bind(name)
            .execute(&pool)
            .await
            .expect("seed budget");
        }

        async fn seed_tx(
            pool: &sqlx::PgPool,
            bid: uuid::Uuid,
            desc: &str,
            embedding: &[f32],
        ) {
            sqlx::query(
                "INSERT INTO transactions (id, budget_id, category_id, amount, transaction_date, description, embedding) \
                 VALUES ($1, $2, NULL, 1.0, NOW(), $3, $4::vector)",
            )
            .bind(uuid::Uuid::new_v4())
            .bind(bid)
            .bind(desc)
            .bind(vector_to_string(embedding))
            .execute(pool)
            .await
            .expect("seed transaction");
        }

        // In-budget rows aligned to different axes; a query near axis 0 (with a
        // smaller axis-1 component) orders A (axis0) < B (axis1) < C (axis2).
        seed_tx(&pool, budget_id, "alpha", &axis_vec(0, 1.0)).await;
        seed_tx(&pool, budget_id, "bravo", &axis_vec(1, 1.0)).await;
        seed_tx(&pool, budget_id, "charlie", &axis_vec(2, 1.0)).await;
        // A row in another budget that exactly matches the query — must be excluded.
        seed_tx(&pool, other_budget_id, "intruder", &axis_vec(0, 1.0)).await;
        // An in-budget row with a NULL embedding: it must NEVER appear, proving the
        // query's `embedding IS NOT NULL` clause is load-bearing (a NULL embedding
        // has no distance to order by and would otherwise pollute results).
        sqlx::query(
            "INSERT INTO transactions (id, budget_id, category_id, amount, transaction_date, description) \
             VALUES ($1, $2, NULL, 1.0, NOW(), 'ghost')",
        )
        .bind(uuid::Uuid::new_v4())
        .bind(budget_id)
        .execute(&pool)
        .await
        .expect("seed null-embedding transaction");

        let mut q = vec![0.0_f32; 768];
        q[0] = 1.0;
        q[1] = 0.5;
        let q_str = vector_to_string(&q);

        let rows = sqlx::query(TRANSACTIONS_SEMANTIC_SEARCH_QUERY)
            .bind(budget_id)
            .bind(&q_str)
            .fetch_all(&pool)
            .await
            .expect("run semantic search");

        let descs: Vec<String> = rows.iter().map(|r| r.get::<String, _>("description")).collect();
        assert_eq!(
            descs,
            vec!["alpha".to_string(), "bravo".to_string(), "charlie".to_string()],
            "matches must be ordered by cosine distance and exclude other budgets"
        );
        assert!(
            !descs.contains(&"intruder".to_string()),
            "another budget's transaction must never appear"
        );
        assert!(
            !descs.contains(&"ghost".to_string()),
            "a NULL-embedding row must never appear (embedding IS NOT NULL is load-bearing)"
        );

        sqlx::query("DELETE FROM users WHERE id = $1")
            .bind(owner_id)
            .execute(&pool)
            .await
            .expect("cleanup");
    }

    // LIST_TRANSACTIONS query (#229): the deterministic category-scoped filter
    // returns ONLY the matching category's transactions in the matching budget —
    // ordered by date desc, complete (no LIMIT) — and excludes a same-named
    // category in a different budget and a different category in the same
    // budget. This is the exact class of bug the ticket reports (category
    // bleed), so every exclusion case is asserted explicitly.
    #[tokio::test]
    #[ignore = "requires Postgres + pgvector; run via: cargo test -- --ignored"]
    async fn transactions_by_category_scopes_to_budget_and_category() {
        let url = std::env::var("DATABASE_URL").unwrap_or_else(|_| {
            "postgres://postgres:postgrespassword@localhost:6153/budget_rag".to_string()
        });
        let pool = sqlx::PgPool::connect(&url).await.expect("connect to test db");
        sqlx::migrate!("./migrations").run(&pool).await.expect("apply migrations");

        let owner_id = uuid::Uuid::new_v4();
        let budget_id = uuid::Uuid::new_v4();
        let other_budget_id = uuid::Uuid::new_v4();

        sqlx::query("INSERT INTO users (id, email) VALUES ($1, $2)")
            .bind(owner_id)
            .bind(format!("tx-by-cat-{owner_id}@example.test"))
            .execute(&pool)
            .await
            .expect("seed user");
        for (bid, name) in [(budget_id, "cat filter test"), (other_budget_id, "other budget")] {
            sqlx::query(
                "INSERT INTO budgets (id, owner_id, name, time_frame, budget_limit, is_default) \
                 VALUES ($1, $2, $3, 'monthly', 1000.0, FALSE)",
            )
            .bind(bid)
            .bind(owner_id)
            .bind(name)
            .execute(&pool)
            .await
            .expect("seed budget");
        }

        // Two categories in the target budget, sharing a name with a category
        // in the OTHER budget — proves the bug class (category bleed across
        // budgets sharing a name) cannot happen.
        async fn seed_category(pool: &sqlx::PgPool, bid: uuid::Uuid, name: &str) -> uuid::Uuid {
            let id = uuid::Uuid::new_v4();
            sqlx::query(
                "INSERT INTO categories (id, budget_id, name, category_type) VALUES ($1, $2, $3, 'expense')",
            )
            .bind(id)
            .bind(bid)
            .bind(name)
            .execute(pool)
            .await
            .expect("seed category");
            id
        }
        let cat_food = seed_category(&pool, budget_id, "Food").await;
        let cat_travel = seed_category(&pool, budget_id, "Travel").await;
        let other_budget_cat_food = seed_category(&pool, other_budget_id, "Food").await;

        async fn seed_tx(
            pool: &sqlx::PgPool,
            bid: uuid::Uuid,
            cat_id: uuid::Uuid,
            desc: &str,
            date: chrono::DateTime<chrono::Utc>,
        ) {
            sqlx::query(
                "INSERT INTO transactions (id, budget_id, category_id, amount, transaction_date, description) \
                 VALUES ($1, $2, $3, 1.0, $4, $5)",
            )
            .bind(uuid::Uuid::new_v4())
            .bind(bid)
            .bind(cat_id)
            .bind(date)
            .bind(desc)
            .execute(pool)
            .await
            .expect("seed transaction");
        }

        let now = chrono::Utc::now();
        // In target category (Food, target budget) — the rows the query must
        // return, oldest-to-newest date so the ORDER BY assertion is meaningful.
        seed_tx(&pool, budget_id, cat_food, "older food", now - chrono::Duration::days(2)).await;
        seed_tx(&pool, budget_id, cat_food, "newer food", now - chrono::Duration::days(1)).await;
        // A DIFFERENT category in the SAME budget — must be excluded.
        seed_tx(&pool, budget_id, cat_travel, "travel expense", now).await;
        // The SAME category NAME in a DIFFERENT budget — must be excluded (this
        // is exactly the bleed the ticket reports if budget scoping were
        // dropped).
        seed_tx(&pool, other_budget_id, other_budget_cat_food, "other budget food", now).await;

        let rows = sqlx::query(TRANSACTIONS_BY_CATEGORY_QUERY)
            .bind(budget_id)
            .bind(cat_food)
            .fetch_all(&pool)
            .await
            .expect("run category-scoped listing");

        let descs: Vec<String> = rows.iter().map(|r| r.get::<String, _>("description")).collect();
        assert_eq!(
            descs,
            vec!["newer food".to_string(), "older food".to_string()],
            "must return only the target category's rows in the target budget, newest first, complete (no LIMIT)"
        );
        assert!(!descs.contains(&"travel expense".to_string()), "a different category in the same budget must never appear");
        assert!(!descs.contains(&"other budget food".to_string()), "a same-named category in a different budget must never appear");

        // A category with zero transactions returns an empty result, not an error.
        let empty_cat = seed_category(&pool, budget_id, "Empty").await;
        let empty_rows = sqlx::query(TRANSACTIONS_BY_CATEGORY_QUERY)
            .bind(budget_id)
            .bind(empty_cat)
            .fetch_all(&pool)
            .await
            .expect("run category-scoped listing for empty category");
        assert!(empty_rows.is_empty(), "a category with zero transactions must return an explicit empty result");

        sqlx::query("DELETE FROM users WHERE id = $1")
            .bind(owner_id)
            .execute(&pool)
            .await
            .expect("cleanup");
    }

    // Arm-level coverage for the LIST_TRANSACTIONS dispatch arm (#229 PR
    // review): the DB-backed test above exercises TRANSACTIONS_BY_CATEGORY_QUERY
    // directly, and the pure-formatter tests exercise the message-rendering
    // helpers directly, but neither drives chat_endpoint's actual
    // "LIST_TRANSACTIONS" => { ... } arm (category resolution + query +
    // formatting, wired together). This uses the SAME
    // EnvGuard/remove_var("GEMINI_API_KEY") pattern already established by
    // chat_add_transaction_new_category_offers_limit et al. to force
    // chat_endpoint through its deterministic offline router — the offline
    // route this PR added (offline_list_transactions_category) makes the
    // arm reachable without a live/mocked Gemini call. Covers three of the
    // arm's branches: a populated category, an empty category, and an
    // unresolvable category name.
    #[tokio::test]
    #[ignore = "requires Postgres + pgvector; run via: cargo test -- --ignored"]
    async fn chat_list_transactions_dispatch_arm_covers_populated_empty_and_not_found() {
        // #269: see GEMINI_ENV_LOCK's doc comment — every GEMINI_API_KEY-touching test must hold this.
        let _gemini_env = GEMINI_ENV_LOCK.lock().unwrap_or_else(|e| e.into_inner());
        struct EnvGuard(Option<String>);
        impl Drop for EnvGuard {
            fn drop(&mut self) {
                match &self.0 {
                    Some(v) => std::env::set_var("GEMINI_API_KEY", v),
                    None => std::env::remove_var("GEMINI_API_KEY"),
                }
            }
        }
        let _env_guard = EnvGuard(std::env::var("GEMINI_API_KEY").ok());
        std::env::remove_var("GEMINI_API_KEY");

        let url = std::env::var("DATABASE_URL").unwrap_or_else(|_| {
            "postgres://postgres:postgrespassword@localhost:6153/budget_rag".to_string()
        });
        let pool = sqlx::PgPool::connect(&url).await.expect("connect to test db");
        let cipher = std::sync::Arc::new(
            crate::crypto::SecretCipher::new(&[7u8; 32]).expect("build test cipher"),
        );
        let state = AppState { db: pool.clone(), cipher, webauthn: std::sync::Arc::new(crate::passkeys::WebauthnRegistry::for_test()) };

        let suffix = uuid::Uuid::new_v4();
        let owner_id = uuid::Uuid::new_v4();
        let budget_id = uuid::Uuid::new_v4();

        sqlx::query("INSERT INTO users (id, email) VALUES ($1, $2)")
            .bind(owner_id)
            .bind(format!("list-tx-arm-{suffix}@example.test"))
            .execute(&pool)
            .await
            .expect("seed user");
        sqlx::query(
            "INSERT INTO budgets (id, owner_id, name, time_frame, budget_limit, is_default) \
             VALUES ($1, $2, 'My Budget', 'monthly', 1000.0, TRUE)",
        )
        .bind(budget_id)
        .bind(owner_id)
        .execute(&pool)
        .await
        .expect("seed budget");

        let food_id = uuid::Uuid::new_v4();
        sqlx::query(
            "INSERT INTO categories (id, budget_id, name, category_type) VALUES ($1, $2, 'Food', 'expense')",
        )
        .bind(food_id)
        .bind(budget_id)
        .execute(&pool)
        .await
        .expect("seed Food category");
        let empty_id = uuid::Uuid::new_v4();
        sqlx::query(
            "INSERT INTO categories (id, budget_id, name, category_type) VALUES ($1, $2, 'Empty', 'expense')",
        )
        .bind(empty_id)
        .bind(budget_id)
        .execute(&pool)
        .await
        .expect("seed Empty category");
        sqlx::query(
            "INSERT INTO transactions (id, budget_id, category_id, amount, transaction_date, description) \
             VALUES ($1, $2, $3, 12.5, NOW(), 'grocery run')",
        )
        .bind(uuid::Uuid::new_v4())
        .bind(budget_id)
        .bind(food_id)
        .execute(&pool)
        .await
        .expect("seed transaction");

        // 1. Populated category: the reply must name the category and the
        // logged transaction, and must NOT read like a mutation ("System
        // Update" success/warning banner never applies to a read).
        let resp = chat_endpoint(
            State(state.clone()),
            Extension(owner_id),
            Json(ChatRequest {
                message: "show me transactions in Food".to_string(),
                budget_id: Some(budget_id),
                conversation_id: None,
                locale: None,
            }),
        )
        .await
        .expect("list transactions (populated) chat call returns Ok");
        assert!(
            resp.0.response.contains("grocery run"),
            "populated reply must include the transaction description, got: {}",
            resp.0.response
        );
        assert!(
            resp.0.response.contains("Food"),
            "populated reply must name the category, got: {}",
            resp.0.response
        );

        // 2. Empty category: an explicit empty-result message, never a raw
        // list of some other category's transactions.
        let resp = chat_endpoint(
            State(state.clone()),
            Extension(owner_id),
            Json(ChatRequest {
                message: "show me transactions in Empty".to_string(),
                budget_id: Some(budget_id),
                conversation_id: None,
                locale: None,
            }),
        )
        .await
        .expect("list transactions (empty) chat call returns Ok");
        assert!(
            resp.0.response.contains("No transactions found"),
            "empty-category reply must be the explicit empty-result message, got: {}",
            resp.0.response
        );
        assert!(
            !resp.0.response.contains("grocery run"),
            "empty-category reply must never leak another category's transactions, got: {}",
            resp.0.response
        );

        // 3. Unresolvable category name: a clear "no such category" message,
        // never a silent fallback to any transaction list.
        let resp = chat_endpoint(
            State(state.clone()),
            Extension(owner_id),
            Json(ChatRequest {
                message: "show me transactions in Nonexistent".to_string(),
                budget_id: Some(budget_id),
                conversation_id: None,
                locale: None,
            }),
        )
        .await
        .expect("list transactions (not found) chat call returns Ok");
        assert!(
            resp.0.response.contains("couldn't find a category named 'Nonexistent'"),
            "unresolvable category reply must be the explicit not-found message, got: {}",
            resp.0.response
        );
        assert!(
            !resp.0.response.contains("grocery run"),
            "unresolvable category reply must never leak the Food category's transactions, got: {}",
            resp.0.response
        );

        // Cleanup.
        sqlx::query("DELETE FROM users WHERE id = $1")
            .bind(owner_id)
            .execute(&pool)
            .await
            .expect("cleanup");
    }

    #[test]
    fn category_not_found_message_names_the_category() {
        assert_eq!(
            category_not_found_message("Foo"),
            "I couldn't find a category named 'Foo' in the active budget."
        );
    }

    #[test]
    fn format_affordability_message_no_limit_configured_never_says_unaffordable() {
        let row = crate::budget::CategoryTableRow {
            id: Uuid::new_v4(),
            name: "Entertainment".to_string(),
            category_type: "expense".to_string(),
            category_limit: None,
            spent: 40.0,
            is_fund: false,
            fund_balance: 0.0,
            rollover_enabled: false,
            linked_budget_id: None,
        };
        let msg = format_affordability_message("Entertainment", &row, 50.0);
        assert!(msg.contains("no cap"), "expected a 'no cap' message, got: {}", msg);
        assert!(!msg.to_lowercase().contains("unaffordable"));
        assert!(!msg.starts_with("No"), "a no-limit category must never answer 'No', got: {}", msg);
    }

    #[test]
    fn format_affordability_message_fund_with_no_limit_still_says_no_cap() {
        // A fund enabled before any limit was ever set: category_limit is None even though
        // fund_balance is nonzero. The limit's absence must short-circuit BEFORE
        // fund_effective_limit is ever consulted (nels#302 spec A3/Risks).
        let row = crate::budget::CategoryTableRow {
            id: Uuid::new_v4(),
            name: "Entertainment".to_string(),
            category_type: "expense".to_string(),
            category_limit: None,
            spent: 0.0,
            is_fund: true,
            fund_balance: 500.0,
            rollover_enabled: false,
            linked_budget_id: None,
        };
        let msg = format_affordability_message("Entertainment", &row, 50.0);
        assert!(msg.contains("no cap"), "expected a 'no cap' message, got: {}", msg);
    }

    #[test]
    fn format_affordability_message_affordable_says_yes_with_numbers() {
        let row = crate::budget::CategoryTableRow {
            id: Uuid::new_v4(),
            name: "Entertainment".to_string(),
            category_type: "expense".to_string(),
            category_limit: Some(200.0),
            spent: 80.0,
            is_fund: false,
            fund_balance: 0.0,
            rollover_enabled: false,
            linked_budget_id: None,
        };
        let msg = format_affordability_message("Entertainment", &row, 50.0);
        assert!(msg.starts_with("Yes"), "got: {}", msg);
        assert!(msg.contains("200.00"), "must state the limit, got: {}", msg);
        assert!(msg.contains("80.00"), "must state spent, got: {}", msg);
        assert!(msg.contains("120.00"), "must state remaining, got: {}", msg);
        assert!(msg.contains("50.00"), "must state the requested amount, got: {}", msg);
    }

    #[test]
    fn format_affordability_message_unaffordable_says_no_with_overage() {
        let row = crate::budget::CategoryTableRow {
            id: Uuid::new_v4(),
            name: "Entertainment".to_string(),
            category_type: "expense".to_string(),
            category_limit: Some(200.0),
            spent: 160.0,
            is_fund: false,
            fund_balance: 0.0,
            rollover_enabled: false,
            linked_budget_id: None,
        };
        let msg = format_affordability_message("Entertainment", &row, 50.0);
        assert!(msg.starts_with("No"), "got: {}", msg);
        assert!(msg.contains("10.00"), "must state the $10 overage, got: {}", msg);
        assert!(msg.contains("40.00"), "must state remaining ($40), got: {}", msg);
    }

    #[test]
    fn format_affordability_message_fund_uses_effective_limit() {
        // limit 100 + fund_balance 50 = effective 150; spent 100 -> remaining 50; requesting 50
        // is exactly affordable only because the fund balance was added in.
        let row = crate::budget::CategoryTableRow {
            id: Uuid::new_v4(),
            name: "Groceries".to_string(),
            category_type: "expense".to_string(),
            category_limit: Some(100.0),
            spent: 100.0,
            is_fund: true,
            fund_balance: 50.0,
            rollover_enabled: false,
            linked_budget_id: None,
        };
        let msg = format_affordability_message("Groceries", &row, 50.0);
        assert!(msg.starts_with("Yes"), "got: {}", msg);
        assert!(msg.contains("150.00"), "must state the fund-effective limit, got: {}", msg);
    }

    #[test]
    fn offline_category_affordability_action_output_feeds_format_affordability_message_correctly() {
        // End-to-end (offline-router -> formatter) without a database: simulates what
        // chat_endpoint's offline branch + CATEGORY_AFFORDABILITY match arm do together, using a
        // hand-built CategoryTableRow standing in for what resolve_category_balance would return.
        let (name, amount) = offline_category_affordability_action("Can I spend $50 on Entertainment?")
            .expect("must match the core affordability phrasing");
        assert_eq!(name, "Entertainment");
        let requested = amount.expect("a dollar figure was present in the message");

        let row = crate::budget::CategoryTableRow {
            id: Uuid::new_v4(),
            name: name.clone(),
            category_type: "expense".to_string(),
            category_limit: Some(200.0),
            spent: 80.0,
            is_fund: false,
            fund_balance: 0.0,
            rollover_enabled: false,
            linked_budget_id: None,
        };
        let msg = format_affordability_message(&row.name, &row, requested);
        assert!(msg.starts_with("Yes"), "got: {}", msg);
        assert!(msg.contains("120.00"), "must state remaining, got: {}", msg);
    }

    fn test_row(name: &str, category_type: &str, limit: Option<f64>, spent: f64) -> crate::budget::CategoryTableRow {
        crate::budget::CategoryTableRow {
            id: Uuid::new_v4(),
            name: name.to_string(),
            category_type: category_type.to_string(),
            category_limit: limit,
            spent,
            is_fund: false,
            fund_balance: 0.0,
            rollover_enabled: false,
            linked_budget_id: None,
        }
    }

    #[test]
    fn render_categories_context_shows_period_windowed_spend_not_lifetime() {
        // The whole point of nels#282: the rendered "Spent/Earned" figure must
        // be exactly whatever `spent` the (already period-windowed) row
        // carries — this function must never re-sum or otherwise touch it.
        let rows = vec![test_row("Entertainment", "expense", Some(250.0), 66.0)];
        let (text, limit) = render_categories_context(
            &rows,
            &std::collections::HashSet::new(),
            &std::collections::HashMap::new(),
            None,
            "time_based",
            false,
        );
        assert!(
            text.contains("Entertainment [expense] - Spent/Earned: $66.00"),
            "expected period-windowed $66.00, got: {text}"
        );
        assert!(!text.contains("1147.82"), "must never show a lifetime figure");
        assert_eq!(limit, 250.0);
    }

    #[test]
    fn render_categories_context_rollover_line_unchanged_by_windowing_fix() {
        // AC bullet 3 (nels#282): rollover annotations must be byte-for-byte
        // identical to what the pre-fix inline loop rendered for the same
        // inputs — the windowing fix touches ONLY the Spent/Earned figure.
        let mut row = test_row("Groceries", "expense", Some(200.0), 50.0);
        row.rollover_enabled = true;
        let mut cat_prev_map = std::collections::HashMap::new();
        cat_prev_map.insert(row.id, 30.0); // previous-period spend, for the carry calc
        let (text, _limit) = render_categories_context(
            &[row],
            &std::collections::HashSet::new(),
            &std::collections::HashMap::new(),
            Some(&cat_prev_map),
            "time_based",
            true, // b_rollover on
        );
        // carried = max(0, base - prev_spent) = max(0, 200 - 30) = 170
        assert!(
            text.contains("Rollover: on | Carried: $170.00"),
            "expected unchanged rollover annotation, got: {text}"
        );
    }

    #[test]
    fn render_categories_context_shows_unavailable_when_cat_prev_map_is_none() {
        // nels#477: a failed previous-period spend read (None cat_prev_map)
        // must render the carry as "unavailable" rather than silently $0.00.
        let mut row = test_row("Groceries", "expense", Some(200.0), 50.0);
        row.rollover_enabled = true;
        let (text, _limit) = render_categories_context(
            &[row],
            &std::collections::HashSet::new(),
            &std::collections::HashMap::new(),
            None,
            "time_based",
            true, // b_rollover on
        );
        assert!(
            text.contains("Carried: unavailable (spend data unavailable)"),
            "expected 'Carried: unavailable' when cat_prev_map is None, got: {text}"
        );
        // Unlike the $170.00 carry we'd compute from a real map, None must
        // never produce a dollar figure — the model would be reasoning off a
        // silently-wrong number.
        assert!(!text.contains("Carried: $"), "a None cat_prev_map must never produce a computed dollar carry, got: {text}");
    }

    #[test]
    fn render_categories_context_fund_line_unchanged_by_windowing_fix() {
        // AC bullet 3 (nels#282): fund annotations must be unchanged too.
        let mut row = test_row("Entertainment", "expense", Some(250.0), 66.0);
        row.is_fund = true;
        row.fund_balance = 40.0;
        let (text, _limit) = render_categories_context(
            &[row],
            &std::collections::HashSet::new(),
            &std::collections::HashMap::new(),
            None,
            "time_based",
            false,
        );
        assert!(
            text.contains("Fund: on | Balance: $40.00 | Effective limit: $290.00"),
            "expected unchanged fund annotation ($250 + $40 = $290 effective), got: {text}"
        );
    }

    #[test]
    fn render_categories_context_zero_spend_category_still_appears() {
        let rows = vec![test_row("Unused", "expense", Some(100.0), 0.0)];
        let (text, _limit) = render_categories_context(
            &rows,
            &std::collections::HashSet::new(),
            &std::collections::HashMap::new(),
            None,
            "time_based",
            false,
        );
        assert!(
            text.contains("Unused [expense] - Spent/Earned: $0.00"),
            "a zero-spend-this-period category must still render, got: {text}"
        );
    }

    #[test]
    fn render_categories_context_income_and_savings_rows_get_no_rollover_or_fund_annotation_and_are_excluded_from_b_limit() {
        // Plan-review gap fix (nels#282): AC bullet 3 ("income/savings/fund/
        // rollover figures unchanged") was previously only exercised with
        // expense-type rows (fund/rollover categories are expense-only by
        // schema CHECK constraint anyway). This pins the OTHER half of that
        // claim: a non-expense row's Spent/Earned figure still reflects the
        // period-windowed `spent` verbatim, it never gets a "Rollover: ..." /
        // "Fund: ..." suffix (the annotation branch is gated on
        // `category_type == "expense"`), and it is excluded from the
        // authoritative expense-only `b_limit` sum — so a future edit that
        // widened the rollover/fund guard or the b_limit accumulation to
        // cover non-expense types would fail this test immediately.
        let income_row = test_row("Salary", "income", None, 500.0);
        let savings_row = test_row("Emergency Fund", "savings", Some(1000.0), 200.0);
        let expense_row = test_row("Entertainment", "expense", Some(250.0), 66.0);
        let (text, limit) = render_categories_context(
            &[income_row, savings_row, expense_row],
            &std::collections::HashSet::new(),
            &std::collections::HashMap::new(),
            Some(&std::collections::HashMap::new()),
            "time_based",
            true, // b_rollover on — if the guard were ever wrong, income/savings would show it
        );
        // The full line, ending in "\n" right after limit_str, is asserted
        // verbatim — if rollover_str were ever non-empty for a non-expense
        // row (the exact regression this test guards against), the line
        // would instead read "...No limit | Rollover: ...\n" and this
        // `contains` check would fail, since "No limit" would no longer be
        // immediately followed by the newline.
        assert!(
            text.contains("Salary [income] - Spent/Earned: $500.00 No limit\n"),
            "income row must render its own period spend with NO rollover/fund suffix, got: {text}"
        );
        assert!(
            text.contains("Emergency Fund [savings] - Spent/Earned: $200.00 (Limit: $1000.00)\n"),
            "savings row must render its own period spend with NO rollover/fund suffix, got: {text}"
        );
        // b_limit sums ONLY expense category_limit values (500/1000 from
        // income/savings must not leak in) — matches Entertainment's own 250.
        assert_eq!(limit, 250.0, "income/savings limits must be excluded from the expense-only b_limit sum");
    }

    #[test]
    fn imported_source_suffix_covers_manual_precedence_and_last4() {
        use uuid::Uuid;
        let acct = Some(Uuid::new_v4());
        assert_eq!(imported_source_suffix(None, Some("Chase"), Some("Chase Bank"), Some("1234")), "");
        assert_eq!(
            imported_source_suffix(acct, Some("Chase Checking"), Some("Chase Bank"), Some("1234")),
            " · 🔗 imported from Chase Checking ••1234"
        );
        assert_eq!(
            imported_source_suffix(acct, None, Some("Chase Bank"), Some("1234")),
            " · 🔗 imported from Chase Bank ••1234"
        );
        assert_eq!(
            imported_source_suffix(acct, Some("   "), Some("Chase Bank"), None),
            " · 🔗 imported from Chase Bank"
        );
        assert_eq!(
            imported_source_suffix(acct, None, None, None),
            " · 🔗 imported from linked account"
        );
        assert_eq!(
            imported_source_suffix(acct, Some("Chase"), None, Some("  ")),
            " · 🔗 imported from Chase"
        );
        // A whitespace-only institution_name (display absent) also falls through
        // to the generic label — non_blank is applied to every name field.
        assert_eq!(
            imported_source_suffix(acct, None, Some("   "), None),
            " · 🔗 imported from linked account"
        );
        // Both names blank but last4 known: generic label keeps the last4 tail.
        assert_eq!(
            imported_source_suffix(acct, None, None, Some("1234")),
            " · 🔗 imported from linked account ••1234"
        );
    }

    #[test]
    fn format_recent_transaction_line_marks_imported_and_manual() {
        use uuid::Uuid;
        let d = chrono::DateTime::parse_from_rfc3339("2026-07-01T00:00:00Z").unwrap().with_timezone(&chrono::Utc);
        // Imported: marker + source label appended after Desc.
        assert_eq!(
            format_recent_transaction_line(
                d, "Food", 4.5, "Coffee",
                Some(Uuid::new_v4()), Some("Chase Checking"), Some("Chase"), Some("1234"), false,
            ),
            "- Date: 2026-07-01 | Cat: Food | Amt: $4.50 | Desc: Coffee · 🔗 imported from Chase Checking ••1234\n"
        );
        // Manual: byte-identical to the pre-#359 line.
        assert_eq!(
            format_recent_transaction_line(d, "Food", 12.0, "Cash lunch", None, None, None, None, false),
            "- Date: 2026-07-01 | Cat: Food | Amt: $12.00 | Desc: Cash lunch\n"
        );
        // Excluded (#374): the excluded marker trails after any imported marker.
        assert_eq!(
            format_recent_transaction_line(d, "Food", 12.0, "Card payoff", None, None, None, None, true),
            "- Date: 2026-07-01 | Cat: Food | Amt: $12.00 | Desc: Card payoff · 🚫 excluded from budget\n"
        );
    }

