    #[test]
    fn format_transactions_list_message_marks_imported_and_manual() {
        use uuid::Uuid;
        let d1 = chrono::DateTime::parse_from_rfc3339("2026-07-01T00:00:00Z").unwrap().with_timezone(&chrono::Utc);
        let d2 = chrono::DateTime::parse_from_rfc3339("2026-07-02T00:00:00Z").unwrap().with_timezone(&chrono::Utc);
        let acct = Some(Uuid::new_v4());
        // Mixed list: an imported row and a manual row, distinct dates so the
        // order-preservation contract stays verifiable.
        let rows = vec![
            TxListRow { description: "Coffee".into(), amount: 4.5, date: d2,
                external_account_id: acct, display_name: Some("Chase Checking".into()),
                institution_name: Some("Chase".into()), last4: Some("1234".into()), excluded_from_budget: false },
            TxListRow { description: "Cash lunch".into(), amount: 12.0, date: d1,
                external_account_id: None, display_name: None, institution_name: None, last4: None, excluded_from_budget: false },
        ];
        let msg = format_transactions_list_message("Food", &rows);
        assert!(msg.starts_with("Transactions in 'Food' (2 total):\n"));
        assert!(msg.contains("- Coffee — $4.50 (2026-07-02) · 🔗 imported from Chase Checking ••1234"));
        // Manual row unmarked and byte-identical to pre-#359 output.
        assert!(msg.contains("- Cash lunch — $12.00 (2026-07-01)\n"));
        assert!(!msg.contains("Cash lunch — $12.00 (2026-07-01) ·"));
        // Formatter preserves caller-supplied row order (the SQL query owns ordering).
        let coffee_pos = msg.find("Coffee").unwrap();
        let lunch_pos = msg.find("Cash lunch").unwrap();
        assert!(coffee_pos < lunch_pos, "message must preserve the rows' input order");
    }

