    // Builds an AppState around a LAZY pool that is never actually queried — the
    // `active_budget_id = None` guard in each helper returns before any DB call,
    // so these stay pure unit tests (no Postgres needed).
    fn lazy_state() -> super::AppState {
        let db = sqlx::postgres::PgPoolOptions::new()
            .connect_lazy("postgres://invalid:invalid@127.0.0.1:1/none")
            .expect("lazy pool");
        let cipher = std::sync::Arc::new(
            crate::crypto::SecretCipher::new(&[7u8; 32]).expect("build test cipher"),
        );
        super::AppState { db, cipher, webauthn: std::sync::Arc::new(crate::passkeys::WebauthnRegistry::for_test()) }
    }

